# Delegated handlers survive Markdown's innerHTML replacement during streaming
# and transcript paging. Never interpolate model text into executable script.
CODE_COPY_BRIDGE = r'''
<script>
(() => {
  if (window.harnessyCodeCopyInstalled) return;
  window.harnessyCodeCopyInstalled = true;
  let scheduled = false;
  function decorate() {
    scheduled = false;
    document.querySelectorAll('.hy-assistant pre, .hy-thinking-content pre').forEach(pre => {
      if (!pre.querySelector('code') || pre.querySelector(':scope > .hy-code-copy')) return;
      pre.classList.add('hy-copyable-code');
      const button = document.createElement('button');
      button.type = 'button'; button.className = 'hy-code-copy';
      button.textContent = 'Copy'; button.title = 'Copy this code block';
      button.setAttribute('aria-label', 'Copy code block');
      pre.appendChild(button);
    });
  }
  function schedule() {
    if (!scheduled) { scheduled = true; requestAnimationFrame(decorate); }
  }
  new MutationObserver(records => {
    if (records.some(record => [...record.addedNodes].some(node =>
      node.nodeType === 1 && !node.classList?.contains('hy-code-copy')))) schedule();
  }).observe(document.body, {subtree:true, childList:true});
  document.addEventListener('click', async event => {
    const button = event.target.closest?.('.hy-code-copy');
    if (!button) return;
    const pre = button.parentElement;
    if (!pre?.matches('.hy-assistant pre, .hy-thinking-content pre')) return;
    event.preventDefault(); event.stopPropagation();
    const text = pre.querySelector('code')?.textContent ?? '';
    try {
      let copied = false;
      if (navigator.clipboard?.writeText) {
        try { await navigator.clipboard.writeText(text); copied = true; } catch (_) {}
      }
      if (!copied) {
        const previousFocus = document.activeElement;
        const area = document.createElement('textarea'); area.value = text;
        area.style.cssText = 'position:fixed;opacity:0;pointer-events:none';
        document.body.appendChild(area); area.focus(); area.select();
        try { copied = document.execCommand('copy'); } finally {
          area.remove(); previousFocus?.focus?.({preventScroll:true});
        }
      }
      button.textContent = copied ? 'Copied' : 'Copy failed';
    } catch (_) { button.textContent = 'Copy failed'; }
    setTimeout(() => { if (button.isConnected) button.textContent = 'Copy'; }, 1600);
  });
  schedule();
})();
</script>
'''


# Browser transcript windowing. The initial tail is always bounded and the
# browser can replace it with overlapping pages while preserving a visible
# anchor. Unlike v0.2.30, durable and live rows share the proven single
# transcript container; paging fails open to a safe tail instead of blanking.
TRANSCRIPT_TAIL_MESSAGES = 48
TRANSCRIPT_PAGE_MESSAGES = 24
TRANSCRIPT_MAX_MESSAGES = 72
TRANSCRIPT_LIVE_COMPACT_EVENTS = 12


# Runtime objects are process-owned rather than page-owned. A browser reload
# creates a new HarnessyPage, but it must not kill PTYs or agent runs which are
# still alive in the HarnessyXO backend.
_TERMINAL_SESSIONS: dict[str, TerminalSession] = {}
_TERMINAL_START_TASKS: dict[str, asyncio.Task[Any]] = {}
_TERMINAL_ERRORS: dict[str, str] = {}
_TERMINAL_ERROR_CODES: dict[str, str] = {}
_TERMINAL_START_STAGES: dict[str, str] = {}
_FILE_OPERATION_TASKS: set[asyncio.Task[Any]] = set()
_NOTIFICATION_TASKS: set[asyncio.Task[Any]] = set()
_NTFY_REPLY_SUPERVISOR_TASK: asyncio.Task[Any] | None = None
_NTFY_REPLY_LISTENER_TASK: asyncio.Task[Any] | None = None
_NTFY_NOTIFICATION_SEQUENCE = 0
_AGENT_TASKS: dict[tuple[str, str], asyncio.Task[Any]] = {}
# Exact post-run file/memory revisions continue after a browser run releases
# its Stop button. They retain the project mutation lease but are not model
# runs: a new prompt may open normally and will wait at that lease if needed.
_PROJECT_REVISION_TASKS: dict[tuple[str, str], asyncio.Task[Any]] = {}
# Process-owned live agent snapshots let a newly rendered browser page attach
# to a run which started under an older transcript render (or even an older
# HarnessyPage after a browser refresh).  The backend remains authoritative;
# these snapshots contain only transient presentation state which is safe to
# replace from persisted chat messages whenever a model/tool step completes.
_AGENT_LIVE_STATES: dict[tuple[str, str], dict[str, Any]] = {}
# Text follow-ups sent while a chat is running wait here until the runner reaches
# a safe model/tool boundary. They are process-owned so a browser refresh does
# not lose steering messages.
_AGENT_FOLLOWUPS: dict[tuple[str, str], list[dict[str, Any]]] = {}
_AGENT_FOLLOWUP_OPEN: dict[tuple[str, str], bool] = {}
# Prevent two page timers from racing the same orphaned follow-up recovery.
_AGENT_FOLLOWUP_RECOVERING: set[tuple[str, str]] = set()
# Persisted whole-run queue workers are process-owned. Admission is through one
# global agent-slot pool; related parent/child projects never overlap.
_RUN_QUEUE_SUPERVISOR_TASK: asyncio.Task[Any] | None = None
_RUN_QUEUE_JOB_TASKS: dict[str, asyncio.Task[Any]] = {}
_RUN_QUEUE_TASK_JOB_IDS: dict[asyncio.Task[Any], str] = {}
_USER_STOPPED_TASKS: set[asyncio.Task[Any]] = set()
_RUN_QUEUE_RETRY_TASKS: dict[str, asyncio.Task[Any]] = {}
_RUN_QUEUE_WAKE = asyncio.Event()
_RUN_QUEUE_SNAPSHOT_OBSERVATIONS: dict[str, str] = {}
_RUN_QUEUE_ADMISSION_OBSERVATIONS: dict[tuple[str, str], str] = {}
# A process-owned rewind keeps other pages from submitting into the same chat
# until restoration and the intended queued-send handoff have finished.
_TIMELINE_REPLACEMENTS: dict[tuple[str, str], str] = {}
_TIMELINE_REPLACEMENT_JOBS: dict[tuple[str, str], TimelineReplacementJob] = {}
_EVENT_LOOP_WATCHDOG_TASK: asyncio.Task[Any] | None = None
# Shutdown reuses successfully prepared stores. It must never initialize or
# probe every registered workspace after the worker cancellation gate closes.
_RUNTIME_WORKSPACE_STORES: dict[str, WorkspaceStore] = {}
_RUNTIME_WORKSPACE_STORE_LOCK = threading.RLock()
_RUNTIME_WORKSPACE_PREPARE_LOCKS: dict[str, threading.Lock] = {}


def _prepare_runtime_workspace(
    root: str | Path, name: str | None = None, *, allow_replacement: bool = False, **kwargs: Any,
) -> WorkspaceStore:
    """Reuse an admitted live generation; initialize each cold workspace once.

    Normal chat commits change WAL and modification times. They must not cause
    a new full database copy, integrity scan or schema initialization whenever
    a chat starts or another browser page connects.
    """
    key = str(validate_workspace_root(root))
    options = dict(kwargs)
    if options.get('timeout') is None:
        options['timeout'] = workspace_preparation_timeout(root)
    budget = float(options['timeout'])
    started = time.monotonic()
    with _RUNTIME_WORKSPACE_STORE_LOCK:
        preparation_lock = _RUNTIME_WORKSPACE_PREPARE_LOCKS.setdefault(key, threading.Lock())
    if not preparation_lock.acquire(timeout=max(.1, budget)):
        raise WorkspaceDatabaseError('timed_out', reason='worker_timeout')
    try:
        with _RUNTIME_WORKSPACE_STORE_LOCK:
            cached = _RUNTIME_WORKSPACE_STORES.get(key)
        if cached is not None and not options.get('force'):
            try:
                with workspace_shared_access(cached.root, expected_generation=cached._workspace_generation):
                    require_workspace_not_quarantined(cached.root)
                    if name is not None and cached.name != name:
                        cached.set_name(name)
                log_event('harnessy', 'workspace_database_store_reused',
                          db_id=_database_identity(cached.db_path))
                return cached
            except WorkspaceDatabaseError as exc:
                if exc.reason in {'maintenance', 'recovery_pending'}:
                    raise
                if not allow_replacement:
                    raise
                with _RUNTIME_WORKSPACE_STORE_LOCK:
                    if _RUNTIME_WORKSPACE_STORES.get(key) is cached:
                        _RUNTIME_WORKSPACE_STORES.pop(key, None)
        remaining = budget - (time.monotonic() - started)
        if remaining <= 0:
            raise WorkspaceDatabaseError('timed_out', reason='worker_timeout')
        options['timeout'] = remaining
        log_event('harnessy', 'workspace_database_preparation_started',
                  db_id=_database_identity(Path(key) / '.harnessy' / 'workspace.db'),
                  timeout_seconds=options['timeout'])
        try:
            store = prepare_workspace_store(root, name, **options)
        except BaseException:
            with _RUNTIME_WORKSPACE_STORE_LOCK:
                _RUNTIME_WORKSPACE_STORES.pop(key, None)
            raise
        with _RUNTIME_WORKSPACE_STORE_LOCK:
            _RUNTIME_WORKSPACE_STORES[key] = store
        return store
    finally:
        preparation_lock.release()


def _prepared_runtime_workspaces() -> list[WorkspaceStore]:
    """Return prepared references without touching workspace storage."""
    with _RUNTIME_WORKSPACE_STORE_LOCK:
        return list(_RUNTIME_WORKSPACE_STORES.values())


async def _prepare_queued_workspace(root: str | Path, name: str) -> WorkspaceStore:
    """Drain a cancelled admission before releasing its queue worker.

    Cancelling to_thread does not stop its native-worker supervisor. Keeping
    the owned waiter alive ensures recovery's exclusive lease is requested
    only after this preparation has closed its shared lease.
    """
    waiter = asyncio.create_task(asyncio.to_thread(_prepare_runtime_workspace, root, name))
    try:
        return await asyncio.shield(waiter)
    except asyncio.CancelledError:
        while not waiter.done():
            try:
                await asyncio.shield(waiter)
            except asyncio.CancelledError:
                continue
            except Exception:
                break
        if waiter.done() and not waiter.cancelled():
            waiter.exception()
        raise


