async def _event_loop_watchdog() -> None:
    """Record material NiceGUI loop stalls without adding UI traffic."""
    loop = asyncio.get_running_loop()
    monitor = EventLoopStallMonitor(threading.get_ident(), log_event)
    monitor.start()
    expected = loop.time() + 1.0
    last_logged = 0.0
    try:
        while True:
            await asyncio.sleep(1.0)
            now = loop.time()
            monitor.beat()
            drift = max(0.0, now - expected)
            expected = now + 1.0
            if drift >= 0.75 and now - last_logged >= 3.0:
                last_logged = now
                log_event('runtime', 'event_loop_stall', drift_seconds=round(drift, 3))
    except asyncio.CancelledError:
        return
    finally:
        # The observer owns no UI/loop objects and must not survive shutdown.
        await asyncio.to_thread(monitor.stop)


def _ensure_event_loop_watchdog() -> None:
    global _EVENT_LOOP_WATCHDOG_TASK
    if _EVENT_LOOP_WATCHDOG_TASK is not None and not _EVENT_LOOP_WATCHDOG_TASK.done():
        return
    try:
        _EVENT_LOOP_WATCHDOG_TASK = asyncio.create_task(_event_loop_watchdog(), name='harnessy-event-loop-watchdog')
    except RuntimeError:
        _EVENT_LOOP_WATCHDOG_TASK = None


def _is_stale_ui_error(exc: BaseException) -> bool:
    text = str(exc).lower()
    return (
        ('parent element' in text and 'deleted' in text)
        or ('client has been deleted' in text)
        or ('client is disconnected' in text)
        or ('slot stack for this task is empty' in text)
        or ('current slot cannot be determined' in text)
    )


def _take_agent_followups(key: tuple[str, str], *, final: bool = False) -> list[dict[str, Any]]:
    rows = list(_AGENT_FOLLOWUPS.pop(key, []) or [])
    # Atomically close intake at the final model boundary only when there is
    # nothing left to deliver. If rows exist, the runner continues and keeps
    # accepting steering for its next safe boundary.
    _AGENT_FOLLOWUP_OPEN[key] = (not final) or bool(rows)
    return rows


def _track_project_revision_task(
    workspace_id: str, chat_id: str, task: asyncio.Task[Any] | None,
) -> None:
    """Keep detached history finalization alive and observable until settled."""
    if task is None:
        return
    key = (str(workspace_id), str(chat_id))
    _PROJECT_REVISION_TASKS[key] = task

    def settled(done: asyncio.Task[Any]) -> None:
        if _PROJECT_REVISION_TASKS.get(key) is done:
            _PROJECT_REVISION_TASKS.pop(key, None)
        try:
            done.exception()
        except asyncio.CancelledError:
            pass

    task.add_done_callback(settled)


