class HarnessyPage:
    def __init__(self, machine: MachineStore) -> None:
        self._page_id = uuid.uuid4().hex
        self.machine = machine
        self.settings = machine.load_settings()
        # Request-bound, server-only authentication capability. Never persist it
        # in UI session settings, browser storage, diagnostics or workspace data.
        self._accounts: Any | None = None
        self._username = ''
        self.registration: WorkspaceRegistration | None = None
        self.workspace: WorkspaceStore | None = None
        self._workspace_open_error: tuple[WorkspaceRegistration, str] | None = None
        self.workspace_cache: dict[str, WorkspaceStore] = {}
        self._workspace_load_failures: dict[str, Exception] = {}
        self.open_tabs: list[OpenTab] = []
        self._blocked_restore_tabs: dict[str, str] = {}
        self.active_tab_key: str | None = None
        self.sidebar_selected_chat: tuple[str, str] | None = None
        self.chat_runtime: dict[tuple[str, str], dict[str, str]] = {}
        self.terminal_sessions = _TERMINAL_SESSIONS
        self.terminal_start_tasks = _TERMINAL_START_TASKS
        self.terminal_errors = _TERMINAL_ERRORS
        self.terminal_error_codes = _TERMINAL_ERROR_CODES
        self.terminal_start_stages = _TERMINAL_START_STAGES
        self.terminal_counters: dict[str, int] = {}
        self.home_scope = ToolScope(HOME_SCOPE_ID, 'Home', Path.home().resolve())
        self.file_paths: dict[str, Path] = {}
        # Unsaved editor drafts are page-local on purpose: switching right-pane tabs must not
        # lose edits, while a process/browser restart never invents persistence the user did not Save.
        self.file_editor_states: dict[str, dict[str, Any]] = {}
        # Composer drafts are different from file-editor drafts: the user explicitly expects each
        # Project / Chat to retain its own unsent message across tab switches and browser refreshes.
        # The workspace DB is authoritative; this cache keeps ordinary remounts cheap.
        self.chat_composer_drafts: dict[tuple[str, str], str] = {}
        self._timeline_deletion_applied: dict[tuple[str, str], str] = {}
        self._composer_draft_write_errors: set[tuple[str, str]] = set()
        self._composer_owner: tuple[str, str] | None = None
        self.file_clipboard: dict[str, dict[str, Any]] = {}
        self.file_selections: dict[str, list[Path]] = {}
        self.environment_subtabs: dict[str, str] = {}
        self.vm_environment_selection: dict[str, str] = {}
        self.busy_tabs: set[str] = set()
        self._tab_busy_signature: tuple[tuple[str, bool], ...] = ()
        self._favicon_busy_state: bool | None = None
        self._queued_followup_expanded: set[tuple[str, str, str]] = set()
        self.running_tasks: dict[str, asyncio.Task[Any]] = {}
        self.active_workspace_jobs: set[str] = set()
        self.active_chat_jobs: set[tuple[str, str]] = set()

        self.sidebar_workspace_area = None
        self.sidebar_chat_area = None
        self.sidebar_archive_area = None
        self.page_overlay_root = None
        self.sidebar_workspace_header = None
        self.sidebar_archive_header = None
        self.sidebar_section_bodies: dict[str, Any] = {}
        self.sidebar_section_chevrons: dict[str, Any] = {}
        self.sidebar_section_collapsed: dict[str, bool] = {'workspaces': False, 'chats': False, 'archives': True}
        self.sidebar_workspace_busy_icons: dict[str, Any] = {}
        self.sidebar_workspace_queue_badges: dict[str, tuple[Any, Any]] = {}
        self.sidebar_workspace_rows: dict[str, Any] = {}
        self.sidebar_workspace_buttons: dict[str, Any] = {}
        self.sidebar_workspace_details: dict[str, Any] = {}
        self.sidebar_chat_rows: dict[tuple[str, str], Any] = {}
        self.sidebar_chat_title_controls: dict[tuple[str, str], tuple[Any, Any]] = {}
        self.sidebar_chat_busy_icons: dict[tuple[str, str], Any] = {}
        self.sidebar_chat_run_indicators: dict[tuple[str, str], list[dict[str, Any]]] = {}
        self.sidebar_chat_busy_controls: dict[tuple[str, str], list[tuple[Any, bool]]] = {}
        self._sidebar_agent_slots: dict[str, Any] = {}
        self._sidebar_completion_holds: list[dict[str, Any]] = []
        self._sidebar_run_queue_jobs: dict[tuple[str, str], list[dict[str, Any]]] = {}
        self.new_chat_area = None
        self.tabbar_area = None
        self.tab_content_area = None
        self.composer = None
        self.composer_upload = None
        self.pending_attachment_area = None
        self.queued_followup_area = None
        self.queued_run_area = None
        self.timeline_replacement_area = None
