    def _set_browser_upload_target(self, ws: WorkspaceStore, chat_id: str, composer_id: str | None = None) -> None:
        payload = json.dumps({
            'workspace_id': ws.id if composer_id else '',
            'chat_id': chat_id if composer_id else '',
            'composer_id': composer_id,
        })
        owner = self.composer or self.message_area
        if owner is not None and self._ui_elements_alive(owner):
            owner.client.run_javascript(f'window.harnessyActiveUpload = {payload};', timeout=2.0)

    def _browser_attachment_uploaded(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        if not data.get('ok'):
            ui.notify(f"Attachment failed: {data.get('error','unknown error')}", type='negative')
            return
        if data.get('archive'):
            ui.notify(
                f"Archive extracted into Project files: {data.get('imported_name') or data.get('name')}",
                type='positive',
            )
        workspace_id = str(data.get('workspace_id') or '')
        chat_id = str(data.get('chat_id') or '')
        if self.active_tab_key == self._chat_tab_key(workspace_id, chat_id):
            reg = self._find_reg(workspace_id)
            if reg is not None:
                self._draw_pending_attachments(self._load_workspace(reg), chat_id)

    def _set_file_explorer_target(self, ws: WorkspaceStore, current: Path, client) -> None:
        # A read-only project/history explorer has no browser upload target, so
        # drag/drop cannot mutate the displayed snapshot or archived tree.
        readonly = isinstance(ws, ToolScope) and ws.read_only
        payload = json.dumps({'workspace_id': ws.id, 'current_path': None if readonly else str(current), 'read_only': readonly})
        self.file_selections[ws.id] = []
        client.run_javascript(
            f'window.harnessySetFileExplorerTarget ? window.harnessySetFileExplorerTarget({payload}) : (window.harnessyFileExplorer = {payload});',
            timeout=2.0,
        )

    def _browser_file_uploaded(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        if data.get('batch_done'):
            uploaded = int(data.get('uploaded') or 0)
            errors = list(data.get('errors') or [])
            if uploaded:
                ui.notify(f"Uploaded {uploaded} item{'s' if uploaded != 1 else ''}", type='positive')
            if data.get('cancelled'):
                ui.notify('Upload cancelled', type='warning')
            if errors:
                detail = '; '.join(str(x) for x in errors[:3])
                if len(errors) > 3:
                    detail += f'; +{len(errors) - 3} more'
                ui.notify(f'Upload errors: {detail}', type='negative', timeout=9000)
            if self.active_tab_key and self.active_tab_key.startswith('files:'):
                self.refresh_tabs()
            return
        if not data.get('ok'):
            ui.notify(f"Upload failed: {data.get('error','unknown error')}", type='negative')
            return
        if data.get('final'):
            ui.notify(f"Uploaded {Path(str(data['final'])).name}", type='positive')
        if self.active_tab_key and self.active_tab_key.startswith('files:'):
            self.refresh_tabs()

    def _browser_file_move(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        wid = str(data.get('workspace_id') or '')
        ws = self._scope_for_id(wid)
        if ws is None:
            return
        if isinstance(ws, ToolScope) and ws.read_only:
            ui.notify('This Project Files panel is read-only. Use Workspace Files to make human edits.', type='warning')
            return
        try:
            source = Path(str(data.get('source') or '')).expanduser().resolve()
            destination = Path(str(data.get('destination') or '')).expanduser().resolve()
            if not self._file_path_in_scope(ws, source) or not self._file_path_in_scope(ws, destination):
                raise ValueError('File move/copy is outside this File Explorer scope')
            if not source.exists():
                raise FileNotFoundError(source)
            if not destination.is_dir():
                raise ValueError('Drop destination is not a directory')
            if source == destination or (source.is_dir() and destination.is_relative_to(source)):
                raise ValueError('Cannot move/copy a folder into itself')
            target = _unique_external_path(destination / source.name)
            if not self._file_path_in_scope(ws, target):
                raise ValueError('File destination is outside this File Explorer scope')
            def work():
                if bool(data.get('copy')):
                    if source.is_dir() and not source.is_symlink():
                        shutil.copytree(source, target)
                    else:
                        shutil.copy2(source, target, follow_symlinks=False)
                    return f'Copied {source.name}'
                shutil.move(str(source), str(target))
                return f'Moved {source.name}'
            self._launch_file_operation(ws, 'Copy' if data.get('copy') else 'Move', work, lambda message: message)
        except Exception as exc:
            ui.notify(f'File operation failed: {exc}', type='negative', timeout=7000)

    def _browser_file_parent_open(self, e) -> None:
        # The path identifies the row for browser click-pair bookkeeping only.
        # Resolve each completed pair against current state, just like toolbar Up.
        self._browser_file_up(e)

    def _browser_file_up(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        wid = str(data.get('workspace_id') or '')
        owner_tab_key = str(data.get('tab_key') or '')
        if not owner_tab_key or owner_tab_key != self.active_tab_key:
            return
        ws = self._scope_for_id(wid)
        if ws is None:
            return
        self._file_up(ws, owner_tab_key=owner_tab_key)

    def _browser_file_selection(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        wid = str(data.get('workspace_id') or '')
        ws = self._scope_for_id(wid)
        if ws is None:
            return
        paths: list[Path] = []
        for raw in data.get('paths') or []:
            try:
                path = Path(str(raw)).expanduser().absolute()
                if self._file_path_in_scope(ws, path):
                    paths.append(path)
            except Exception:
                continue
        self.file_selections[wid] = paths

    def _file_targets(self, ws: WorkspaceStore | ToolScope, fallback: Path | None = None) -> list[Path]:
        selected = [
            p for p in self.file_selections.get(ws.id, [])
            if (p.exists() or p.is_symlink()) and self._file_path_in_scope(ws, p)
        ]
        if fallback is not None:
            selected_path = fallback.expanduser().absolute()
            if not self._file_path_in_scope(ws, selected_path):
                return []
            if selected_path in selected:
                return selected
            return [selected_path]
        return selected

    def _browser_file_action(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        wid = str(data.get('workspace_id') or '')
        action = str(data.get('action') or '')
        ws = self._scope_for_id(wid)
        if ws is None:
            return
        if isinstance(ws, ToolScope) and ws.read_only and action not in {'open', 'clear', 'copy'}:
            ui.notify('This Project Files panel is read-only.', type='warning')
            return
        paths: list[Path] = []
        for raw in data.get('paths') or []:
            try:
                p = Path(str(raw)).expanduser().absolute()
                if (p.exists() or p.is_symlink()) and self._file_path_in_scope(ws, p):
                    paths.append(p)
            except Exception:
                continue
        if paths:
            self.file_selections[wid] = paths
        targets = paths or self._file_targets(ws)
        current = self.file_paths.get(wid, self._file_scope_root(ws))
        if action == 'copy' and targets:
            self._file_set_clipboard(ws, targets, 'copy')
        elif action == 'cut' and targets:
            self._file_set_clipboard(ws, targets, 'cut')
        elif action == 'paste':
            self._file_paste(ws, current)
        elif action == 'delete' and targets:
            self._file_delete(ws, targets)
        elif action == 'open' and len(targets) == 1:
            self._file_open(ws, targets[0])
        elif action == 'rename' and len(targets) == 1:
            self._file_rename(targets[0])
        elif action == 'rename' and len(targets) > 1:
            ui.notify('Rename works on one selected item at a time.', type='warning')
        elif action == 'clear':
            self.file_selections[wid] = []

    def _browser_sidebar_reorder(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        kind = str(data.get('kind') or '')
        ids = [str(x) for x in (data.get('ids') or []) if str(x)]
        if not ids:
            return
        try:
            if kind == 'workspace':
                self.machine.reorder_workspaces(ids)
            elif kind == 'chat' and self.workspace:
                self.workspace.reorder_chats(ids, archived=False)
            elif kind == 'archive' and self.workspace:
                self.workspace.reorder_chats(ids, archived=True)
            else:
                return
            self.refresh_sidebar()
        except Exception as exc:
            ui.notify(f'Could not save order: {exc}', type='negative')
            self.refresh_sidebar()

    def _browser_sidebar_chat_move(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        chat_id = str(data.get('chat_id') or '')
        source_kind = str(data.get('source_kind') or '')
        target_kind = str(data.get('target_kind') or '')
        ids = [str(x) for x in (data.get('ids') or []) if str(x)]
        if not self.workspace or not chat_id or source_kind not in {'chat', 'archive'} or target_kind not in {'chat', 'archive'}:
            return
        if source_kind != target_kind:
            ui.notify(
                'Archive is a permanent family operation. Use the Project / Chat menu to archive; '
                'archived records cannot return to Active.',
                type='warning', timeout=7000,
            )
            self.refresh_sidebar()
            return
        try:
            if ids:
                self.workspace.reorder_chats(ids, archived=(target_kind == 'archive'))
            self.refresh_sidebar()
        except Exception as exc:
            ui.notify(f'Could not move chat: {exc}', type='negative')
            self.refresh_sidebar()

    def _browser_tab_reorder(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        keys = [str(x) for x in (data.get('keys') or []) if str(x)]
        if not keys:
            return
        by_key = {tab.key: tab for tab in self.open_tabs}
        ordered = [by_key[key] for key in keys if key in by_key]
        ordered.extend(tab for tab in self.open_tabs if tab.key not in keys)
        if [tab.key for tab in ordered] == [tab.key for tab in self.open_tabs]:
            return
        self.open_tabs = ordered
        self._save_ui_session()

    def _browser_reconnected(self, e) -> None:
        self._favicon_busy_state = None
        self._sync_tab_activity_ui()
        self._backend_checked_at = 0.0
        self._request_backend_health()
        data = e.args if isinstance(e.args, dict) else {}
        log_event(
            'harnessy', 'browser_reconnected',
            outage_ms=int(data.get('outage_ms') or 0),
            reason=str(data.get('reason') or ''),
            attempts=int(data.get('attempts') or 0),
        )

    def _browser_transcript_follow(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        workspace_id, chat_id = str(data.get('workspace_id') or ''), str(data.get('chat_id') or '')
        if (self.active_tab_key != self._chat_tab_key(workspace_id, chat_id)
                or str(data.get('render_token')) != str(self._chat_render_generation)):
            return
        self._transcript_following[(workspace_id, chat_id)] = data.get('following') is True

    @staticmethod
    async def _transcript_javascript(client: Any, code: str, *, timeout: float) -> Any:
        # NiceGUI waits for client.connected() BEFORE its JS-response timeout.
        # Bound the entire call so a disconnected page cannot hold a runner's
        # persistence/cleanup boundary forever while its RE work is complete.
        if hasattr(client, 'has_socket_connection') and not client.has_socket_connection:
            return None
        return await asyncio.wait_for(client.run_javascript(code, timeout=timeout), timeout=timeout + 0.5)

    async def _refresh_transcript_preserving_view(self, ws: WorkspaceStore, chat_id: str) -> bool:
        """A persistence-boundary update with an explicit browser acknowledgement.

        Never guess where the user is reading from scrollHeight. The browser
        owns the anchor; the server owns the bounded message records. A stale
        response cannot mutate a replacement chat/page. Backend work continues
        even when presentation is disconnected or another page request is busy.
        """
        key = (ws.id, chat_id)
        area = self.message_area
        generation = self._chat_render_generation
        if (area is None or not self._ui_elements_alive(area)
                or self.active_tab_key != self._chat_tab_key(*key)
                or key in self._transcript_window_busy):
            return False
        self._transcript_window_busy.add(key)
        owns_busy = True
        capture = None
        try:
            client = area.client
            capture = await self._transcript_javascript(client,
                'window.harnessyBeforeTranscriptUpdate && '
                f'window.harnessyBeforeTranscriptUpdate({json.dumps(ws.id)}, {json.dumps(chat_id)}, {generation});',
                timeout=2.0,
            )
            if (not isinstance(capture, dict) or generation != self._chat_render_generation
                    or self.message_area is not area or not self._ui_elements_alive(area)
                    or self.active_tab_key != self._chat_tab_key(*key)):
                return False
            if key in self._pending_transcript_navigation:
                # A newer explicit request owns the viewport. Its request ID
                # supersedes this capture, so drain it without replaying the
                # refresh's older window or anchor first.
                return False
            following = capture.get('following') is True
            anchor_id = str(capture.get('anchor_id') or '')
            live_state = _AGENT_LIVE_STATES.get(key) or {}
            anchor_id = (live_state.get('anchor_aliases') or {}).get(anchor_id, anchor_id)
            previous = self._transcript_windows.get(key)
            previous = dict(previous) if previous is not None else None
            previous_following = self._transcript_following.get(key, True)
            base_id = anchor_id.split('--segment-', 1)[0]
            locate_id = base_id if (not following and base_id and base_id not in self._history_rows) else ''
            prepared = await asyncio.to_thread(
                self._read_transcript_snapshot, ws, chat_id, previous,
                following=following, reset=following or anchor_id.startswith('live-'),
                locate_message_id=locate_id,
            )
            # Worker reads have no page side effects. A tab/render change or a
            # newer navigation request must win over this old browser capture.
            if (generation != self._chat_render_generation or self.message_area is not area
                    or not self._ui_elements_alive(area)
                    or self.active_tab_key != self._chat_tab_key(*key)
                    or key in self._pending_transcript_navigation):
                return False
            if (self._transcript_windows.get(key) != previous
                    or self._transcript_following.get(key, True) != previous_following):
                raise RuntimeError('Transcript view changed during background read')
            self._transcript_following[key] = following
            self._draw_messages(ws, chat_id, reset_window=following, prepared=prepared)
            # The server mutation is committed. The browser remains locked until
            # its acknowledgement restores layout; release here so a queued Jump
            # emitted from that acknowledgement cannot be discarded as busy.
            self._transcript_window_busy.discard(key)
            owns_busy = False
            completed = await self._transcript_javascript(client,
                'window.harnessyTranscriptWindowRendered && '
                f'window.harnessyTranscriptWindowRendered({json.dumps(anchor_id)}, '
                f'{float(capture.get("anchor_offset") or 0)!r}, "refresh", true, {generation}, '
                f'{int(capture.get("request_id") or 0)}, {str(following).lower()});',
                timeout=3.0,
            )
            return completed is True
        except (Exception, asyncio.CancelledError) as exc:
            if not _is_stale_ui_error(exc):
                log_event('harnessy', 'transcript_refresh_deferred', workspace_id=ws.id, chat_id=chat_id,
                          error=f'{type(exc).__name__}: {exc}')
            # Once the browser accepted a capture, it owns a transaction too.
            # End that transaction explicitly on failure; its load timeout is
            # informational and must not unlock an unacknowledged mutation.
            if (isinstance(capture, dict) and generation == self._chat_render_generation
                    and self.message_area is area and self._ui_elements_alive(area)
                    and self.active_tab_key == self._chat_tab_key(*key)):
                self._transcript_window_busy.discard(key)
                owns_busy = False
                try:
                    await self._transcript_javascript(area.client,
                        'window.harnessyTranscriptWindowRendered && '
                        f'window.harnessyTranscriptWindowRendered({json.dumps(str(capture.get("anchor_id") or ""))}, '
                        f'{float(capture.get("anchor_offset") or 0)!r}, "refresh", false, {generation}, '
                        f'{int(capture.get("request_id") or 0)}, false, false);', timeout=3.0)
                except Exception as ack_exc:
                    if not _is_stale_ui_error(ack_exc):
                        log_event('harnessy', 'transcript_window_ack_deferred', error=str(ack_exc))
            if isinstance(exc, asyncio.CancelledError):
                raise
            return False
        finally:
            if owns_busy:
                self._transcript_window_busy.discard(key)
            await self._drain_transcript_navigation(key)

    async def _drain_transcript_navigation(self, key: tuple[str, str]) -> None:
        """Run the newest queued navigation after a presentation mutation ends."""
        if key in self._transcript_navigation_draining:
            return
        self._transcript_navigation_draining.add(key)
        try:
            while key not in self._transcript_window_busy:
                data = self._pending_transcript_navigation.pop(key, None)
                if data is None:
                    break
                await self._handle_transcript_window_request(data, queued=True)
        finally:
            self._transcript_navigation_draining.discard(key)

    async def _browser_transcript_window(self, e) -> None:
        """Read-only navigation; only off-window UI elements are unmounted."""
        data = e.args if isinstance(e.args, dict) else {}
        await self._handle_transcript_window_request(data)

    async def _handle_transcript_window_request(self, data: dict[str, Any], *, queued: bool = False) -> None:
        workspace_id, chat_id = str(data.get('workspace_id') or ''), str(data.get('chat_id') or '')
        direction = str(data.get('direction') or '').lower()
        anchor_id = str(data.get('anchor_id') or '')
        try:
            anchor_offset = float(data.get('anchor_offset') or 0.0)
            request_id = int(data.get('request_id') or 0)
        except (TypeError, ValueError):
            return
        if not math.isfinite(anchor_offset):
            return
        key = (workspace_id, chat_id)
        generation = self._chat_render_generation
        if (not workspace_id or not chat_id or direction not in {'older', 'newer', 'earliest', 'latest', 'locate'}
                or self.active_tab_key != self._chat_tab_key(*key)
                or str(data.get('render_token')) != str(generation)):
            return
        latest = self._transcript_navigation_latest.get(key)
        if latest is not None and latest[0] == generation and (
                request_id < latest[1] or (request_id == latest[1] and not queued)):
            return
        self._transcript_navigation_latest[key] = (generation, request_id)
        if key in self._transcript_window_busy:
            # A refresh can be awaiting browser anchor capture when this event
            # arrives. Dropping it leaves the browser locked without any ack.
            # Coalesce by request serial; never start overlapping row mutations.
            self._pending_transcript_navigation[key] = dict(data)
            return
        reg, area = self.machine.get_workspace(workspace_id), self.message_area
        if reg is None or area is None or not self._ui_elements_alive(area):
            return
        self._transcript_window_busy.add(key)
        owns_busy = True
        changed = False
        succeeded = False
        before_following = self._transcript_following.get(key, False)
        try:
            ws = self._load_workspace(reg)
            previous = self._transcript_windows.get(key)
            previous = dict(previous) if previous is not None else None
            before = dict(previous or {})
            prepared = await asyncio.to_thread(
                self._read_transcript_snapshot, ws, chat_id, previous,
                following=direction == 'latest', reset=direction == 'latest',
                locate_message_id=anchor_id if direction == 'locate' else '',
                direction=direction,
            )
            current = (generation == self._chat_render_generation and self.message_area is area
                       and self._ui_elements_alive(area)
                       and self.active_tab_key == self._chat_tab_key(*key)
                       and self._transcript_navigation_latest.get(key) == (generation, request_id)
                       and key not in self._pending_transcript_navigation)
            if not current:
                # A replacement render or newer request owns the UI. Drain the
                # latest queued intent after releasing this read-only operation.
                self._transcript_window_busy.discard(key)
                owns_busy = False
                await self._drain_transcript_navigation(key)
                return
            if self._transcript_windows.get(key) != previous:
                raise RuntimeError('Transcript view changed during background read')
            after = prepared['state']
            self._transcript_following[key] = direction == 'latest'
            changed = any(before.get(k) != after.get(k) for k in ('start', 'end', 'total'))
            if changed:
                # One-way handoff from direct live callbacks to the process-owned
                # reattach observer. Never let two renderers write the same rows.
                live_state = _AGENT_LIVE_STATES.get(key)
                if isinstance(live_state, dict) and bool(live_state.get('active')):
                    live_state['owner_detached'] = True
                    live_state['revision'] = int(live_state.get('revision') or 0) + 1
                self._live_sync_view = self._live_sync_tool_view = None
                self._draw_messages(ws, chat_id, prepared=prepared)
            else:
                self._transcript_windows[key] = dict(after)
            succeeded = True
        except asyncio.CancelledError:
            # The off-thread read has no page mutations, but its browser request
            # still needs a failed acknowledgement before cancellation escapes.
            self._transcript_window_busy.discard(key)
            owns_busy = False
            try:
                if (generation == self._chat_render_generation and self.message_area is area
                        and self._ui_elements_alive(area)
                        and self.active_tab_key == self._chat_tab_key(*key)):
                    await self._transcript_javascript(area.client,
                        'window.harnessyTranscriptWindowRendered && '
                        f'window.harnessyTranscriptWindowRendered({json.dumps(anchor_id)}, {anchor_offset!r}, '
                        f'{json.dumps(direction)}, false, {generation}, {request_id}, '
                        'undefined, false);', timeout=3.0)
            except Exception as exc:
                if not _is_stale_ui_error(exc):
                    log_event('harnessy', 'transcript_window_ack_deferred', error=str(exc))
            finally:
                await self._drain_transcript_navigation(key)
            raise
        except Exception as exc:
            # Retain old visible rows on an actual read failure. Do not replace
            # them with an empty fallback page and do not modify the database.
            if (generation == self._chat_render_generation and self.message_area is area
                    and self.active_tab_key == self._chat_tab_key(*key)):
                if ('before' in locals() and self._transcript_windows.get(key) in
                        (previous, locals().get('after'))):
                    self._transcript_windows[key] = before
                    self._transcript_following[key] = before_following
                if self._history_notice is not None and self._ui_elements_alive(self._history_notice):
                    self._history_notice.set_text('History could not be loaded. The current page and stored messages have been kept; scroll again to retry.')
                    self._history_notice.set_visibility(True)
            log_event('harnessy', 'transcript_window_handler_failed', workspace_id=workspace_id,
                      chat_id=chat_id, direction=direction, error=f'{type(exc).__name__}: {exc}')
        finally:
            if owns_busy:
                self._transcript_window_busy.discard(key)
        try:
            if (generation == self._chat_render_generation and self.message_area is area
                    and self._ui_elements_alive(area) and self.active_tab_key == self._chat_tab_key(*key)):
                await self._transcript_javascript(area.client,
                    'window.harnessyTranscriptWindowRendered && '
                    f'window.harnessyTranscriptWindowRendered({json.dumps(anchor_id)}, {anchor_offset!r}, '
                    f'{json.dumps(direction)}, {str(changed).lower()}, {generation}, {request_id}, '
                    f'undefined, {str(succeeded).lower()});',
                    timeout=3.0,
                )
        except asyncio.CancelledError:
            # Stop/disconnect must not leave an accepted browser transaction
            # locked merely because the first acknowledgement was cancelled.
            if (generation == self._chat_render_generation and self.message_area is area
                    and self._ui_elements_alive(area) and self.active_tab_key == self._chat_tab_key(*key)):
                try:
                    await self._transcript_javascript(area.client,
                        'window.harnessyTranscriptWindowRendered && '
                        f'window.harnessyTranscriptWindowRendered({json.dumps(anchor_id)}, {anchor_offset!r}, '
                        f'{json.dumps(direction)}, {str(changed).lower()}, {generation}, {request_id}, '
                        'undefined, false);', timeout=3.0)
                except Exception as exc:
                    if not _is_stale_ui_error(exc):
                        log_event('harnessy', 'transcript_window_ack_deferred', error=str(exc))
            raise
        except Exception as exc:
            if not _is_stale_ui_error(exc):
                log_event('harnessy', 'transcript_window_ack_deferred', error=str(exc))
        finally:
            await self._drain_transcript_navigation(key)

    def _browser_project_files(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        reg = self._find_reg(str(data.get('workspace_id') or ''))
        if reg:
            self.open_chat_working_files(self._load_workspace(reg), str(data.get('chat_id') or ''))

    def _browser_chat_scroll(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        workspace_id = str(data.get('workspace_id') or '')
        chat_id = str(data.get('chat_id') or '')
        if not workspace_id or not chat_id:
            return
        reg = self.machine.get_workspace(workspace_id)
        if not reg:
            return
        try:
            ws = self._load_workspace(reg)
            snapshot = {
                'message_id': data.get('message_id'),
                'offset': float(data.get('offset') or 0),
                'scroll_top': float(data.get('scroll_top') or 0),
                'at_bottom': bool(data.get('at_bottom')),
            }
            ws.set_state(f'chat_scroll:{chat_id}', json.dumps(snapshot, separators=(',', ':')))
        except Exception:
            pass

    def _terminal_input(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        terminal_id = str(data.get('terminal_id') or '')
        if not any(
            tab.key == terminal_id and tab.kind in {'terminal', 'target_terminal'} and tab.workspace_id == str(data.get('workspace_id') or '')
            for tab in self.open_tabs
        ):
            return
        session = self.terminal_sessions.get(terminal_id)
        if session:
            try:
                session.send(str(data.get('data') or ''))
            except RuntimeError as exc:
                ui.notify(str(exc), type='warning')

    def _terminal_resize(self, e) -> None:
        data = e.args if isinstance(e.args, dict) else {}
        terminal_id = str(data.get('terminal_id') or '')
        if not any(
            tab.key == terminal_id and tab.kind in {'terminal', 'target_terminal'} and tab.workspace_id == str(data.get('workspace_id') or '')
            for tab in self.open_tabs
        ):
            return
        session = self.terminal_sessions.get(terminal_id)
        if session:
            try:
                session.resize(int(data.get('cols') or 120), int(data.get('rows') or 34))
            except (TypeError, ValueError):
                pass

    # --------------------------------------------------------------- memory tab
    def _render_memory_tab(self, tab: OpenTab, ws: WorkspaceStore) -> None:
        with ui.column().classes('hy-tool-panel hy-memory-panel w-full no-wrap gap-0'):
            with ui.row().classes('hy-editor-header w-full items-center px-4 py-2'):
                ui.label(f'{ws.name} · Workspace Memory').classes('font-semibold')
                ui.space()
                ui.label(f'{ws.db_path} · memory / workspace_state').classes('hy-editor-path text-xs hy-muted')
            with ui.column().classes('hy-editor-body w-full p-4 gap-2 no-wrap'):
                editor = ui.textarea(value=ws.read_project_memory()).props(
                    'outlined rows=1 hide-bottom-space aria-label="Workspace memory"'
                ).classes('hy-fill-editor hy-memory-editor w-full')
                ui.label('SQLite is authoritative for Workspace Memory. This editor shows a generated Markdown view; Save replaces the structured memory/checkpoint records represented by this view. HarnessyXO includes a bounded generated excerpt in each request, and the model can read more with read_project_memory.').classes('hy-editor-footer text-xs hy-muted')
                with ui.row().classes('hy-editor-footer w-full justify-end'):
                    ui.button('Reload', on_click=lambda: setattr(editor, 'value', ws.read_project_memory())).props('flat no-caps')
                    ui.button('Save Memory', on_click=lambda: (ws.write_project_memory(editor.value or ''), ui.notify('Workspace memory saved to SQLite', type='positive'))).props('unelevated no-caps')

    def open_workspace_instructions(self, reg: WorkspaceRegistration) -> None:
        try:
            ws = self._load_workspace(reg)
        except Exception as exc:
            ui.notify(f'Could not open workspace instructions: {exc}', type='negative')
            return
        self._open_instruction_builder(ws, scope='workspace')

    def open_project_chat_instructions(self, ws: WorkspaceStore, chat_id: str) -> None:
        chat = ws.get_chat(chat_id)
        if not chat:
            ui.notify('Project / Chat no longer exists.', type='warning')
            return
        if chat.locked:
            ui.notify(
                'This Project / Chat is locked. “View Effective Instructions” remains available.',
                type='warning', timeout=5000,
            )
            return
        self._open_instruction_builder(ws, scope='project_chat', chat_id=chat_id)

    def open_effective_instructions(self, ws: WorkspaceStore, chat_id: str) -> None:
        chat = ws.get_chat(chat_id)
        if not chat:
            ui.notify('Project / Chat no longer exists.', type='warning')
            return
        global_text = self.machine.read_global_instructions().strip()
        workspace_text = ws.read_workspace_instructions().strip()
        project_text = ws.read_chat_instructions(chat_id).strip()
        layers = [
            ('Global Instructions', global_text, 'Applies to every workspace.'),
            ('Workspace Instructions', workspace_text, 'Applies to every Project / Chat in this workspace.'),
            ('Project / Chat Instructions', project_text, 'Applies only to this Project / Chat.'),
        ]
        with ui.dialog() as dialog, ui.card().classes('hy-editor-card').style('width:min(860px,96vw);height:min(820px,92dvh)'):
            with ui.row().classes('hy-editor-header w-full items-center p-4'):
                ui.label(f'Effective Instructions — {chat.title}').classes('font-semibold')
                ui.space()
                ui.button(icon='close', on_click=dialog.close).props('flat round dense aria-label="Close dialog"')
            with ui.column().classes('hy-editor-body w-full gap-3 p-4').style('flex:1;min-height:0;overflow-y:auto'):
                ui.label('These are the user-authored instruction layers HarnessyXO supplies to this Project / Chat. Current Task State, Memory, core HarnessyXO rules, and skills are separate from these instruction layers.').classes('text-xs hy-muted')
                total = 0
                for name, text, description in layers:
                    estimate = max(0, len(text.encode('utf-8')) // 3)
                    total += estimate
                    state = f'{estimate:,} estimated tokens' if text else 'Empty'
                    with ui.expansion(f'{name} · {state}', value=False).classes('w-full'):
                        ui.label(description).classes('text-xs hy-muted')
                        if text:
                            ui.markdown(text, sanitize=True).classes('w-full hy-assistant')
                        else:
                            ui.label('(empty)').classes('text-sm hy-muted')
                ui.separator()
                ui.label(f'Approximate user-instruction cost: {total:,} tokens per request.').classes('text-xs hy-muted')
            with ui.row().classes('hy-editor-footer w-full justify-end p-3'):
                ui.button('Close', on_click=dialog.close).props('flat no-caps')
        dialog.open()

    def open_current_task_state(self, ws: WorkspaceStore, chat_id: str) -> None:
        """Show the per-Project/Chat continuity ledger without mutating it."""
        chat = ws.get_chat(chat_id)
        if not chat:
            ui.notify('Project / Chat no longer exists.', type='warning')
            return

        with ui.dialog() as dialog, ui.card().classes('hy-editor-card hy-task-state-card'):
            with ui.row().classes('hy-editor-header w-full items-center no-wrap p-4'):
                ui.icon('fact_check', size='22px')
                ui.label(f'Current Task State — {chat.title}').classes('font-semibold min-w-0').style('overflow-wrap:anywhere')
                ui.space()
                ui.button(icon='close', on_click=dialog.close).props('flat round dense aria-label="Close task state"')

            state_body = ui.column().classes('hy-editor-body hy-task-state-body w-full gap-3 p-4')

            def render_state() -> None:
                state = ws.get_task_state(chat_id)
                state_body.clear()
                with state_body:
                    ui.label(
                        'This is the Project/Chat-specific continuity ledger HarnessyXO injects on every model request and keeps outside transcript compaction. '
                        'It is a working handover, not the model’s entire memory and not live VM/filesystem telemetry.'
                    ).classes('text-sm')
                    with ui.card().classes('hy-task-state-section w-full p-3 gap-2'):
                        ui.label('Where HarnessyXO continuity lives').classes('text-sm font-semibold')
                        ui.label('• Chat history: recent turns stay in the active prompt; older persisted turns remain searchable/readable from cold history.').classes('text-xs hy-muted hy-task-state-value')
                        ui.label('• Current Task State: this Project/Chat’s bounded working handover for objective, progress, artifacts, open questions, and next action.').classes('text-xs hy-muted hy-task-state-value')
                        ui.label('• Workspace Memory: durable cross-Project/Chat facts, decisions, architecture notes, and the workspace checkpoint.').classes('text-xs hy-muted hy-task-state-value')

                    revision = int(state.get('revision') or 0)
                    updated = str(state.get('updated_at') or '').strip() or 'Never'
                    with ui.row().classes('w-full items-center gap-2 flex-wrap'):
                        ui.badge(f'Revision {revision}', outline=True)
                        ui.badge(f'Last updated: {updated}', outline=True)
                    if revision == 0:
                        with ui.card().classes('hy-task-state-section w-full p-3 gap-1'):
                            ui.label('No Current Task State has been recorded yet.').classes('font-semibold')
                            ui.label('The model has not successfully called update_task_state for this Project/Chat.').classes('text-sm hy-muted')

                    def text_section(title: str, key: str) -> None:
                        value = str(state.get(key) or '').strip()
                        with ui.card().classes('hy-task-state-section w-full p-3 gap-1'):
                            ui.label(title).classes('text-xs font-semibold hy-muted')
                            ui.label(value or '(empty)').classes('text-sm hy-task-state-value' + (' hy-muted' if not value else ''))

                    def list_section(title: str, key: str) -> None:
                        values = [str(v).strip() for v in (state.get(key) or []) if str(v).strip()]
                        with ui.card().classes('hy-task-state-section w-full p-3 gap-1'):
                            ui.label(title).classes('text-xs font-semibold hy-muted')
                            if not values:
                                ui.label('(empty)').classes('text-sm hy-muted')
                            else:
                                for value in values:
                                    ui.label('• ' + value).classes('text-sm hy-task-state-value')

                    text_section('Objective', 'objective')
                    text_section('Current phase', 'current_phase')
                    text_section('Next action', 'next_action')
                    list_section('Completed milestones / findings', 'completed')
                    list_section('Working artifacts', 'working_artifacts')
                    list_section('Open questions', 'open_questions')
                    list_section('Do not repeat', 'do_not_repeat')
                    list_section('Notes / resume context', 'notes')

                    raw = {k: state.get(k) for k in (
                        'objective', 'current_phase', 'next_action', 'completed', 'working_artifacts',
                        'open_questions', 'do_not_repeat', 'notes', 'revision', 'updated_at'
                    )}
                    with ui.expansion('Raw task-state JSON', value=False).classes('w-full'):
                        ui.label(json.dumps(raw, ensure_ascii=False, indent=2)).classes('text-xs hy-task-state-value').style('font-family:var(--hy-mono)')

            with ui.row().classes('hy-editor-footer w-full items-center gap-2 p-3'):
                ui.button('Refresh', icon='refresh', on_click=render_state).props('flat no-caps')
                ui.space()

                def open_memory() -> None:
                    reg = self._find_reg(ws.id)
                    if not reg:
                        ui.notify('Workspace registration is unavailable.', type='warning')
                        return
                    dialog.close()
                    self.open_tool_tab('memory', reg)

                ui.button('Open Workspace Memory', icon='memory', on_click=open_memory).props('flat no-caps')
                ui.button('Close', on_click=dialog.close).props('unelevated no-caps')

            render_state()
        dialog.open()

    def _open_instruction_builder(self, ws: WorkspaceStore, *, scope: str, chat_id: str | None = None) -> None:
        """Open a passive instruction setup chooser; never start inference on open."""
        if scope not in {'workspace', 'project_chat'}:
            raise ValueError('Unknown instruction scope')
        chat = ws.get_chat(chat_id) if chat_id else None
        if scope == 'project_chat' and not chat:
            ui.notify('Project / Chat no longer exists.', type='warning')
            return
        if scope == 'project_chat' and chat.locked:
            ui.notify('Unlock this Project / Chat before changing its instructions.', type='warning')
            return

        existing = ws.read_workspace_instructions() if scope == 'workspace' else ws.read_chat_instructions(str(chat_id))
        title = f'Workspace Instructions — {ws.name}' if scope == 'workspace' else f'Project / Chat Instructions — {chat.title}'
        scope_help = (
            'These instructions apply to every Project / Chat in this workspace.'
            if scope == 'workspace' else
            'These instructions apply only to this Project / Chat; Workspace Instructions already apply here.'
        )
        source_chats = []
        for candidate in ws.list_chats(archived=None):
            if scope == 'project_chat' and candidate.id == str(chat_id):
                continue
            source_text = ws.read_chat_instructions(candidate.id).strip()
            if source_text:
                source_chats.append((candidate, source_text))

        with ui.dialog() as dialog, ui.card().classes('hy-editor-card hy-instruction-entry-card'):
            with ui.row().classes('hy-editor-header w-full items-center no-wrap p-4'):
                ui.icon('assignment', size='22px')
                ui.label(title).classes('font-semibold min-w-0').style('overflow-wrap:anywhere')
                ui.space()
                ui.button(icon='close', on_click=dialog.close).props('flat round dense aria-label="Close instruction setup"')

            with ui.column().classes('hy-editor-body hy-instruction-entry-body w-full gap-3 p-4'):
                ui.label(scope_help).classes('text-sm')
                ui.label(
                    'Choose how to configure this instruction scope. Opening this screen is passive: no LLM request, token use, or background interview begins until you explicitly press Start LLM Interview.'
                ).classes('text-xs hy-muted')
                current_state = f'{max(1, len(existing.encode("utf-8")) // 3):,} estimated tokens' if existing.strip() else 'Empty'
                ui.label(f'Current instructions: {current_state}').classes('text-xs hy-muted')

                with ui.row().classes('w-full items-stretch gap-3 flex-wrap'):
                    with ui.card().classes('hy-instruction-entry-option p-4 gap-2'):
                        ui.icon('edit_note', size='28px')
                        ui.label('Enter manually').classes('font-semibold')
                        ui.label('Edit the instruction text directly. No model is contacted.').classes('text-xs hy-muted')
                        manual_button = ui.button('Enter manually', icon='edit_note').props('unelevated no-caps')
                    with ui.card().classes('hy-instruction-entry-option p-4 gap-2'):
                        ui.icon('content_copy', size='28px')
                        ui.label('Copy from Project / Chat').classes('font-semibold')
                        ui.label('Reuse existing Project/Chat instructions from this workspace. This copies instructions only, not transcript, memory, task state, or files.').classes('text-xs hy-muted')
                        copy_button = ui.button('Copy from Project / Chat', icon='content_copy').props('outline no-caps')
                        if not source_chats:
                            copy_button.disable()
                            ui.label('No other Project/Chat in this workspace currently has saved instructions.').classes('text-xs hy-muted')
                    with ui.card().classes('hy-instruction-entry-option p-4 gap-2'):
                        ui.icon('psychology_alt', size='28px')
                        ui.label('LLM interview').classes('font-semibold')
                        ui.label('Start the isolated guided interview. The model is contacted only after you press the button below.').classes('text-xs hy-muted')
                        interview_button = ui.button('Start LLM Interview', icon='play_arrow').props('unelevated no-caps')

                if existing.strip():
                    with ui.expansion('Preview current instructions', value=False).classes('w-full'):
                        ui.markdown(existing, sanitize=True).classes('w-full hy-assistant')

            with ui.row().classes('hy-editor-footer w-full justify-end p-3'):
                ui.button('Close', on_click=dialog.close).props('flat no-caps')

            def enter_manual() -> None:
                dialog.close()
                self._open_manual_instruction_editor(ws, scope=scope, chat_id=chat_id)

            def copy_from_chat() -> None:
                dialog.close()
                self._open_instruction_copy_dialog(ws, scope=scope, chat_id=chat_id)

            def start_interview() -> None:
                if not self.machine.list_model_profiles(self.settings):
                    ui.notify('An active LLM profile is required to start the instruction interview.', type='warning')
                    return
                dialog.close()
                self._open_instruction_interview(ws, scope=scope, chat_id=chat_id)

            manual_button.on('click', enter_manual)
            copy_button.on('click', copy_from_chat)
            interview_button.on('click', start_interview)
        dialog.open()

    def _open_manual_instruction_editor(self, ws: WorkspaceStore, *, scope: str, chat_id: str | None = None) -> None:
        if scope not in {'workspace', 'project_chat'}:
            raise ValueError('Unknown instruction scope')
        chat = ws.get_chat(chat_id) if chat_id else None
        if scope == 'project_chat' and not chat:
            ui.notify('Project / Chat no longer exists.', type='warning')
            return
        existing = ws.read_workspace_instructions() if scope == 'workspace' else ws.read_chat_instructions(str(chat_id))
        label = 'Workspace' if scope == 'workspace' else 'Project / Chat'
        title = f'Workspace Instructions — {ws.name}' if scope == 'workspace' else f'Project / Chat Instructions — {chat.title}'

        with ui.dialog().props('persistent') as dialog, ui.card().classes('hy-editor-card'):
            with ui.row().classes('hy-editor-header w-full items-center no-wrap p-4'):
                ui.icon('edit_note', size='22px')
                ui.label(f'{title} · Manual').classes('font-semibold min-w-0').style('overflow-wrap:anywhere')
                ui.space()
                ui.button(icon='close', on_click=dialog.close).props('flat round dense aria-label="Close dialog"')
            with ui.column().classes('hy-editor-body w-full gap-2 p-4 no-wrap'):
                ui.label('Edit the durable instruction text directly. No LLM is used in manual mode.').classes('text-xs hy-muted')
                editor = ui.textarea(value=existing).props('outlined rows=1 aria-label="Manual instructions"').classes('hy-fill-editor hy-file-editor w-full')
                editor.on('keydown', js_handler='(e) => e.stopPropagation()')
            with ui.row().classes('hy-editor-footer w-full items-center gap-2 p-3'):
                ui.button('Cancel', on_click=dialog.close).props('flat no-caps')
                ui.space()
                save_button = ui.button('Save Instructions', icon='save').props('unelevated no-caps')

            def commit(text: str) -> None:
                clean = str(text or '').strip()
                try:
                    revision = ws.write_workspace_instructions(clean) if scope == 'workspace' else ws.write_chat_instructions(str(chat_id), clean)
                except Exception as exc:
                    ui.notify(f'Could not save instructions: {exc}', type='negative')
                    return
                if clean:
                    ui.notify(f'{label} instructions saved · revision {revision}', type='positive')
                else:
                    ui.notify(f'{label} instructions cleared · revision {revision}', type='positive')
                dialog.close()

            def save_manual() -> None:
                text = str(editor.value or '').strip()
                if text == existing.strip():
                    ui.notify('Instructions are unchanged.', type='info')
                    dialog.close()
                    return
                if existing.strip() and not text:
                    with ui.dialog() as confirm_dialog, ui.card().classes('w-[520px] max-w-[92vw] gap-3'):
                        ui.label(f'Clear {label} instructions?').classes('text-lg font-semibold text-negative')
                        ui.label('This removes the current instructions at this scope. Higher-level instructions, conversation history, memory, task state, and project files are preserved.').classes('text-sm')
                        with ui.row().classes('w-full justify-end gap-2'):
                            ui.button('Cancel', on_click=confirm_dialog.close).props('flat no-caps')
                            def confirm_clear() -> None:
                                confirm_dialog.close()
                                commit('')
                            ui.button('Clear Instructions', icon='delete_outline', on_click=confirm_clear).props('unelevated no-caps color=negative')
                    confirm_dialog.open()
                    return
                commit(text)

            save_button.on('click', save_manual)
        dialog.open()

    def _open_instruction_copy_dialog(self, ws: WorkspaceStore, *, scope: str, chat_id: str | None = None) -> None:
        if scope not in {'workspace', 'project_chat'}:
            raise ValueError('Unknown instruction scope')
        target_chat = ws.get_chat(chat_id) if chat_id else None
        if scope == 'project_chat' and not target_chat:
            ui.notify('Project / Chat no longer exists.', type='warning')
            return

        sources = []
        for candidate in ws.list_chats(archived=None):
            if scope == 'project_chat' and candidate.id == str(chat_id):
                continue
            text = ws.read_chat_instructions(candidate.id).strip()
            if text:
                sources.append((candidate, text))
        if not sources:
            ui.notify('No other Project / Chat in this workspace has saved instructions to copy.', type='warning')
            return

        existing = ws.read_workspace_instructions() if scope == 'workspace' else ws.read_chat_instructions(str(chat_id))
        target_label = 'Workspace Instructions' if scope == 'workspace' else f'Project / Chat Instructions — {target_chat.title}'
        options = {
            candidate.id: f'{candidate.title}{" · Archived" if candidate.archived_at else ""} · {candidate.id[:8]}'
            for candidate, _text in sources
        }
        by_id = {candidate.id: text for candidate, text in sources}
        first_id = next(iter(options))

        with ui.dialog().props('persistent') as dialog, ui.card().classes('hy-editor-card').style('width:min(860px,96vw);height:min(760px,92dvh)'):
            with ui.row().classes('hy-editor-header w-full items-center no-wrap p-4'):
                ui.icon('content_copy', size='22px')
                ui.label(f'Copy instructions → {target_label}').classes('font-semibold min-w-0').style('overflow-wrap:anywhere')
                ui.space()
                ui.button(icon='close', on_click=dialog.close).props('flat round dense aria-label="Close dialog"')
            with ui.column().classes('hy-editor-body w-full gap-3 p-4').style('overflow-y:auto'):
                ui.label('Choose a Project / Chat whose saved Project/Chat Instructions should be copied into this scope. Only the instruction document is copied.').classes('text-sm')
                source_select = ui.select(options, value=first_id, label='Source Project / Chat').props('outlined dense').classes('w-full')
                ui.label('Source preview').classes('text-xs font-semibold hy-muted')
                preview = ui.markdown(by_id[first_id], sanitize=True).classes('w-full hy-assistant')
                if existing.strip():
                    with ui.expansion('Current target instructions (will be replaced)', value=False).classes('w-full'):
                        ui.markdown(existing, sanitize=True).classes('w-full hy-assistant')

                def refresh_preview(e=None) -> None:
                    source_id = str(source_select.value or '')
                    preview.set_content(by_id.get(source_id, ''))

                source_select.on_value_change(refresh_preview)

            with ui.row().classes('hy-editor-footer w-full items-center gap-2 p-3'):
                ui.button('Cancel', on_click=dialog.close).props('flat no-caps')
                ui.space()
                copy_button = ui.button('Copy Instructions', icon='content_copy').props('unelevated no-caps')

            def commit_copy(text: str) -> None:
                try:
                    revision = ws.write_workspace_instructions(text) if scope == 'workspace' else ws.write_chat_instructions(str(chat_id), text)
                except Exception as exc:
                    ui.notify(f'Could not copy instructions: {exc}', type='negative')
                    return
                label = 'Workspace' if scope == 'workspace' else 'Project / Chat'
                ui.notify(f'{label} instructions copied · revision {revision}', type='positive')
                dialog.close()

            def copy_selected() -> None:
                source_id = str(source_select.value or '')
                text = by_id.get(source_id, '').strip()
                if not text:
                    ui.notify('The selected source no longer has saved instructions.', type='warning')
                    return
                if text == existing.strip():
                    ui.notify('The selected instructions are already identical to the target.', type='info')
                    dialog.close()
                    return
                if existing.strip():
                    with ui.dialog() as confirm_dialog, ui.card().classes('w-[540px] max-w-[92vw] gap-3'):
                        ui.label(f'Replace current {target_label}?').classes('text-lg font-semibold')
                        ui.label('The target instruction document will be replaced by the selected Project/Chat Instructions. Conversation history, Workspace Memory, Current Task State, and files are not changed.').classes('text-sm')
                        with ui.row().classes('w-full justify-end gap-2'):
                            ui.button('Cancel', on_click=confirm_dialog.close).props('flat no-caps')
                            def confirm_copy() -> None:
                                confirm_dialog.close()
                                commit_copy(text)
                            ui.button('Replace Instructions', icon='content_copy', on_click=confirm_copy).props('unelevated no-caps')
                    confirm_dialog.open()
                    return
                commit_copy(text)

            copy_button.on('click', copy_selected)
        dialog.open()

    def _instruction_builder_profile_id(self, ws: WorkspaceStore, chat_id: str | None) -> str:
        candidate = chat_id
        if not candidate:
            tab = next((t for t in self.open_tabs if t.key == self.active_tab_key), None)
            if tab and tab.kind == 'chat' and tab.workspace_id == ws.id and tab.chat_id:
                candidate = tab.chat_id
        if candidate:
            try:
                return str(self._runtime_for_chat(ws.id, candidate).get('profile_id') or '')
            except Exception:
                pass
        return str(self.machine.get_model_profile(None, self.settings).get('id') or '')

    def _open_instruction_interview(self, ws: WorkspaceStore, *, scope: str, chat_id: str | None = None) -> None:
        """Explicitly-started LLM-driven, tool-free instruction interview."""
        if scope not in {'workspace', 'project_chat'}:
            raise ValueError('Unknown instruction scope')
        chat = ws.get_chat(chat_id) if chat_id else None
        if scope == 'project_chat' and not chat:
            ui.notify('Project / Chat no longer exists.', type='warning')
            return

        existing = ws.read_workspace_instructions() if scope == 'workspace' else ws.read_chat_instructions(str(chat_id))
        global_level = self.machine.read_global_instructions().strip()
        higher_parts: list[str] = []
        if global_level:
            higher_parts.append('# Global Instructions already in force\n' + global_level)
        if scope == 'project_chat':
            workspace_level = ws.read_workspace_instructions().strip()
            if workspace_level:
                higher_parts.append('# Workspace Instructions already in force\n' + workspace_level)
        higher_level = '\n\n'.join(higher_parts)
        reference_context, reference_memory_count, reference_chat_count = instruction_reference_context(ws, chat_id)
        title = f'Workspace Instructions — {ws.name}' if scope == 'workspace' else f'Project / Chat Instructions — {chat.title}'
        scope_help = (
            'These instructions apply to every Project / Chat in this workspace. Use this when the workspace has one shared mission, environment, or set of working rules. Leave it empty when each Project / Chat is unrelated.'
            if scope == 'workspace' else
            'These instructions apply only to this Project / Chat. Workspace Instructions already apply here, so the builder will avoid duplicating them unless this Project / Chat needs a different or more specific rule.'
        )
        profiles = self.machine.list_model_profiles(self.settings)
        if not profiles:
            ui.notify('An active LLM profile is required to configure instructions.', type='warning')
            return
        initial_profile_id = self._instruction_builder_profile_id(ws, chat_id)
        valid_ids = {str(p.get('id') or '') for p in profiles}
        if initial_profile_id not in valid_ids:
            initial_profile_id = str(profiles[0].get('id') or '')

        answers: list[dict[str, str]] = []
        state: dict[str, Any] = {
            'question': None,
            'busy': False,
            'drafted': False,
            'stage': 'interview',
            'busy_started': 0.0,
            'busy_operation': '',
            'post_final_followup': False,
        }
        max_questions = 12
        final_question = "Anything else you'd like the model to know?"

        with ui.dialog().props('persistent') as dialog, ui.card().classes('hy-editor-card hy-instruction-builder-card'):
            with ui.row().classes('hy-editor-header w-full items-center no-wrap p-4'):
                ui.icon('psychology_alt', size='22px')
                ui.label(title).classes('font-semibold min-w-0').style('overflow-wrap:anywhere')
                ui.space()
                ui.button(icon='close', on_click=dialog.close).props('flat round dense aria-label="Close instruction builder"')

            with ui.column().classes('hy-editor-body hy-instruction-builder-body w-full gap-3 p-4'):
                model_row = ui.column().classes('hy-instruction-model-row w-full gap-1')
                with model_row:
                    def profile_label(profile: dict[str, Any]) -> str:
                        name = str(profile.get('name') or '').strip()
                        model = str(profile.get('model') or '').strip()
                        return model if not name or name.casefold() == model.casefold() else f'{name} · {model}'

                    model_select = ui.select(
                        {str(p.get('id')): profile_label(p) for p in profiles},
                        value=initial_profile_id,
                        label='Instruction-builder model',
                    ).classes('hy-instruction-model-select w-full').props('dense outlined options-dense')

                with ui.expansion('Interview context', icon='info', value=False).classes('hy-instruction-context w-full'):
                    ui.label('About this interview').classes('text-sm font-semibold')
                    ui.label(scope_help).classes('text-sm')
                    ui.label('The builder is isolated: it has no project tools, live filesystem access, chat transcript, or memory-write capability. It may receive the bounded read-only reference snapshot shown below so it can recognize related prior work without silently inheriting it. Nothing becomes active until you press Save.').classes('text-xs hy-muted')
                    if reference_context:
                        memory_word = 'entry' if reference_memory_count == 1 else 'entries'
                        chat_word = 'summary' if reference_chat_count == 1 else 'summaries'
                        ui.separator()
                        ui.label(
                            f'Read-only reference context · {reference_memory_count} memory {memory_word} · '
                            f'{reference_chat_count} other Project/Chat {chat_word}'
                        ).classes('text-sm font-semibold')
                        ui.label('Reference only: similarity may cause the interviewer to ask whether prior work is related, but it cannot automatically inherit or modify Memory, another Project/Chat, or its transcript.').classes('text-xs hy-muted')
                        ui.code(reference_context).classes('w-full').style('max-height:260px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere')
                    if higher_level.strip():
                        ui.separator()
                        ui.label('Higher-level instructions already in force').classes('text-sm font-semibold')
                        ui.markdown(higher_level, sanitize=True).classes('w-full hy-assistant')
                    if existing.strip():
                        ui.separator()
                        ui.label('Current instructions at this scope').classes('text-sm font-semibold')
                        ui.markdown(existing, sanitize=True).classes('w-full hy-assistant')
                        ui.label('The interviewer receives this existing text and asks only what it needs to revise or confirm it.').classes('text-xs hy-muted')

                with ui.row().classes('hy-instruction-activity w-full items-center no-wrap gap-3 px-3 py-2'):
                    activity_spinner = ui.spinner(size='20px')
                    activity_icon = ui.icon('check_circle_outline', size='20px').classes('hy-muted')
                    with ui.column().classes('gap-0').style('flex:1;min-width:0'):
                        status = ui.label('Starting isolated instruction interview…').classes('text-sm font-medium')
                        activity_detail = ui.label('The dialog will stay visibly busy while the selected LLM is working.').classes('text-xs hy-muted')
                    activity_elapsed = ui.label('').classes('text-xs hy-muted').style('font-variant-numeric:tabular-nums;white-space:nowrap')
                progress = ui.linear_progress(value=0).props('indeterminate').classes('w-full')
                ui.separator().classes('hy-instruction-ready-separator w-full')
                question_counter = ui.label('Preparing interview…').classes(
                    'hy-instruction-question-counter w-full'
                )

                history_shell = ui.expansion('Interview answers (0)', icon='history', value=False).classes('hy-instruction-answers w-full')
                history_shell.set_visibility(False)
                with history_shell:
                    history_area = ui.column().classes('hy-instruction-history w-full gap-1')
                question_area = ui.column().classes('w-full gap-2')
                answer = ui.textarea(label='Your answer').props('outlined rows=6 aria-label="Instruction interview answer"').classes('hy-instruction-textarea w-full')
                answer.set_visibility(False)
                answer.on('keydown', js_handler='(e) => e.stopPropagation()')

                final_area = ui.column().classes('w-full gap-2')
                final_area.set_visibility(False)
                with final_area:
                    with ui.card().classes('hy-instruction-question w-full p-4 gap-2'):
                        ui.label(final_question).classes('hy-instruction-question-text')
                        ui.label("Add any final constraints, preferences, edge cases, priorities, or expectations that haven't already been covered. Leave this blank if you're happy with the interview.").classes('text-sm hy-muted')
                    final_answer = ui.textarea(label='Optional final note').props('outlined rows=6 aria-label="Anything else"').classes('hy-instruction-final w-full')
                    final_answer.on('keydown', js_handler='(e) => e.stopPropagation()')

                draft_area = ui.column().classes('w-full gap-2')
                draft_area.set_visibility(False)
                with draft_area:
                    ui.label('Proposed instructions').classes('font-semibold')
                    ui.label('Review and edit this draft before saving. It is intentionally concise persistent context; discoveries and current progress belong in Memory / Current Task State instead.').classes('text-xs hy-muted')
                    with ui.tabs().classes('hy-editor-toolbar w-full') as draft_tabs:
                        draft_preview_tab = ui.tab('Preview')
                        draft_edit_tab = ui.tab('Edit')
                    with ui.tab_panels(draft_tabs, value=draft_preview_tab).classes('hy-file-editor-panels w-full bg-transparent').style('min-height:260px'):
                        with ui.tab_panel(draft_preview_tab).classes('p-2'):
                            draft_preview = ui.markdown('', sanitize=True).classes('w-full hy-assistant')
                        with ui.tab_panel(draft_edit_tab).classes('p-0'):
                            draft_editor = ui.textarea(value='').props('outlined rows=1 aria-label="Generated instructions"').classes('hy-fill-editor hy-file-editor w-full')
                            draft_editor.on('keydown', js_handler='(e) => e.stopPropagation()')
                    draft_editor.on_value_change(lambda e: draft_preview.set_content(str(e.value or '')))
                    token_hint = ui.label('').classes('text-xs hy-muted')

            with ui.row().classes('hy-editor-footer hy-instruction-footer w-full items-center gap-2 p-3').style('border-top:1px solid var(--hy-border)'):
                cancel_button = ui.button('Cancel', on_click=dialog.close).props('flat no-caps')
                ui.space()
                skip_button = ui.button('Skip Question').props('flat no-caps')
                finish_button = ui.button('Finish & Draft Now').props('flat no-caps')
                continue_button = ui.button('Answer & Continue').props('unelevated no-caps')
                final_no_button = ui.button('No, draft instructions').props('flat no-caps')
                final_add_button = ui.button('Add this and continue').props('unelevated no-caps')
                save_button = ui.button('Save Instructions').props('unelevated no-caps')
                final_no_button.set_visibility(False)
                final_add_button.set_visibility(False)
                save_button.set_visibility(False)
                finish_button.disable()
                continue_button.disable()

            def selected_profile() -> dict[str, Any]:
                return self.machine.get_model_profile(str(model_select.value or ''), self.settings)

            def update_elapsed() -> None:
                try:
                    if state['busy'] and state['busy_started']:
                        elapsed = max(0, int(time.monotonic() - float(state['busy_started'])))
                        minutes, seconds = divmod(elapsed, 60)
                        activity_elapsed.set_text(f'{minutes}:{seconds:02d}')
                    else:
                        activity_elapsed.set_text('')
                except RuntimeError as exc:
                    if not _is_stale_ui_error(exc):
                        raise

            ui.timer(0.25, update_elapsed)

            def sync_controls() -> None:
                busy = bool(state['busy'])
                drafted = bool(state['drafted'])
                stage = str(state['stage'])
                model_select.set_enabled(not busy and not drafted)
                answer.set_enabled(not busy and not drafted)
                final_answer.set_enabled(not busy and not drafted)
                if stage == 'interview':
                    continue_button.set_enabled(not busy and state.get('question') is not None)
                    skip_button.set_enabled(not busy and state.get('question') is not None)
                    finish_button.set_enabled(not busy and bool(answers or existing.strip() or str(answer.value or '').strip()))
                elif stage == 'post_final_followup':
                    continue_button.set_enabled(not busy and state.get('question') is not None)
                    skip_button.set_enabled(not busy and state.get('question') is not None)
                    finish_button.disable()
                elif stage == 'final_review':
                    final_no_button.set_enabled(not busy)
                    final_add_button.set_enabled(not busy)
                save_button.set_enabled(not busy and drafted)

            def set_busy(value: bool, text: str = '', detail: str = '') -> None:
                state['busy'] = bool(value)
                if value:
                    state['busy_started'] = time.monotonic()
                    activity_spinner.set_visibility(True)
                    activity_icon.set_visibility(False)
                    progress.set_visibility(True)
                else:
                    state['busy_started'] = 0.0
                    activity_spinner.set_visibility(False)
                    activity_icon.set_visibility(True)
                    progress.set_visibility(False)
                if text:
                    status.set_text(text)
                if detail:
                    activity_detail.set_text(detail)
                sync_controls()

            answer.on_value_change(lambda _e: sync_controls())

            def set_idle_icon(name: str = 'check_circle_outline', color: str | None = None) -> None:
                activity_icon.props(remove='color')
                props = f'name={name}' + (f' color={color}' if color else '')
                activity_icon.props(props)

            def builder_progress(phase: str) -> None:
                if not state['busy']:
                    return
                phase = str(phase or '').strip()
                if not phase:
                    return
                operation = str(state.get('busy_operation') or '')
                if phase.lower().startswith('prompt'):
                    text = 'Prompt processing…'
                elif phase.lower().startswith('waiting'):
                    text = 'Waiting for the model…'
                elif phase.lower().startswith('generating'):
                    text = 'Drafting instructions…' if operation == 'draft' else 'Generating next question…'
                else:
                    text = phase.rstrip('.') + '…'
                try:
                    status.set_text(text)
                    activity_detail.set_text('Instruction compiler is working.' if operation == 'draft' else 'Instruction interviewer is working.')
                except RuntimeError as exc:
                    if not _is_stale_ui_error(exc):
                        raise

            def draw_history() -> None:
                history_shell.set_text(f'Interview answers ({len(answers)})')
                history_shell.set_visibility(bool(answers))
                history_area.clear()
                with history_area:
                    for idx, row in enumerate(answers, start=1):
                        with ui.expansion(f'Q{idx} answered ✓', value=False).classes('w-full'):
                            ui.label(row.get('question', '')).classes('text-xs font-semibold hy-muted').style('white-space:pre-wrap;overflow-wrap:anywhere')
                            ui.label(row.get('answer', '')).classes('text-sm').style('white-space:pre-wrap;overflow-wrap:anywhere')

            def show_interview_actions() -> None:
                skip_button.set_visibility(True)
                continue_button.set_visibility(True)
                finish_button.set_visibility(state['stage'] == 'interview')
                final_no_button.set_visibility(False)
                final_add_button.set_visibility(False)
                save_button.set_visibility(False)

            def draw_question(q, *, post_final: bool = False) -> None:
                state['question'] = q
                state['stage'] = 'post_final_followup' if post_final else 'interview'
                state['post_final_followup'] = bool(post_final)
                final_area.set_visibility(False)
                draft_area.set_visibility(False)
                question_area.clear()
                with question_area:
                    with ui.card().classes('hy-instruction-question w-full p-4 gap-2'):
                        ui.label(q.question).classes('hy-instruction-question-text').style('white-space:pre-wrap;overflow-wrap:anywhere')
                        if q.why_needed:
                            ui.label(q.why_needed).classes('text-xs hy-muted')
                        if q.recommended_answer:
                            with ui.column().classes('hy-instruction-recommendation w-full gap-1'):
                                with ui.row().classes('w-full items-center gap-2'):
                                    ui.label('Recommended answer').classes('text-xs font-semibold hy-muted')
                                    ui.space()
                                    ui.button('Use recommendation', on_click=lambda value=q.recommended_answer: answer.set_value(value)).props('flat no-caps dense')
                                ui.label(q.recommended_answer).classes('text-sm').style('white-space:pre-wrap;overflow-wrap:anywhere')
                        if q.examples:
                            with ui.expansion('Show examples', value=False).classes('w-full'):
                                for example in q.examples:
                                    ui.button(example, on_click=lambda value=example: answer.set_value(value)).props('outline no-caps dense').classes('w-full').style('text-align:left;white-space:normal')
                        if q.covered:
                            ui.label('Covered: ' + ', '.join(q.covered)).classes('text-xs hy-muted')
                answer.set_value('')
                answer.set_visibility(True)
                show_interview_actions()
                label = 'Final follow-up' if post_final else f'Question {len(answers) + 1} of {max_questions}'
                question_counter.set_text(label)
                set_idle_icon()
                status.set_text('Ready for your answer.')
                activity_detail.set_text('Answer the active question, use the recommendation, or skip it.')
                sync_controls()

            def show_final_review() -> None:
                state['question'] = None
                state['stage'] = 'final_review'
                state['post_final_followup'] = False
                question_area.clear()
                answer.set_visibility(False)
                final_answer.set_value('')
                final_area.set_visibility(True)
                draft_area.set_visibility(False)
                skip_button.set_visibility(False)
                continue_button.set_visibility(False)
                finish_button.set_visibility(False)
                final_no_button.set_visibility(True)
                final_add_button.set_visibility(True)
                save_button.set_visibility(False)
                question_counter.set_text('Final review')
                set_busy(False, 'One last review before drafting.', 'Nothing is saved yet. Add a final note or draft now.')
                set_idle_icon('rate_review')

            async def make_draft() -> None:
                if state['busy'] or state['drafted']:
                    return
                state['busy_operation'] = 'draft'
                state['stage'] = 'drafting'
                final_area.set_visibility(False)
                question_area.clear()
                answer.set_visibility(False)
                skip_button.set_visibility(False)
                continue_button.set_visibility(False)
                finish_button.set_visibility(False)
                final_no_button.set_visibility(False)
                final_add_button.set_visibility(False)
                set_busy(True, 'Drafting instructions…', 'The compiler is turning the interview into concise durable instructions.')
                await asyncio.sleep(0)
                try:
                    profile = selected_profile()
                    draft = await instruction_draft(
                        profile, scope=scope, answers=answers,
                        higher_level=higher_level, existing=existing, reference_context=reference_context,
                        concurrency=min(
                            max(1, int(self.settings.get('agent', {}).get('global_agent_slots', 1))),
                            max(1, int(profile.get('provider_concurrency', 1) or 1)),
                        ),
                        progress=builder_progress,
                    )
                except Exception as exc:
                    state['stage'] = 'final_review'
                    set_busy(False, 'Instruction drafting failed.', str(exc))
                    set_idle_icon('error_outline', 'negative')
                    final_area.set_visibility(True)
                    final_no_button.set_visibility(True)
                    final_add_button.set_visibility(True)
                    ui.notify(f'Instruction builder could not reach/complete with the selected LLM: {exc}', type='negative', timeout=12000)
                    return
                state['drafted'] = True
                state['question'] = None
                state['stage'] = 'draft'
                model_row.set_visibility(False)
                draft_editor.set_value(draft)
                draft_preview.set_content(draft)
                approx = max(1, len(draft.encode('utf-8')) // 3)
                token_hint.set_text(f'Approximate persistent prompt cost: {approx:,} tokens per request (conservative estimate).')
                draft_area.set_visibility(True)
                save_button.set_visibility(True)
                question_counter.set_text('Draft ready')
                set_busy(False, 'Draft ready. Review it before saving.', 'Nothing becomes active until Save Instructions is pressed.')
                set_idle_icon('check_circle', 'primary')

            async def request_next(
                *, post_final: bool = False,
                pending_answer: dict[str, str] | None = None,
            ) -> bool:
                if state['busy'] or state['drafted']:
                    return False
                prospective_answers = list(answers)
                if pending_answer is not None:
                    prospective_answers.append(dict(pending_answer))
                if not post_final and len(prospective_answers) >= max_questions:
                    if pending_answer is not None:
                        answers.append(dict(pending_answer))
                        draw_history()
                    show_final_review()
                    return True
                state['busy_operation'] = 'next'
                set_busy(True, 'Thinking about your answer…' if prospective_answers else 'Starting isolated instruction interview…',
                         'The selected LLM is deciding whether another question is materially necessary.')
                await asyncio.sleep(0)
                try:
                    profile = selected_profile()
                    q = await instruction_next_question(
                        profile, scope=scope, answers=prospective_answers,
                        higher_level=higher_level, existing=existing, reference_context=reference_context,
                        force_ready=False,
                        concurrency=min(
                            max(1, int(self.settings.get('agent', {}).get('global_agent_slots', 1))),
                            max(1, int(profile.get('provider_concurrency', 1) or 1)),
                        ),
                        progress=builder_progress,
                    )
                except Exception as exc:
                    state['stage'] = 'final_review' if post_final else 'interview'
                    if pending_answer is not None:
                        set_busy(
                            False,
                            'Could not generate the next question.',
                            f'Your answer was not submitted. Edit it and try again. {exc}',
                        )
                    else:
                        set_busy(False, 'Instruction interview could not start/continue.', str(exc))
                    set_idle_icon('error_outline', 'negative')
                    if post_final:
                        final_area.set_visibility(True)
                        final_no_button.set_visibility(True)
                        final_add_button.set_visibility(True)
                        sync_controls()
                    ui.notify(f'Instruction interviewer could not continue: {exc}', type='negative', timeout=12000)
                    return False
                if pending_answer is not None:
                    answers.append(dict(pending_answer))
                    draw_history()
                    state['question'] = None
                    question_area.clear()
                    answer.set_visibility(False)
                if q.action == 'READY':
                    set_busy(False)
                    if post_final:
                        await make_draft()
                    else:
                        show_final_review()
                    return True
                draw_question(q, post_final=post_final)
                set_busy(False, 'Ready for your answer.', 'One active question at a time.')
                return True

            async def submit_answer() -> None:
                if state['busy'] or state['drafted']:
                    return
                q = state.get('question')
                text = str(answer.value or '').strip()
                if not q:
                    return
                if not text:
                    ui.notify('Answer the question, use a recommendation/example, or skip it.', type='warning')
                    return
                post_final_followup = bool(state.get('post_final_followup'))
                if post_final_followup:
                    answers.append({'question': q.question, 'answer': text})
                    draw_history()
                    state['question'] = None
                    question_area.clear()
                    answer.set_visibility(False)
                    await make_draft()
                else:
                    await request_next(pending_answer={'question': q.question, 'answer': text})

            async def skip_question() -> None:
                if state['busy'] or state['drafted']:
                    return
                q = state.get('question')
                if not q:
                    return
                post_final_followup = bool(state.get('post_final_followup'))
                if post_final_followup:
                    answers.append({'question': q.question, 'answer': '[Skipped by user]'})
                    draw_history()
                    state['question'] = None
                    question_area.clear()
                    answer.set_visibility(False)
                    await make_draft()
                else:
                    await request_next(pending_answer={
                        'question': q.question,
                        'answer': '[Skipped by user]',
                    })

            async def finish_now() -> None:
                if state['busy'] or state['drafted']:
                    return
                if state['question'] is not None and str(answer.value or '').strip():
                    answers.append({'question': state['question'].question, 'answer': str(answer.value).strip()})
                    draw_history()
                    state['question'] = None
                show_final_review()

            async def add_final_and_continue() -> None:
                if state['busy'] or state['drafted']:
                    return
                text = str(final_answer.value or '').strip()
                if not text:
                    ui.notify('Add a final note, or choose “No, draft instructions”.', type='warning')
                    return
                # The builder gets exactly one opportunity to ask a targeted
                # follow-up after this HarnessyXO-controlled final review.
                await request_next(
                    post_final=True,
                    pending_answer={'question': final_question, 'answer': text},
                )

            async def no_final_and_draft() -> None:
                if state['busy'] or state['drafted']:
                    return
                await make_draft()

            def commit_save(text: str) -> None:
                try:
                    if scope == 'workspace':
                        revision = ws.write_workspace_instructions(text)
                    else:
                        revision = ws.write_chat_instructions(str(chat_id), text)
                except Exception as exc:
                    ui.notify(f'Could not save instructions: {exc}', type='negative')
                    return
                label = 'Workspace' if scope == 'workspace' else 'Project / Chat'
                if text:
                    ui.notify(f'{label} instructions saved · revision {revision}', type='positive')
                else:
                    ui.notify(f'{label} instructions cleared · revision {revision}', type='positive')
                dialog.close()

            def save_instructions() -> None:
                if not state['drafted'] or state['busy']:
                    return
                text = str(draft_editor.value or '').strip()
                if existing.strip() and not text:
                    label = 'Workspace' if scope == 'workspace' else 'Project / Chat'
                    with ui.dialog() as confirm_dialog, ui.card().classes('w-[520px] max-w-[92vw] gap-3'):
                        ui.label(f'Clear {label} instructions?').classes('text-lg font-semibold text-negative')
                        ui.label('Saving an empty draft removes the current instructions at this scope. Higher-level instructions and project files are preserved.').classes('text-sm')
                        with ui.row().classes('w-full justify-end gap-2'):
                            ui.button('Cancel', on_click=confirm_dialog.close).props('flat no-caps')
                            def confirm_clear() -> None:
                                confirm_dialog.close()
                                commit_save('')
                            ui.button('Clear Instructions', icon='delete_outline', on_click=confirm_clear).props('unelevated no-caps color=negative')
                    confirm_dialog.open()
                    return
                commit_save(text)

            continue_button.on('click', submit_answer)
            skip_button.on('click', skip_question)
            finish_button.on('click', finish_now)
            final_no_button.on('click', no_final_and_draft)
            final_add_button.on('click', add_final_and_continue)
            save_button.on('click', save_instructions)
            status.set_text('Starting isolated instruction interview…')
            progress.set_visibility(True)
            activity_spinner.set_visibility(True)
            activity_icon.set_visibility(False)
            ui.timer(0.05, request_next, once=True)
        dialog.open()

    # ----------------------------------------------------------- file explorer
    @staticmethod
    def _file_scope_root(ws: WorkspaceStore | ToolScope) -> Path:
        if isinstance(ws, WorkspaceStore):
            return ws.files_root.resolve()
        return ws.root.resolve()

    @staticmethod
    def _file_live_link_target(ws: WorkspaceStore | ToolScope, path: Path) -> Path:
        if not isinstance(ws, ToolScope):
            return path.resolve(strict=False)
        candidate = path.resolve(strict=False)
        seen: set[Path] = set()
        for _ in range(len(ws.live_links) + 1):
            if candidate in seen:
                break
            seen.add(candidate)
            replacement = None
            matches: list[tuple[int, Path, Path]] = []
            for marker_text, target_text in ws.live_links:
                marker = Path(marker_text).resolve(strict=False)
                if candidate == marker or marker in candidate.parents:
                    matches.append((len(marker.parts), marker, Path(target_text).resolve(strict=False)))
            if matches:
                _depth, marker, target = max(matches, key=lambda row: row[0])
                relative = candidate.relative_to(marker)
                replacement = (target / relative).resolve(strict=False)
            if replacement is None or replacement == candidate:
                break
            candidate = replacement
        return candidate

    @staticmethod
    def _file_requested_path(ws: WorkspaceStore | ToolScope, value: str | Path) -> Path:
        """Translate the Project Files model path into its safe host projection."""
        raw = str(value or '').strip()
        if isinstance(ws, ToolScope) and not ws.archived:
            prefix = '/workspace/Files'
            if raw == prefix or raw.startswith(prefix + '/'):
                relative_text = raw[len(prefix):].lstrip('/')
                relative = Path(relative_text) if relative_text else Path('.')
                if relative.is_absolute() or any(part in {'', '..'} for part in relative.parts):
                    raise ValueError('Project Files path escapes /workspace/Files.')
                return HarnessyPage._file_live_link_target(ws, ws.root / relative)
        return HarnessyPage._file_live_link_target(ws, Path(raw).expanduser())

    @staticmethod
    def _file_display_path(ws: WorkspaceStore | ToolScope, path: Path) -> str:
        """Return the logical path shown/copied by a confined Project Files tab."""
        candidate = path.resolve(strict=False)
        if not isinstance(ws, ToolScope):
            return str(candidate)
        if ws.archived:
            try:
                relative = candidate.relative_to(ws.root.resolve())
            except ValueError:
                return ws.output_directory
            return ws.output_directory if relative == Path('.') else f'{ws.output_directory}/{relative.as_posix()}'

        seen: set[Path] = set()
        for _ in range(len(ws.live_links) + 1):
            if candidate in seen:
                break
            seen.add(candidate)
            matches: list[tuple[int, Path, Path]] = []
            for marker_text, target_text in ws.live_links:
                marker = Path(marker_text).resolve(strict=False)
                target = Path(target_text).resolve(strict=False)
                if candidate == target or target in candidate.parents:
                    matches.append((len(target.parts), marker, target))
            if not matches:
                break
            _depth, marker, target = max(matches, key=lambda row: row[0])
            replacement = (marker / candidate.relative_to(target)).resolve(strict=False)
            if replacement == candidate:
                break
            candidate = replacement
        root = ws.root.resolve()
        try:
            relative = candidate.relative_to(root)
        except ValueError:
            return ws.output_directory
        return '/workspace/Files' if relative == Path('.') else f'/workspace/Files/{relative.as_posix()}'

    def _file_scope_store(self, ws: WorkspaceStore | ToolScope) -> WorkspaceStore | None:
        if isinstance(ws, WorkspaceStore):
            return ws
        if ws.workspace_id:
            candidate = self._scope_for_id(ws.workspace_id)
            if isinstance(candidate, WorkspaceStore):
                return candidate
        return None

    @staticmethod
    def _file_parent_path(ws: WorkspaceStore | ToolScope, current: Path) -> Path:
        if isinstance(ws, ToolScope):
            for marker_text, target_text in ws.live_links:
                if current.resolve(strict=False) == Path(target_text).resolve(strict=False):
                    return Path(marker_text).resolve(strict=False).parent
        return current.parent

    @classmethod
    def _file_path_in_scope(cls, ws: WorkspaceStore | ToolScope, path: Path) -> bool:
        confined = isinstance(ws, ToolScope) or isinstance(ws, WorkspaceStore)
        if not confined:
            return True
        root = cls._file_scope_root(ws)
        try:
            target = path.resolve(strict=False)
        except (OSError, RuntimeError):
            return False
        if isinstance(ws, ToolScope):
            for _marker, live_root_text in ws.live_links:
                live_root = Path(live_root_text).resolve(strict=False)
                if target == live_root or live_root in target.parents:
                    return True
            if ws.hidden_root_names and target.is_relative_to(root):
                relative = target.relative_to(root)
                if relative.parts and relative.parts[0] in ws.hidden_root_names:
                    return False
        if target == root or root in target.parents:
            return True
        return False

    @classmethod
    def _file_entry_visible(
        cls, ws: WorkspaceStore | ToolScope, current: Path, path: Path,
    ) -> bool:
        if (
            isinstance(ws, ToolScope)
            and current.resolve(strict=False) == ws.root.resolve(strict=False)
            and path.name in ws.hidden_root_names
        ):
            return False
        return cls._file_path_in_scope(ws, path)

    @staticmethod
    def _sort_file_entries(entries: list[Path], sort_key: str, descending: bool) -> list[Path]:
        key = str(sort_key or 'name').lower()
        def stat_value(path: Path) -> tuple[Any, ...]:
            try:
                stat = path.stat()
            except OSError:
                stat = None
            if key == 'modified':
                return ((stat.st_mtime if stat else 0.0), path.name.casefold())
            if key == 'size':
                return ((stat.st_size if stat and path.is_file() else 0), path.name.casefold())
            if key == 'type':
                suffix = path.suffix.casefold().lstrip('.') if path.is_file() else ''
                return (suffix, path.name.casefold())
            return (path.name.casefold(),)
        folders = [path for path in entries if path.is_dir()]
        files = [path for path in entries if not path.is_dir()]
        folders.sort(key=stat_value, reverse=descending)
        files.sort(key=stat_value, reverse=descending)
        return folders + files

    def _file_sort_state(self) -> tuple[str, bool]:
        general = self.settings.get('general', {}) if isinstance(self.settings.get('general'), dict) else {}
        key = str(general.get('file_sort_key') or 'name')
        if key not in {'name', 'modified', 'size', 'type'}:
            key = 'name'
        return key, bool(general.get('file_sort_descending', False))

    def _toggle_file_sort_column(self, key: str, *, owner_tab_key: str | None = None) -> None:
        current_key, current_descending = self._file_sort_state()
        descending = (not current_descending) if key == current_key else False
        self._set_file_sort(key=key, descending=descending, owner_tab_key=owner_tab_key)

    @staticmethod
    def _file_type_label(path: Path, is_dir: bool | None = None) -> str:
        directory = path.is_dir() if is_dir is None else bool(is_dir)
        if directory:
            return 'Folder'
        suffix = path.suffix.casefold().lstrip('.')
        return suffix.upper() if suffix else 'File'

    def _set_file_sort(self, *, key: str | None = None, descending: bool | None = None,
                       owner_tab_key: str | None = None) -> None:
        # A queued event from an explorer that has been closed/switched away
        # must not redraw a different tab and discard its current draft.
        if owner_tab_key is not None and self.active_tab_key != owner_tab_key:
            return
        current_key, current_desc = self._file_sort_state()
        self.settings = self.machine.update_settings({'general': {
            'file_sort_key': key if key in {'name', 'modified', 'size', 'type'} else current_key,
            'file_sort_descending': current_desc if descending is None else bool(descending),
        }})
        self.refresh_tabs()

    def _render_files_tab(self, tab: OpenTab, ws: WorkspaceStore | ToolScope) -> None:
        scope_root = self._file_scope_root(ws)
        readonly = isinstance(ws, ToolScope) and ws.read_only
        current = self.file_paths.setdefault(ws.id, scope_root)
        if not current.exists() or not current.is_dir() or not self._file_path_in_scope(ws, current):
            current = scope_root
            self.file_paths[ws.id] = current
        output_labels = self._file_output_labels(ws, current)
        parent_path = self._file_parent_path(ws, current)
        can_go_up = parent_path != current and self._file_path_in_scope(ws, parent_path)
        with ui.column().classes('hy-tool-panel hy-file-explorer w-full no-wrap gap-0'):
            if readonly:
                identity = ws.identity or {}
                with ui.column().classes('w-full px-3 py-2 gap-0 hy-working-files-identity'):
                    ui.label(f"{ws.name} · {identity.get('working_root_label', 'Canonical project')} · Read-only panel").classes('text-sm font-semibold')
                    ui.label(f"Root ID: {identity.get('working_root_id', 'unavailable')}").classes('text-xs hy-muted')
                    ui.label(
                        ('Permanent archive snapshot: ' if ws.archived else 'Exact model-visible Project Files root: ')
                        + ws.output_directory
                    ).classes('text-xs hy-muted break-all')
                    reg = self._find_reg(ws.workspace_id or '')
                    if reg and not ws.archived:
                        ui.button('Open Workspace Files', icon='folder_special', on_click=lambda r=reg: self.open_tool_tab('files', r)).props('flat dense no-caps')
            toolbar = ui.row().classes('hy-tool-toolbar hy-file-toolbar w-full items-center py-2 gap-1')
            columns = ui.row().classes('hy-file-columns w-full').props('role=row aria-label="File columns"')
            listing = ui.column().classes('hy-file-listing w-full gap-0')
            with toolbar:
                if isinstance(ws, WorkspaceStore):
                    scope_chip = ui.label('Files').classes('text-xs hy-muted hy-root-scope-chip')
                    scope_chip.tooltip(
                        'References and every active canonical Project-<ID> directory. '
                        'There are no alternate working copies.'
                    )
                path_input = ui.input(value=self._file_display_path(ws, current)).props(
                    'dense outlined aria-label="Folder path"'
                ).classes('hy-file-path-input')
                with ui.row().classes('hy-file-actions items-center gap-0'):
                    up_button = ui.button(icon='arrow_upward').props(
                        f'flat round dense aria-label="Up one level" data-hy-file-up=1 '
                        f'data-hy-file-scope={ws.id} data-hy-file-tab={tab.key}'
                    ).tooltip('Up one level')
                    up_button.set_enabled(can_go_up)
                    root_tip = (
                        'User home' if ws.id == HOME_SCOPE_ID else
                        ('Model-visible /workspace/Files' if isinstance(ws, ToolScope) and not ws.archived else
                         ('Workspace Files/' if isinstance(ws, WorkspaceStore) and ws.is_vm_workspace else 'Workspace root'))
                    )
                    ui.button(icon='home', on_click=lambda: self._file_go(ws, scope_root, owner_tab_key=tab.key)).props('flat round dense').tooltip(root_tip)
                    if not readonly and not (isinstance(ws, WorkspaceStore) and ws.is_vm_workspace):
                        ui.button('/', on_click=lambda: self._file_go(ws, Path('/'), owner_tab_key=tab.key)).props('flat dense no-caps').tooltip('Filesystem root')
                    ui.button(icon='refresh', on_click=self.refresh_tabs).props('flat round dense aria-label="Refresh"').tooltip('Refresh')
                    history_store = self._file_scope_store(ws)
                    if history_store is not None and not (isinstance(ws, ToolScope) and ws.archived):
                        ui.button(
                            icon='history', on_click=lambda store=history_store: self.open_file_history_browser(store),
                        ).props('flat round dense').tooltip('Browse File History, including deleted files')
                    if not readonly:
                        ui.button(icon='create_new_folder', on_click=lambda: self._file_new_folder(ws, current)).props('flat round dense aria-label="New folder"').tooltip('New folder')
                        ui.button(icon='note_add', on_click=lambda: self._file_new_file(ws, current)).props('flat round dense aria-label="New file"').tooltip('New file')
                        upload_button = ui.button(icon='upload_file').props('flat round dense').tooltip('Upload files')
                        upload_button.on('click', js_handler='() => window.harnessyPickExplorerFiles && window.harnessyPickExplorerFiles()')
                    clipboard = self.file_clipboard.get(ws.id)
                    if clipboard and not readonly:
                        ui.button(icon='content_paste', on_click=lambda: self._file_paste(ws, current)).props('flat round dense').tooltip(f"Paste {len(clipboard.get('paths') or [])} item(s)")
                path_input.on(
                    'keydown.enter',
                    lambda: self._file_go(
                        ws, str(path_input.value or ''),
                        owner_tab_key=tab.key,
                    ),
                )
            with columns:
                sort_key, sort_descending = self._file_sort_state()
                for key, label, column_class in (
                    ('name', 'Name', 'hy-file-col-name'),
                    ('size', 'Size', 'hy-file-col-size'),
                    ('modified', 'Date modified', 'hy-file-col-modified'),
                    ('type', 'Type', 'hy-file-col-type'),
                ):
                    active = sort_key == key
                    indicator = ('↓' if sort_descending else '↑') if active else ''
                    aria_sort = ('descending' if sort_descending else 'ascending') if active else 'none'
                    button = ui.button(
                        f'{label} {indicator}'.rstrip(),
                        on_click=lambda k=key: self._toggle_file_sort_column(k, owner_tab_key=tab.key),
                    ).props(
                        f'flat dense no-caps role=columnheader aria-sort={aria_sort} aria-label="Sort by {label}"'
                    ).classes(
                        f'hy-file-column-header {column_class}' + (' hy-active-sort' if active else '')
                    )
                    if active:
                        direction = 'descending' if sort_descending else 'ascending'
                        next_direction = 'ascending' if sort_descending else 'descending'
                        button.tooltip(f'Sorted {direction}. Click to sort {next_direction}. Folders remain first.')
                    else:
                        button.tooltip(f'Sort by {label.lower()}. Folders remain first.')
            with listing:
                try:
                    reserved = {FILES_PROBE_DIR_NAME}
                    entries = self._sort_file_entries(
                        [
                            p for p in current.iterdir()
                            if p.name not in reserved and self._file_entry_visible(ws, current, p)
                        ],
                        *self._file_sort_state(),
                    )
                except Exception as exc:
                    ui.label(f'Cannot read {current}: {exc}').classes('text-negative p-4')
                    return
                if can_go_up:
                    self._file_parent_row(ws, parent_path, owner_tab_key=tab.key)
                if not entries:
                    ui.label('Empty folder.' if readonly else 'Empty folder — drop files anywhere in this area to upload.').classes('hy-muted p-4')
                for item_path in entries[:5000]:
                    self._file_row(ws, item_path, output_labels=output_labels, owner_tab_key=tab.key)
                with ui.context_menu():
                    if not readonly:
                        ui.menu_item('New file', on_click=lambda: self._file_new_file(ws, current))
                        ui.menu_item('New folder', on_click=lambda: self._file_new_folder(ws, current))
                    if self.file_clipboard.get(ws.id) and not readonly:
                        ui.separator().classes('hy-action-menu-separator')
                        ui.menu_item('Paste', on_click=lambda: self._file_paste(ws, current))
                    history_store = self._file_scope_store(ws)
                    if history_store is not None and not (isinstance(ws, ToolScope) and ws.archived):
                        if not readonly:
                            ui.separator().classes('hy-action-menu-separator')
                        ui.menu_item(
                            'Browse File History',
                            on_click=lambda store=history_store: self.open_file_history_browser(store),
                        )
                    if not readonly or history_store is not None and not (isinstance(ws, ToolScope) and ws.archived):
                        ui.separator().classes('hy-action-menu-separator')
                    ui.menu_item('Refresh', on_click=self.refresh_tabs)
            self._set_file_explorer_target(ws, current, listing.client)

    def _file_output_labels(self, ws: WorkspaceStore | ToolScope, current: Path) -> dict[str, str] | None:
        """Join owners/titles once per render, never infer ownership from nested names."""
        store = ws if isinstance(ws, WorkspaceStore) else None
        if store is None and ws.workspace_id:
            candidate = self._scope_for_id(ws.workspace_id)
            if isinstance(candidate, WorkspaceStore):
                store = candidate
        if store is None or current.resolve() != store.files_root.resolve():
            return None
        chats = {chat.id: chat.title for chat in store.list_chats(archived=None)}
        return {
            str(owner['folder_name']): chats.get(str(owner.get('chat_id') or ''), 'Reserved Project / Chat')
            for owner in store.list_output_owners()
        }

    def _file_up(self, ws: WorkspaceStore | ToolScope, *, owner_tab_key: str | None = None) -> None:
        if owner_tab_key is not None and owner_tab_key != self.active_tab_key:
            return
        current = self.file_paths.get(ws.id, self._file_scope_root(ws))
        parent = self._file_parent_path(ws, current)
        if parent == current or not self._file_path_in_scope(ws, parent):
            return
        self._file_go(ws, parent, owner_tab_key=owner_tab_key)

    def _file_go(self, ws: WorkspaceStore | ToolScope, target: str | Path, *, owner_tab_key: str | None = None) -> None:
        if owner_tab_key is not None and owner_tab_key != self.active_tab_key:
            return
        # Event callbacks inherit their sender's parent slot. refresh_tabs()
        # deletes that slot; use the persistent content container for the whole
        # operation so error notifications retain a live client after a redraw.
        container = self.tab_content_area
        context = container if container is not None and self._ui_elements_alive(container) else nullcontext()
        with context:
            try:
                resolved = self._file_requested_path(ws, target)
                if not resolved.is_dir():
                    raise ValueError('Not a directory')
                if not self._file_path_in_scope(ws, resolved):
                    raise ValueError('Workspace File Explorer is confined to this workspace Files/ directory. Use the Home File Explorer for host filesystem access.')
                self.file_paths[ws.id] = resolved
                self._save_ui_session()
                self.refresh_tabs()
            except Exception as exc:
                log_event('ui', 'file_navigation_failed', workspace_id=ws.id, error_type=type(exc).__name__)
                ui.notify(str(exc), type='negative')

    def _file_open(self, ws: WorkspaceStore | ToolScope, target: Path, *, owner_tab_key: str | None = None) -> None:
        if owner_tab_key is not None and owner_tab_key != self.active_tab_key:
            return
        resolved_target = self._file_live_link_target(ws, target)
        if resolved_target.is_dir():
            self._file_go(ws, resolved_target, owner_tab_key=owner_tab_key)
        elif resolved_target.is_file():
            self.open_file_tab(ws, resolved_target)

    def _file_parent_row(self, ws: WorkspaceStore | ToolScope, parent: Path, *, owner_tab_key: str | None = None) -> None:
        encoded = quote(str(parent), safe='')
        props = (f'data-hy-path={encoded} data-hy-parent=1 data-hy-dir=1 data-hy-file=0 '
                 f'data-hy-file-scope={ws.id} data-hy-file-tab={owner_tab_key or self.active_tab_key or ""}')
        with ui.row().classes('hy-file-row w-full').props(props) as row:
            with ui.row().classes('hy-file-name-cell hy-file-col-name no-wrap items-center'):
                ui.icon('drive_file_move', size='19px')
                ui.label('..').classes('text-sm font-semibold hy-file-name')
            ui.label('—').classes('hy-file-col-size hy-file-metadata')
            ui.label('').classes('hy-file-col-modified hy-file-metadata')
            ui.label('Parent').classes('hy-file-col-type hy-file-metadata')
            # Repeated parent navigation is handled by a stable delegated browser
            # click pair listener; binding native dblclick here regresses when the
            # row is replaced underneath an unmoved pointer.

    def _file_row(self, ws: WorkspaceStore | ToolScope, p: Path, *, output_labels: dict[str, str] | None = None,
                  owner_tab_key: str | None = None) -> None:
        readonly = isinstance(ws, ToolScope) and ws.read_only
        encoded = quote(str(p), safe='')
        is_dir = p.is_dir()
        is_file = p.is_file()
        props = f'draggable={"false" if readonly else "true"} data-hy-path={encoded} data-hy-dir={1 if is_dir else 0} data-hy-file={1 if is_file else 0}'
        try:
            stat = p.stat()
        except OSError:
            stat = None
        size_text = _human_size(stat.st_size) if stat is not None and is_file else '—'
        modified_text = ''
        if stat is not None:
            import datetime as _dt
            modified_text = _dt.datetime.fromtimestamp(stat.st_mtime).strftime('%Y-%m-%d %H:%M')
        output_title = None
        if is_dir and output_labels is not None:
            output_title = output_labels.get(p.name)
            if output_title is None and CHAT_OUTPUT_DIR_RE.fullmatch(p.name):
                output_title = 'Unassigned project'
        project_directory = is_dir and output_labels is not None and p.name in output_labels
        live_link = isinstance(ws, ToolScope) and any(
            p.resolve(strict=False) == Path(marker).resolve(strict=False)
            for marker, _target in ws.live_links
        )
        project_access_link = live_link and isinstance(ws, ToolScope) and any(
            p.resolve(strict=False) == Path(marker).resolve(strict=False)
            and Path(marker).resolve(strict=False).parent == ws.root.resolve(strict=False)
            for marker, _target in ws.live_links
        )
        with ui.row().classes('hy-file-row w-full').props(props) as row:
            with ui.row().classes('hy-file-name-cell hy-file-col-name no-wrap items-center'):
                icon = 'link' if live_link else ('inventory_2' if project_directory else ('folder' if is_dir else ('archive' if is_archive(p) else 'description')))
                ui.icon(icon, size='19px')
                ui.label(p.name).classes('text-sm hy-file-name')
                if output_title is not None:
                    ui.label(f'({output_title})').classes('hy-file-output-owner').tooltip(output_title)
                if live_link:
                    if project_access_link:
                        ui.label('(Project Access · read-only)').classes('hy-file-output-owner').tooltip(
                            'Explicitly shared project files. Changes appear here immediately.'
                        )
                    else:
                        ui.label('(live parent · read-only)').classes('hy-file-output-owner').tooltip(
                            'Current parent project files. Changes appear here immediately.'
                        )
            ui.label(size_text).classes('hy-file-col-size hy-file-metadata')
            ui.label(modified_text).classes('hy-file-col-modified hy-file-metadata')
            ui.label(
                'Project Access' if project_access_link else
                ('Live parent' if live_link else ('Project' if project_directory else self._file_type_label(p, is_dir)))
            ).classes('hy-file-col-type hy-file-metadata')
            row.on('click', js_handler="(e) => window.harnessyFileRowClick && window.harnessyFileRowClick(e)")
            row.on('dblclick', lambda target=p: self._file_open(ws, target, owner_tab_key=owner_tab_key))
            with ui.context_menu():
                if is_dir:
                    ui.menu_item('Open', on_click=lambda target=p: self._file_open(ws, target, owner_tab_key=owner_tab_key))
                    if not readonly:
                        ui.separator().classes('hy-action-menu-separator')
                        ui.menu_item('New file here', on_click=lambda target=p: self._file_new_file(ws, target))
                        ui.menu_item('New folder here', on_click=lambda target=p: self._file_new_folder(ws, target))
                    if self.file_clipboard.get(ws.id) and not readonly:
                        ui.separator().classes('hy-action-menu-separator')
                        ui.menu_item('Paste here', on_click=lambda target=p: self._file_paste(ws, target))
                else:
                    ui.menu_item('View' if readonly else 'View / Edit', on_click=lambda target=p: self.open_file_tab(ws, target))
                    ui.menu_item('Download', on_click=lambda target=p: self._download_scope_file(ws, target))
                    ui.separator().classes('hy-action-menu-separator')
                    ui.menu_item('File Fingerprint / Properties', on_click=lambda target=p: self.open_file_fingerprint(ws, target))
                    history_store = self._file_scope_store(ws)
                    if history_store is not None and not (isinstance(ws, ToolScope) and ws.archived):
                        ui.menu_item(
                            'File History',
                            on_click=lambda target=p, store=history_store: self.open_file_history_dialog(store, target),
                        )
                if readonly:
                    ui.separator().classes('hy-action-menu-separator')
                    ui.menu_item(
                        'Copy full path',
                        on_click=lambda target=p: self._write_clipboard(
                            self._file_display_path(ws, target)
                        ),
                    )
                    return
                ui.separator().classes('hy-action-menu-separator')
                ui.menu_item('Copy', on_click=lambda target=p: self._file_set_clipboard(ws, self._file_targets(ws, target), 'copy'))
                ui.menu_item('Cut', on_click=lambda target=p: self._file_set_clipboard(ws, self._file_targets(ws, target), 'cut'))
                ui.menu_item('Rename / Move…', on_click=lambda target=p: self._file_rename(target) if len(self._file_targets(ws, target)) == 1 else ui.notify('Rename works on one selected item at a time.', type='warning'))
                ui.separator().classes('hy-action-menu-separator')
                ui.menu_item('Pack as ZIP', on_click=lambda target=p: self._file_zip(ws, self._file_targets(ws, target)))
                if is_file and is_archive(p):
                    ui.menu_item('Extract Here', on_click=lambda target=p: self._file_extract(ws, target, 'here'))
                    ui.menu_item(f'Extract to {_archive_base_name(p)}', on_click=lambda target=p: self._file_extract(ws, target, 'folder'))
                ui.separator().classes('hy-action-menu-separator')
                ui.menu_item('Delete', on_click=lambda target=p: self._file_delete(ws, self._file_targets(ws, target)))

    def _download_scope_file(self, ws: WorkspaceStore | ToolScope, path: Path) -> None:
        if not self._file_path_in_scope(ws, path) or not path.is_file():
            ui.notify('The file is unavailable or outside this explorer scope.', type='warning')
            return
        ui.download.file(path)

    async def open_file_fingerprint(self, ws: WorkspaceStore | ToolScope, path: Path) -> None:
        """Hash exact bytes off the event loop; never label a preview hash as a file hash."""
        from harnessy.diagnostics import inspect_file_fingerprint, log_file_operation

        if not self._file_path_in_scope(ws, path):
            ui.notify('The file is outside this explorer scope.', type='warning')
            return
        root = self._file_scope_root(ws)
        identity = ws.working_root_identity(root) if isinstance(ws, WorkspaceStore) else (ws.identity or {})
        workspace_id = ws.workspace_id or ws.id if isinstance(ws, ToolScope) else ws.id
        options = {
            'workspace_id': workspace_id, 'working_root': root,
            'working_root_id': identity.get('working_root_id', ''),
            'working_root_kind': identity.get('working_root_kind', 'host_files'),
        }
        display_path = self._file_display_path(ws, path)
        display_root = self._file_display_path(ws, root)
        with ui.dialog() as dialog, ui.card().classes('w-[760px] max-w-[95vw] gap-3'):
            with ui.row().classes('w-full items-center no-wrap'):
                ui.icon('fingerprint')
                ui.label('File Fingerprint / Properties').classes('text-lg font-semibold')
                ui.space()
                ui.button(icon='close', on_click=dialog.close).props('flat round dense aria-label="Close dialog"')
            ui.label(display_path).classes('text-xs break-all')
            progress = ui.label('Reading every byte and calculating SHA-256…').classes('text-sm hy-muted')
            content = ui.column().classes('w-full gap-2')
        dialog.open()
        try:
            def inspect() -> dict[str, Any]:
                fingerprint = inspect_file_fingerprint(path, **options)
                log_file_operation(
                    'inspect_file', path=path, **options,
                    chat_id=ws.chat_id if isinstance(ws, ToolScope) else None,
                    file_state=fingerprint, ok=True, source='ui',
                )
                return fingerprint
            fingerprint = await asyncio.to_thread(inspect)
            summary = '\n'.join([
                f'File: {display_path}', f'Root: {display_root}',
                f"Root kind: {options['working_root_kind']}",
                f"Root ID: {options['working_root_id'] or 'not applicable'}",
                f"Path ID: {fingerprint['path_id']}",
                f"Resolved path ID: {fingerprint['resolved_path_id']}",
                f"Bytes: {fingerprint['bytes']}",
                f"SHA-256 (whole file): {fingerprint['sha256']}",
                f"Modified (UTC): {datetime.fromtimestamp(fingerprint['mtime_ns'] / 1_000_000_000, timezone.utc).isoformat()}",
                f"Modified (ns): {fingerprint['mtime_ns']}",
                f"Observed: {fingerprint['observed_at']}",
                'Stable: file identity and metadata unchanged while hashing',
            ])
            if not self._ui_elements_alive(content):
                return
            progress.set_text('Verified whole-file fingerprint (not a preview or excerpt hash).')
            with content:
                ui.textarea(value=summary).props('outlined readonly autogrow aria-label="File fingerprint"').classes('w-full text-xs')
                with ui.row().classes('w-full justify-end gap-2'):
                    ui.button('Copy SHA-256', icon='content_copy', on_click=lambda: self._write_clipboard(str(fingerprint['sha256']))).props('flat no-caps')
                    ui.button('Copy details', icon='content_copy', on_click=lambda: self._write_clipboard(summary)).props('flat no-caps')
        except Exception as exc:
            if self._ui_elements_alive(progress):
                progress.set_text(f'Could not verify a stable file: {exc}. Refresh and try again.')
                progress.classes(add='text-negative')

    async def open_file_history_dialog(
        self, ws: WorkspaceStore, path: Path | str, *, _tab: OpenTab | None = None,
    ) -> None:
        try:
            versions = await asyncio.to_thread(ws.list_file_versions, path)
            relative = versions[0]['path'] if versions else Path(path).name
        except Exception as exc:
            ui.notify(f'Could not load File History: {exc}', type='negative', timeout=9000)
            return
        if not versions:
            ui.notify('No File History records are available for this path.', type='warning')
            return

        if _tab is None:
            key = self._history_tab_key(ws.id, path)
            tab = next((row for row in self.open_tabs if row.key == key), None)
            if tab is None:
                tab = OpenTab(
                    key, 'history', ws.id, None,
                    f'File History · {Path(relative).name}', file_path=str(path),
                )
                self.open_tabs.append(tab)
            self.file_history_states[key] = {
                'versions': versions,
                'selected': str(versions[0]['version_id']),
                'compare': 'previous',
                'relative': relative,
            }
            self.activate_tab(key)
            return
        if self.active_tab_key != _tab.key:
            return
        container = self.tab_content_area
        if container is None or not self._ui_elements_alive(container):
            return
        state = self.file_history_states.setdefault(_tab.key, {
            'versions': versions,
            'selected': str(versions[0]['version_id']),
            'compare': 'previous',
            'relative': relative,
        })
        state['versions'] = versions
        if not any(
            str(item.get('version_id') or '') == str(state.get('selected') or '')
            for item in versions
        ):
            state['selected'] = str(versions[0]['version_id'])
        state['relative'] = relative
        container.clear()
        close_panel = lambda: self.close_tab(_tab.key)

        with container, ui.column().classes('hy-tool-panel hy-file-history-card gap-2'):
            with ui.row().classes('w-full items-center no-wrap gap-2'):
                ui.icon('history', size='23px')
                with ui.column().classes('gap-0 min-w-0'):
                    ui.label(f'File History · {Path(relative).name}').classes('text-lg font-semibold ellipsis')
                    ui.label(relative).classes('text-xs hy-muted ellipsis')
                ui.space()
                ui.button(icon='close', on_click=close_panel).props('flat round dense aria-label="Close tab"').tooltip('Close tab')
            ui.separator()
            with ui.row().classes('hy-file-history-body w-full no-wrap gap-3'):
                version_area = ui.column().classes('hy-file-history-list gap-1 no-wrap')
                detail_area = ui.column().classes('hy-file-history-detail gap-3 no-wrap')

            def selected_version() -> dict[str, Any]:
                return next(
                    (item for item in state['versions'] if str(item.get('version_id')) == state['selected']),
                    state['versions'][0],
                )

            def previous_version_id(version_id: str) -> str | None:
                rows = state['versions']
                index = next((i for i, item in enumerate(rows) if str(item.get('version_id')) == version_id), -1)
                return str(rows[index + 1].get('version_id')) if 0 <= index < len(rows) - 1 else None

            async def download_version(version_id: str) -> None:
                try:
                    exported = await asyncio.to_thread(ws.export_file_version, relative, version_id)
                    ui.download.file(exported)
                except Exception as exc:
                    ui.notify(f'Download failed: {exc}', type='negative', timeout=8000)

            def open_origin(item: dict[str, Any]) -> None:
                chat_id = str(item.get('source_chat_id') or '')
                message_id = str(item.get('source_message_id') or '')
                if not chat_id or ws.get_chat(chat_id) is None:
                    ui.notify('The originating chat was deleted; its file version remains available.', type='info')
                    return
                close_panel()
                self.open_chat_tab(chat_id, ws=ws)
                if message_id:
                    script = f'window.harnessyJumpToPrompt && window.harnessyJumpToPrompt({json.dumps(message_id)});'
                    async def jump_to_origin() -> None:
                        await ui.run_javascript(script)
                    ui.timer(0.15, jump_to_origin, once=True)

            def restore_as_copy(version_id: str) -> None:
                original = Path(relative)
                default_name = f'{original.stem}_restored{original.suffix}'
                default_path = (original.parent / default_name).as_posix()
                with ui.dialog().props('persistent') as restore_dialog, ui.card().classes('w-[620px] max-w-[94vw] gap-3'):
                    ui.label('Restore historical version as a copy').classes('text-lg font-semibold')
                    ui.label('The current file is left unchanged. HarnessyXO records a safety checkpoint before restoring.').classes('text-sm hy-muted')
                    destination = ui.input('Destination in Files', value=default_path).props('outlined dense').classes('w-full')
                    with ui.row().classes('w-full justify-end gap-2'):
                        ui.button('Cancel', on_click=restore_dialog.close).props('flat no-caps')

                        async def restore_copy() -> None:
                            try:
                                result = await asyncio.to_thread(
                                    ws.restore_file_version, relative, version_id,
                                    destination=str(destination.value or '').strip(),
                                )
                                restore_dialog.close()
                                ui.notify(f"Restored copy to {result['destination']}", type='positive')
                                self.refresh_tabs()
                            except Exception as exc:
                                ui.notify(f'Restore failed: {exc}', type='negative', timeout=9000)

                        ui.button('Restore copy', icon='content_copy', on_click=restore_copy).props('unelevated no-caps')
                restore_dialog.open()

            def confirm_replace(version_id: str) -> None:
                with ui.dialog().props('persistent') as replace_dialog, ui.card().classes('w-[560px] max-w-[94vw] gap-3'):
                    ui.label('Replace the current file?').classes('text-lg font-semibold')
                    ui.label(
                        f'This replaces {relative} with the selected historical bytes. '
                        'A safety checkpoint of the current canonical project/reference scope is created first.'
                    ).classes('text-sm')
                    with ui.row().classes('w-full justify-end gap-2'):
                        ui.button('Cancel', on_click=replace_dialog.close).props('flat no-caps')

                        async def replace_current() -> None:
                            try:
                                result = await asyncio.to_thread(ws.restore_file_version, relative, version_id)
                                replace_dialog.close()
                                ui.notify(
                                    f"Restored {relative} · safety {result['safety_snapshot_id'][:8]}",
                                    type='positive',
                                )
                                state['versions'] = await asyncio.to_thread(ws.list_file_versions, relative)
                                state['selected'] = 'current'
                                draw_versions()
                                await draw_detail()
                                self.refresh_tabs()
                            except Exception as exc:
                                ui.notify(f'Restore failed: {exc}', type='negative', timeout=9000)

                        ui.button('Replace current', icon='restore', on_click=replace_current).props(
                            'unelevated no-caps color=negative'
                        )
                replace_dialog.open()

            async def choose(version_id: str, compare: str = 'previous') -> None:
                state['selected'] = str(version_id)
                state['compare'] = compare
                draw_versions()
                await draw_detail()

            def choose_callback(version_id: str, compare: str = 'previous'):
                async def callback() -> None:
                    await choose(version_id, compare)
                return callback

            def download_callback(version_id: str):
                async def callback() -> None:
                    await download_version(version_id)
                return callback

            def draw_versions() -> None:
                version_area.clear()
                with version_area:
                    ui.label(f"{len(state['versions'])} distinct states").classes('text-xs hy-muted q-mb-xs')
                    for item in state['versions']:
                        version_id = str(item.get('version_id') or '')
                        selected = version_id == state['selected']
                        classes = 'hy-file-history-version w-full gap-0' + (' hy-selected' if selected else '')
                        with ui.column().classes(classes) as row:
                            when = str(item.get('created_at') or '').replace('T', ' ')[:19]
                            title = 'Current' if version_id == 'current' else (when or version_id[:8])
                            state_label = 'Available' if item.get('exists') else 'Not present at this checkpoint'
                            ui.label(title).classes('text-sm font-semibold')
                            source_bits = [str(item.get('source_chat_public_id') or ''), str(item.get('source_chat_title') or '')]
                            source = ' · '.join(bit for bit in source_bits if bit)
                            if source:
                                ui.label(source).classes('text-xs ellipsis')
                            ui.label(state_label).classes('text-xs hy-muted')
                            row.on('click', choose_callback(version_id))
                            with ui.context_menu().classes('hy-action-menu'):
                                ui.menu_item('Open / preview', on_click=choose_callback(version_id))
                                previous_id = previous_version_id(version_id)
                                if previous_id is not None:
                                    ui.menu_item('Compare with previous', on_click=choose_callback(version_id, 'previous'))
                                if version_id != 'current':
                                    ui.menu_item('Compare with current', on_click=choose_callback(version_id, 'current'))
                                if item.get('exists'):
                                    ui.separator()
                                    ui.menu_item('Download this version', on_click=download_callback(version_id))
                                    if version_id != 'current':
                                        ui.menu_item('Restore as copy…', on_click=lambda v=version_id: restore_as_copy(v))
                                        ui.menu_item('Replace current file…', on_click=lambda v=version_id: confirm_replace(v))
                                if item.get('source_chat_id'):
                                    ui.separator()
                                    ui.menu_item('Open originating prompt', on_click=lambda value=item: open_origin(value))

            async def draw_detail() -> None:
                item = selected_version()
                version_id = str(item.get('version_id') or '')
                raw: bytes | None = None
                preview_error = ''
                if item.get('exists'):
                    try:
                        raw, _meta = await asyncio.to_thread(
                            ws.read_file_version, relative, version_id, max_bytes=3 * 1024 * 1024,
                        )
                    except Exception as exc:
                        preview_error = str(exc)

                compare_id: str | None = None
                newer_id = version_id
                older_id = previous_version_id(version_id)
                if state.get('compare') == 'current' and version_id != 'current':
                    newer_id, older_id = 'current', version_id
                compare_id = older_id
                diff_result: dict[str, Any] | None = None
                if compare_id is not None:
                    try:
                        diff_result = await asyncio.to_thread(
                            ws.diff_file_versions, relative, newer_id, compare_id,
                        )
                    except Exception as exc:
                        diff_result = {'diff': '', 'binary': False, 'error': str(exc)}

                detail_area.clear()
                with detail_area:
                    with ui.row().classes('w-full items-start gap-2'):
                        with ui.column().classes('gap-0 min-w-0'):
                            ui.label('Current file' if version_id == 'current' else str(item.get('created_at') or '')).classes('text-base font-semibold')
                            provenance = ' · '.join(value for value in (
                                str(item.get('source_chat_public_id') or ''),
                                str(item.get('source_chat_title') or ''),
                                str(item.get('label') or ''),
                            ) if value)
                            if provenance:
                                ui.label(provenance).classes('text-xs hy-muted')
                        ui.space()
                        if item.get('exists'):
                            ui.button(icon='download', on_click=download_callback(version_id)).props('flat round dense aria-label="Download this version"').tooltip('Download this version')
                            if version_id != 'current':
                                ui.button(icon='content_copy', on_click=lambda v=version_id: restore_as_copy(v)).props('flat round dense aria-label="Restore as copy"').tooltip('Restore as copy')
                                ui.button(icon='restore', on_click=lambda v=version_id: confirm_replace(v)).props('flat round dense color=negative aria-label="Replace current file"').tooltip('Replace current file')
                    prompt_preview = str(item.get('prompt_preview') or '').strip()
                    if prompt_preview:
                        ui.label(f'Prompt: {prompt_preview}').classes('text-xs hy-muted')
                    with ui.tabs().classes('w-full') as tabs:
                        preview_tab = ui.tab('Preview')
                        changes_tab = ui.tab('Changes')
                        details_tab = ui.tab('Details')
                    with ui.tab_panels(tabs, value=changes_tab if diff_result else preview_tab).classes('w-full p-0'):
                        with ui.tab_panel(preview_tab).classes('p-0 q-pt-sm'):
                            if not item.get('exists'):
                                ui.label('This path did not exist at this checkpoint.').classes('hy-muted')
                            elif preview_error:
                                ui.label(f'Preview unavailable: {preview_error}').classes('hy-muted')
                            elif raw is not None:
                                mime = mimetypes.guess_type(relative)[0] or 'application/octet-stream'
                                if mime.startswith('image/'):
                                    data_url = f'data:{mime};base64,{base64.b64encode(raw).decode("ascii")}'
                                    ui.image(data_url).classes('max-w-full max-h-[420px] object-contain')
                                elif b'\x00' in raw[:8192]:
                                    ui.label(f'Binary file · {_human_size(len(raw))}. Use Download to inspect exact bytes.').classes('hy-muted')
                                else:
                                    ui.label(raw.decode('utf-8', errors='replace')).classes('hy-file-history-preview')
                        with ui.tab_panel(changes_tab).classes('p-0 q-pt-sm'):
                            if diff_result is None:
                                ui.label('There is no older distinct state to compare.').classes('hy-muted')
                            elif diff_result.get('error'):
                                ui.label(f"Comparison unavailable: {diff_result['error']}").classes('hy-muted')
                            elif diff_result.get('binary'):
                                ui.label(str(diff_result.get('message') or 'Binary comparison')).classes('hy-muted')
                            elif not str(diff_result.get('diff') or ''):
                                ui.label('No textual differences.').classes('hy-muted')
                            else:
                                ui.label(str(diff_result.get('diff') or '')).classes('hy-file-history-diff')
                                if diff_result.get('truncated'):
                                    ui.label('Diff truncated for display. Download either version for exact bytes.').classes('text-xs hy-muted')
                        with ui.tab_panel(details_tab).classes('p-0 q-pt-sm'):
                            details = {
                                key: item.get(key) for key in (
                                    'version_id', 'created_at', 'exists', 'kind', 'size', 'mode', 'storage',
                                    'identity', 'source_kind', 'source_chat_public_id', 'source_chat_title',
                                    'source_message_id', 'restorable', 'warning_text',
                                )
                            }
                            ui.label(
                                json.dumps(details, indent=2, ensure_ascii=False)
                            ).classes('hy-file-history-preview')

            draw_versions()
        await draw_detail()

    async def open_file_history_browser(self, ws: WorkspaceStore) -> None:
        try:
            paths = await asyncio.to_thread(ws.list_file_history_paths)
        except Exception as exc:
            ui.notify(f'Could not browse File History: {exc}', type='negative', timeout=9000)
            return
        with ui.dialog().props('persistent') as dialog, ui.card().classes('w-[780px] max-w-[95vw] h-[760px] max-h-[92vh] gap-2'):
            with ui.row().classes('w-full items-center'):
                ui.label('Browse File History').classes('text-lg font-semibold')
                ui.space()
                ui.button(icon='close', on_click=dialog.close).props('flat round dense aria-label="Close dialog"')
            ui.label('Includes files which have been deleted or renamed since an earlier checkpoint.').classes('text-xs hy-muted')
            search = ui.input('Filter by path or filename').props('outlined dense clearable').classes('w-full')
            rows_area = ui.column().classes('w-full gap-0 overflow-auto')

            def draw_paths() -> None:
                query = str(search.value or '').strip().casefold()
                matches = [item for item in paths if not query or query in str(item['path']).casefold()]
                rows_area.clear()
                with rows_area:
                    if not matches:
                        ui.label('No matching historical files.').classes('hy-muted p-3')
                        return
                    def open_path_callback(value: dict[str, Any]):
                        async def callback() -> None:
                            dialog.close()
                            await self.open_file_history_dialog(ws, ws.files_root / str(value['path']))
                        return callback
                    for item in matches[:1000]:
                        with ui.row().classes('w-full items-center no-wrap py-2 px-2 cursor-pointer').on(
                            'click', open_path_callback(item),
                        ):
                            ui.icon('description' if item.get('exists_now') else 'restore_from_trash', size='18px')
                            ui.label(str(item['path'])).classes('text-sm ellipsis')
                            ui.space()
                            ui.label('Current' if item.get('exists_now') else 'Historical only').classes('text-xs hy-muted')
                    if len(matches) > 1000:
                        ui.label(f'Showing 1,000 of {len(matches)} matches. Narrow the filter.').classes('text-xs hy-muted p-2')

            search.on_value_change(lambda _e: draw_paths())
            draw_paths()
        dialog.open()

    def _launch_file_operation(self, ws: WorkspaceStore | ToolScope, label: str, work, success_text) -> None:
        tab_key = self._tool_tab_key('files', ws.id)
        if TAB_ACTIVITY.busy(tab_key):
            ui.notify('File Explorer is already working. Wait for the current operation to finish.', type='warning')
            return
        release_activity = TAB_ACTIVITY.acquire(tab_key)
        self._sync_tab_activity_ui()

        async def run() -> None:
            try:
                worker = asyncio.create_task(asyncio.to_thread(work))
                try:
                    result = await asyncio.shield(worker)
                except asyncio.CancelledError:
                    # A thread cannot be cancelled. Retain the activity/ownership
                    # until actual I/O exits instead of allowing a second writer.
                    await asyncio.shield(worker)
                    raise
                message = success_text(result) if callable(success_text) else str(success_text)
                if message:
                    try:
                        ui.notify(message, type='positive')
                    except RuntimeError as exc:
                        if not _is_stale_ui_error(exc):
                            raise
            except Exception as exc:
                log_event('harnessy', 'file_operation_failed', operation=label, error=str(exc))
                try:
                    ui.notify(f'{label} failed: {exc}', type='negative', timeout=8000)
                except RuntimeError:
                    pass
            finally:
                release_activity()
                try:
                    if self.active_tab_key == tab_key:
                        self.refresh_tabs()
                    self._sync_tab_activity_ui()
                except RuntimeError as exc:
                    if not _is_stale_ui_error(exc):
                        raise

        task = asyncio.create_task(run(), name=f'harnessy-file-{label.lower().replace(" ", "-")}')
        _FILE_OPERATION_TASKS.add(task)
        task.add_done_callback(_FILE_OPERATION_TASKS.discard)

    async def _file_upload(self, e: events.UploadEventArguments, ws: WorkspaceStore, destination: Path) -> None:
        tab_key = self._tool_tab_key('files', ws.id)
        release_activity = TAB_ACTIVITY.acquire(tab_key)
        self._sync_tab_activity_ui()
        try:
            target = _unique_external_path(destination / Path(e.file.name).name)
            await e.file.save(target)
            ui.notify(f'Uploaded {target.name}', type='positive')
        except Exception as exc:
            ui.notify(f'Upload failed: {exc}', type='negative')
        finally:
            release_activity()
            self.refresh_tabs()
            self._sync_tab_activity_ui()

    def _file_set_clipboard(self, ws: WorkspaceStore | ToolScope, paths: Path | list[Path], mode: str) -> None:
        items = [paths] if isinstance(paths, Path) else list(paths)
        items = [p.resolve() for p in items if p.exists() and self._file_path_in_scope(ws, p)]
        if not items:
            return
        self.file_clipboard[ws.id] = {'paths': [str(p) for p in items], 'mode': mode}
        verb = 'Copied' if mode == 'copy' else 'Cut'
        ui.notify(f"{verb} {len(items)} item{'s' if len(items) != 1 else ''}")
        if self.active_tab_key == self._tool_tab_key('files', ws.id):
            self.refresh_tabs()

    def _file_paste(self, ws: WorkspaceStore | ToolScope, destination: Path) -> None:
        clip = self.file_clipboard.get(ws.id)
        if not clip:
            return
        sources = [Path(str(raw)).resolve() for raw in clip.get('paths') or []]
        sources = [p for p in sources if p.exists() and self._file_path_in_scope(ws, p)]
        if not sources:
            ui.notify('Paste failed: Clipboard items no longer exist in this File Explorer scope', type='negative')
            return
        dest = destination.resolve()
        if not self._file_path_in_scope(ws, dest):
            ui.notify('Paste failed: destination is outside this File Explorer scope', type='negative')
            return
        mode = str(clip.get('mode') or 'copy')

        def work() -> int:
            created = 0
            for source in sources:
                if source.is_dir() and dest.is_relative_to(source):
                    raise ValueError(f'Cannot paste {source.name} into itself')
                target = _unique_external_path(dest / source.name)
                if mode == 'cut':
                    shutil.move(str(source), str(target))
                elif source.is_dir() and not source.is_symlink():
                    shutil.copytree(source, target)
                else:
                    shutil.copy2(source, target, follow_symlinks=False)
                created += 1
            return created

        def success(count: int) -> str:
            if mode == 'cut':
                self.file_clipboard.pop(ws.id, None)
            return f"Pasted {count} item{'s' if count != 1 else ''}"

        self._launch_file_operation(ws, 'Paste', work, success)

    def _file_new_folder(self, ws: WorkspaceStore, current: Path) -> None:
        self._name_dialog('New folder', 'Folder name', lambda name: (current / name).mkdir(parents=False, exist_ok=False))

    def _file_new_file(self, ws: WorkspaceStore, current: Path) -> None:
        def create(name: str) -> None:
            p = current / name
            p.parent.mkdir(parents=True, exist_ok=True)
            p.touch(exist_ok=False)
            self.open_file_tab(ws, p)
        self._name_dialog('New file', 'File name', create)

    def _name_dialog(self, title: str, label: str, action) -> None:
        with ui.dialog() as dialog, ui.card().classes('w-[470px] max-w-[92vw]'):
            ui.label(title).classes('text-lg font-semibold')
            field = ui.input(label).classes('w-full')
            def do() -> None:
                try:
                    name = (field.value or '').strip()
                    if not name or name in {'.','..'} or '/' in name:
                        raise ValueError('Enter a simple name')
                    action(name)
                    dialog.close()
                    self.refresh_tabs()
                except Exception as exc:
                    ui.notify(str(exc), type='negative')
            with ui.row().classes('w-full justify-end'):
                ui.button('Cancel', on_click=dialog.close).props('flat no-caps')
                ui.button('Create', on_click=do).props('unelevated no-caps')
        dialog.open()

    def _render_file_tab(self, tab: OpenTab, ws: WorkspaceStore | ToolScope) -> None:
        if not tab.file_path:
            ui.label('This file tab has no path. Close it and reopen the file.').classes('text-negative p-4')
            return
        path = Path(tab.file_path)
        readonly = isinstance(ws, ToolScope) and ws.read_only
        if not self._file_path_in_scope(ws, path):
            ui.label('This file is no longer in the selected canonical project scope. Reopen Project Files.').classes('text-negative p-4')
            return
        state = self.file_editor_states.get(tab.key)
        if state is None:
            try:
                resolved = path.expanduser().resolve(strict=True)
                if not self._file_path_in_scope(ws, resolved):
                    raise ValueError('The file is outside this File Explorer scope.')
                draft = TextFileDraft.open(resolved)
            except (OSError, ValueError) as exc:
                ui.label(f'Cannot open {path}: {exc}').classes('text-negative p-4')
                return
            state = {'draft': draft, 'value': draft.text}
            self.file_editor_states[tab.key] = state
        draft = state['draft']
        if str(state.get('value') or '') == str(draft.text):
            try:
                fresh = TextFileDraft.open(path)
                if fresh.digest != draft.digest:
                    state['draft'] = fresh
                    state['value'] = fresh.text
                    draft = fresh
            except (OSError, ValueError):
                # Preserve the last readable state in the tab; Save/Revert will surface a precise error.
                pass
        markdown = path.suffix.lower() in {'.md', '.markdown', '.mdown', '.mkd'}

        if readonly:
            with ui.column().classes('hy-tool-panel hy-file-document-tab w-full no-wrap gap-0'):
                with ui.row().classes('hy-editor-header w-full items-center no-wrap px-4 py-2'):
                    ui.label(f'{path.name} · Read-only project view').classes('font-semibold text-sm')
                    ui.button(icon='fingerprint', on_click=lambda: self.open_file_fingerprint(ws, path)).props('flat round dense aria-label="File Fingerprint / Properties"').tooltip('File Fingerprint / Properties')
                    ui.button(icon='download', on_click=lambda: self._download_scope_file(ws, path)).props('flat round dense aria-label="Download exact file"').tooltip('Download exact file')
                ui.label(self._file_display_path(ws, path)).classes('text-xs hy-muted px-4 break-all')
                ui.textarea(value=str(state.get('value') or '')).props('outlined readonly rows=1 aria-label="File viewer"').classes('hy-fill-editor hy-file-editor hy-file-viewer w-full')
            return

        with ui.column().classes('hy-tool-panel hy-file-document-tab w-full no-wrap gap-0'):
            with ui.row().classes('hy-editor-header w-full items-center no-wrap px-4 py-2'):
                with ui.column().classes('gap-0 min-w-0 flex-grow'):
                    ui.label(path.name).classes('font-semibold text-sm')
                    ui.label(str(path)).classes('hy-editor-path text-xs hy-muted').tooltip(str(path))
                dirty_label = ui.label('').classes('text-xs hy-muted')

            with ui.tabs().classes('hy-editor-toolbar w-full') as tabs:
                viewer_tab = ui.tab('Viewer')
                edit_tab = ui.tab('Edit')
            with ui.tab_panels(tabs, value=viewer_tab).classes('hy-file-editor-panels hy-editor-body w-full bg-transparent'):
                with ui.tab_panel(viewer_tab).classes('hy-file-preview-panel p-0'):
                    if markdown:
                        with ui.element('div').classes('hy-file-preview'):
                            viewer = ui.markdown(str(state.get('value') or ''), sanitize=True).classes('w-full hy-assistant')
                    else:
                        with ui.column().classes('hy-editor-body w-full p-3'):
                            viewer = ui.textarea(value=str(state.get('value') or '')).props(
                                'outlined readonly rows=1 aria-label="File viewer"'
                            ).classes('hy-fill-editor hy-file-editor hy-file-viewer w-full')
                with ui.tab_panel(edit_tab).classes('hy-file-edit-panel p-0'):
                    with ui.column().classes('hy-editor-body w-full p-3'):
                        editor = ui.textarea(value=str(state.get('value') or '')).props(
                            'outlined rows=1 aria-label="File source"'
                        ).classes('hy-fill-editor hy-file-editor w-full')
                        editor.on('keydown', js_handler='(e) => e.stopPropagation()')

            def sync_dirty() -> None:
                dirty = str(state.get('value') or '') != str(state['draft'].text)
                dirty_label.set_text('Unsaved changes' if dirty else 'Saved')
                dirty_label.classes(replace='text-xs text-warning' if dirty else 'text-xs hy-muted')

            def update_viewer(value: str) -> None:
                if markdown:
                    viewer.set_content(value)
                else:
                    viewer.set_value(value)

            def changed(e) -> None:
                state['value'] = str(e.value or '')
                update_viewer(state['value'])
                sync_dirty()

            editor.on_value_change(changed)

            def save() -> None:
                try:
                    changed_on_disk = state['draft'].save(str(state.get('value') or ''))
                    # TextFileDraft.save updates its baseline text/digest in place.
                    sync_dirty()
                    ui.notify('Saved' if changed_on_disk else 'No changes to save', type='positive')
                except (OSError, ValueError) as exc:
                    ui.notify(str(exc), type='negative', timeout=10000)

            def revert() -> None:
                try:
                    fresh = TextFileDraft.open(path)
                    state['draft'] = fresh
                    state['value'] = fresh.text
                    editor.set_value(fresh.text)
                    update_viewer(fresh.text)
                    sync_dirty()
                    ui.notify('Reloaded from disk', type='positive')
                except (OSError, ValueError) as exc:
                    ui.notify(str(exc), type='negative', timeout=10000)

            with ui.row().classes('hy-editor-footer w-full items-center p-3'):
                ui.label('Viewer is read-only. Changes reach the file only when you press Save.').classes('text-xs hy-muted')
                ui.space()
                ui.button('Revert', on_click=revert).props('flat no-caps').tooltip('Discard this draft and reload the current file from disk')
                ui.button('Save', on_click=save).props('unelevated no-caps')
            sync_dirty()

    def _file_zip(self, ws: WorkspaceStore | ToolScope, paths: Path | list[Path]) -> None:
        items = [paths] if isinstance(paths, Path) else list(paths)
        items = [p.resolve() for p in items if p.exists()]
        if not items:
            return

        def work() -> Path:
            import zipfile
            if len(items) == 1:
                path = items[0]
                if path.is_dir():
                    output = _unique_external_path(path.parent / f'{path.name}.zip')
                    make_zip(path, output, exclude_names={FILES_PROBE_DIR_NAME})
                else:
                    output = _unique_external_path(path.parent / f'{path.stem}.zip')
                    with zipfile.ZipFile(output, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
                        zf.write(path, path.name)
            else:
                parent = items[0].parent
                output = _unique_external_path(parent / 'selection.zip')
                with zipfile.ZipFile(output, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
                    for item in items:
                        if item.is_dir() and not item.is_symlink():
                            for child in item.rglob('*'):
                                if child.is_file() and FILES_PROBE_DIR_NAME not in child.relative_to(item).parts:
                                    zf.write(child, Path(item.name) / child.relative_to(item))
                        elif item.is_file() and item.name != FILES_PROBE_DIR_NAME:
                            zf.write(item, item.name)
            return output

        self._launch_file_operation(ws, 'ZIP', work, lambda output: f'Created {output.name}')

    def _file_extract(self, ws: WorkspaceStore | ToolScope, path: Path, mode: str) -> None:
        def work() -> str:
            if mode == 'here':
                safe_extract_archive(path, path.parent)
                return f'Extracted {path.name} here'
            if mode == 'folder':
                dest = _unique_external_path(path.parent / _archive_base_name(path))
                dest.mkdir(parents=True, exist_ok=False)
                safe_extract_archive(path, dest)
                return f'Extracted to {dest.name}'
            raise ValueError(f'Unknown extraction mode: {mode}')

        self._launch_file_operation(ws, 'Extract', work, lambda message: message)

    def _file_rename(self, path: Path) -> None:
        with ui.dialog() as dialog, ui.card().classes('w-[470px] max-w-[92vw]'):
            ui.label('Rename').classes('text-lg font-semibold')
            field = ui.input('Name', value=path.name).classes('w-full')
            def rename() -> None:
                try:
                    name = (field.value or '').strip()
                    if not name or '/' in name:
                        raise ValueError('Invalid name')
                    path.rename(path.with_name(name))
                    dialog.close(); self.refresh_tabs()
                except Exception as exc:
                    ui.notify(str(exc), type='negative')
            with ui.row().classes('w-full justify-end'):
                ui.button('Cancel', on_click=dialog.close).props('flat no-caps')
                ui.button('Rename', on_click=rename).props('unelevated no-caps')
        dialog.open()

    def _file_delete(self, ws: WorkspaceStore | ToolScope, paths: Path | list[Path]) -> None:
        items = [paths] if isinstance(paths, Path) else list(paths)
        items = [p.expanduser().absolute() for p in items if p.exists() or p.is_symlink()]
        if not items:
            return
        try:
            for path in items:
                if path.is_dir() and not path.is_symlink():
                    validate_workspace_delete_target(
                        path, state_root=self.machine.root,
                        other_workspace_roots=(item.path for item in self.machine.list_workspaces()),
                    )
        except ValueError as exc:
            ui.notify(f'Cannot delete this folder: {exc}', type='negative', timeout=9000)
            return
        with ui.dialog() as dialog, ui.card().classes('w-[600px] max-w-[92vw]'):
            ui.label('Delete permanently?').classes('text-lg font-semibold')
            if len(items) == 1:
                ui.label(str(items[0])).classes('text-sm')
            else:
                ui.label(f"{len(items)} selected items").classes('text-sm font-semibold')
                with ui.column().classes('w-full max-h-[220px] overflow-y-auto gap-1'):
                    for path in items[:100]:
                        ui.label(str(path)).classes('text-xs hy-file-name')
                    if len(items) > 100:
                        ui.label(f'+ {len(items) - 100} more').classes('text-xs hy-muted')
            ui.label('This permanently deletes the selected host file(s) and cannot be undone by HarnessyXO. Workspace File Explorer actions are confined to that workspace’s Files/ directory; Home File Explorer remains an explicit user-only host utility.').classes('text-xs text-negative')
            def delete() -> None:
                dialog.close()
                def work() -> int:
                    removed = 0
                    for path in items:
                        if not path.exists() and not path.is_symlink():
                            continue
                        if path.is_dir() and not path.is_symlink():
                            validate_workspace_delete_target(
                                path, state_root=self.machine.root,
                                other_workspace_roots=(item.path for item in self.machine.list_workspaces()),
                            )
                            shutil.rmtree(path)
                        else:
                            path.unlink()
                        removed += 1
                    return removed
                self._launch_file_operation(
                    ws, 'Delete', work,
                    lambda count: f"Deleted {count} item{'s' if count != 1 else ''}",
                )
            with ui.row().classes('w-full justify-end'):
                ui.button('Cancel', on_click=dialog.close).props('flat no-caps')
                ui.button('Delete', on_click=delete).props('unelevated no-caps color=negative')

            # Keyboard belongs to the confirmation dialog, not whichever button
            # happens to own focus. Prevent the browser from also activating a
            # focused control so one Enter press can only perform one action.
            dialog.on(
                'keydown',
                lambda e: delete() if (e.args or {}).get('key') == 'Enter' else dialog.close(),
                js_handler="""(e) => {
                    if (e.key !== 'Enter' && e.key !== 'Escape') return;
                    const t = e.target;
                    const editable = t && (t.matches?.('input, textarea, select') || t.isContentEditable);
                    if (e.key === 'Enter' && editable) return;
                    e.preventDefault(); e.stopPropagation(); emit({key:e.key});
                }""",
            )
        dialog.open()

    # --------------------------------------------------------------- terminal
    def _render_terminal_tab(self, tab: OpenTab, ws: WorkspaceStore | ToolScope) -> None:
        session = self.terminal_sessions.get(tab.key)
        manager = EnvironmentManager(ws.root, environment_id=tab.environment_id) if isinstance(ws, WorkspaceStore) else None
        config = manager.config if manager is not None and tab.environment_id else None
        is_workspace_vm = isinstance(ws, WorkspaceStore) and config is not None
        guest_console = bool(is_workspace_vm and getattr(tab, 'terminal_mode', 'guest_console') != 'project_files')
        try:
            guest_file_capabilities = dict(manager.provider().file_view_capabilities()) if guest_console else {}
        except Exception:
            guest_file_capabilities = {}
        project = ws.get_chat(tab.chat_id) if is_workspace_vm and not guest_console and tab.chat_id else None
        project_label = f'{project.title} · {project.public_id}' if project is not None else 'Unavailable project'
        if isinstance(ws, WorkspaceStore) and config is None:
            # A saved terminal never attaches to an arbitrary replacement VM.
            session = None

        if session is None and is_workspace_vm:
            error = self.terminal_errors.get(tab.key)
            error_code = self.terminal_error_codes.get(tab.key, '')
            pending_view = error_code in {'FILE_VIEW_PENDING', 'FILE_VIEW_POLICY_CHANGED'}
            environment_busy = ENVIRONMENT_OPERATIONS.is_busy(ws.root, environment_id=config.id)
            with ui.column().classes('hy-tool-panel hy-terminal-panel w-full no-wrap gap-0'):
                with ui.row().classes('hy-tool-toolbar w-full items-center py-2 flex-wrap gap-2').style('border-bottom:1px solid var(--hy-border); min-width:0'):
                    ui.label(tab.title).classes('font-semibold').style('min-width:0;max-width:100%;overflow-wrap:anywhere')
                    base_label = ui.label(f'🛡 {config.name} · Guest console' if guest_console else f'🛡 {config.name} · {project_label}').classes('text-xs hy-muted').style('overflow-wrap:anywhere')
                    base_label.tooltip(
                        _guest_console_files_text(guest_file_capabilities)
                        if guest_console else
                        'Uses the same project file view as model commands: own files, read-only ancestors, '
                        'direct Project Access sources and References.'
                    )
                with ui.column().classes('w-full h-full items-center justify-center gap-3'):
                    if error:
                        ui.icon('schedule' if pending_view else 'error_outline', size='34px').classes('text-warning' if pending_view else 'text-negative')
                        ui.label('References access changed' if guest_console and error_code == 'FILE_VIEW_POLICY_CHANGED' else 'Waiting for References' if guest_console and pending_view else 'Project file access changed' if error_code == 'FILE_VIEW_POLICY_CHANGED' else 'Waiting for project files' if pending_view else 'Workspace VM terminal could not start').classes('font-semibold text-warning' if pending_view else 'font-semibold text-negative')
                        ui.label(error).classes('text-sm hy-muted').style('max-width:760px;white-space:pre-wrap')
                        if pending_view:
                            ui.label(
                                'Close other Guest consoles using the previous References view, then Retry to prepare the current read-only References.'
                                if guest_console else
                                'Retry to prepare this project’s files using the current saved access. A Guest console is available in Terminal options.'
                                if error_code == 'FILE_VIEW_POLICY_CHANGED' else
                                'Retry after the file-view update completes. If a view is in use, finish its work or close its project-files terminals first. A Guest console is available in Terminal options.'
                            ).classes('text-xs hy-muted').style('max-width:760px;overflow-wrap:anywhere')
                        def retry() -> None:
                            self.terminal_errors.pop(tab.key, None)
                            self.terminal_error_codes.pop(tab.key, None)
                            self.refresh_tabs()
                        ui.button('Retry', icon='refresh', on_click=retry).props('unelevated no-caps')
                        ui.button('Terminal options', icon='terminal', on_click=lambda: self._choose_vm_terminal(self._find_reg(ws.id), config.id)).props('flat no-caps')
                    else:
                        ui.spinner(size='34px')
                        if environment_busy:
                            op = ENVIRONMENT_OPERATIONS.state(ws.root, environment_id=config.id)
                            ui.label(op.message or 'Waiting for environment operation…').classes('font-semibold')
                            ui.label('The terminal will attach after the workspace environment is Ready.').classes('text-xs hy-muted')
                        else:
                            stage_label = ui.label(self.terminal_start_stages.get(tab.key) or ('Starting guest console…' if guest_console else 'Preparing project files terminal…')).classes('font-semibold').style('overflow-wrap:anywhere')
                            ui.label('HarnessyXO will not fall back to the host shell if the VM is unavailable.').classes('text-xs hy-muted')
                    if not guest_console:
                        from harnessy.ui.project_file_views import render_file_view_status
                        render_file_view_status(ws, config.id, project_id=str(tab.chat_id or ''), compact=True)
                    elif guest_file_capabilities.get('guest_references'):
                        from harnessy.ui.project_file_views import render_file_view_status
                        render_file_view_status(ws, config.id, compact=True, references=True)
            if not error and not environment_busy and tab.key not in self.terminal_start_tasks:
                async def boot_terminal() -> None:
                    preparation_release = None
                    try:
                        current = manager.config
                        if current is None:
                            raise RuntimeError('This VM environment is no longer registered.')
                        if not guest_console:
                            selected_project = ws.get_chat(str(tab.chat_id or ''))
                            if selected_project is None or selected_project.archived_at is not None or not current.allows_project(selected_project.id):
                                raise RuntimeError('This project is no longer allowed to use this VM. Choose an allowed project or open a Guest console.')
                        self.terminal_start_stages[tab.key] = 'Starting VM…'
                        # Terminal boot uses the same process-owned Environment
                        # operation manager as the Environment page. The job keeps
                        # running across a browser reload and carries a total
                        # deadline; the terminal task merely observes its result.
                        ENVIRONMENT_OPERATIONS.start(ws.root, 'start', environment_id=config.id)
                        operation_task = ENVIRONMENT_OPERATIONS.task(ws.root, environment_id=config.id)
                        if operation_task is not None:
                            await asyncio.shield(operation_task)
                        operation = ENVIRONMENT_OPERATIONS.state(ws.root, environment_id=config.id)
                        if operation.status != 'succeeded':
                            raise RuntimeError(operation.error or operation.message or 'Workspace environment did not become Ready.')
                        provider = manager.provider()
                        status = await provider.status()
                        if not status.running or not status.ready:
                            raise RuntimeError(status.error or status.detail or f'VM state is {status.state}')
                        from harnessy.environment.file_views import FILE_VIEWS
                        if guest_console:
                            # Keep the References namespace stable through PTY
                            # construction. Only this preparation owner may be
                            # exempted; existing Guest consoles still hold it.
                            console_capabilities = dict(provider.file_view_capabilities())
                            self.terminal_start_stages[tab.key] = 'Preparing read-only References…' if console_capabilities.get('guest_references') else 'Opening guest console…'
                            preparation_release = await FILE_VIEWS.acquire_terminal_activity(
                                ws.root, environment_id=config.id,
                                project_id='__guest_console__', owner_id=tab.key,
                                label='Opening guest console',
                            )
                            argv, env, cwd = await provider.open_guest_terminal(workspace=ws, owner_id=tab.key)
                        else:
                            self.terminal_start_stages[tab.key] = 'Preparing this project’s file view…'
                            preparation_release = await FILE_VIEWS.acquire_terminal_activity(
                                ws.root, environment_id=config.id,
                                project_id=str(tab.chat_id), owner_id=tab.key,
                                label='Opening project terminal',
                            )
                            policy = await FILE_VIEWS.ensure_project(
                                ws.root, environment_id=config.id, project_id=str(tab.chat_id), owner_id=tab.key, human=True,
                            )
                            policy = {**policy, '_file_view_owner_id': tab.key}
                            active_root = ws.active_root_path(str(tab.chat_id))
                            self.terminal_start_stages[tab.key] = 'Opening project files terminal…'
                            argv, env, cwd = await provider.open_project_terminal(
                                active_root=active_root, output_policy=policy, workspace=ws,
                            )
                        construction = asyncio.create_task(asyncio.to_thread(
                            TerminalSession, cwd, command_argv=argv, env=env,
                            workspace_root=ws.root, environment_id=config.id,
                            project_id='__guest_console__' if guest_console else str(tab.chat_id), owner_id=tab.key))
                        try:
                            created = await asyncio.shield(construction)
                        except asyncio.CancelledError:
                            # Repeated close/shutdown requests must not cancel
                            # the future while its thread still creates a PTY.
                            # Keep the preparation lease until that handle can
                            # be retrieved and closed.
                            while not construction.done():
                                try:
                                    await asyncio.shield(construction)
                                except asyncio.CancelledError:
                                    continue
                                except Exception:
                                    break
                            if not construction.cancelled():
                                try:
                                    orphan = construction.result()
                                except Exception:
                                    pass
                                else:
                                    orphan.close()
                            raise
                        if guest_console:
                            created.guest_references_path = str(console_capabilities.get('guest_references_path') or '/workspace/Files/References') if console_capabilities.get('guest_references') else ''
                        log_event(
                            'runtime', 'workspace_terminal_started', workspace=str(ws.root),
                            provider=status.provider, environment_id=config.id,
                            guest_cwd='guest_home' if guest_console else '/workspace',
                            terminal_mode='guest_console' if guest_console else 'project_files', cpu_only=True,
                            project_id=None if guest_console else tab.chat_id,
                        )
                        # The PTY is backend-owned. Closing the tab cancels this
                        # task explicitly; a browser reload merely destroys the
                        # old NiceGUI page and must not destroy the terminal.
                        self.terminal_sessions[tab.key] = created
                        self.terminal_errors.pop(tab.key, None)
                        self.terminal_error_codes.pop(tab.key, None)
                    except asyncio.CancelledError:
                        raise
                    except Exception as exc:
                        self.terminal_errors[tab.key] = str(exc)
                        code = str(getattr(exc, 'error_code', '') or '')
                        self.terminal_error_codes[tab.key] = code if code in {'FILE_VIEW_PENDING', 'FILE_VIEW_UNSUPPORTED', 'FILE_VIEW_FAILED', 'FILE_VIEW_POLICY_CHANGED'} else ''
                        log_event('harnessy', 'workspace_terminal_start_failed', workspace=str(ws.root), environment_id=config.id,
                                  terminal_mode='guest_console' if guest_console else 'project_files',
                                  error_code=self.terminal_error_codes[tab.key], error=str(exc))
                    finally:
                        if preparation_release is not None:
                            preparation_release()
                        self.terminal_start_tasks.pop(tab.key, None)
                        self.terminal_start_stages.pop(tab.key, None)
                # Do not use NiceGUI's background task wrapper here: this job must
                # outlive the page/client which happened to request the terminal.
                self.terminal_start_tasks[tab.key] = asyncio.create_task(
                    boot_terminal(), name=f'harnessy-terminal-start-{tab.key}'
                )
            if not error:
                async def watch_terminal_start() -> None:
                    if not environment_busy and not stage_label.is_deleted:
                        stage_label.set_text(self.terminal_start_stages.get(tab.key) or ('Starting guest console…' if guest_console else 'Preparing project files terminal…'))
                    if environment_busy:
                        if ENVIRONMENT_OPERATIONS.is_busy(ws.root, environment_id=config.id):
                            return
                    task = self.terminal_start_tasks.get(tab.key)
                    if environment_busy or self.terminal_sessions.get(tab.key) is not None or self.terminal_errors.get(tab.key) or task is None or task.done():
                        try:
                            self.refresh_tabs()
                        except RuntimeError as exc:
                            if not _is_stale_ui_error(exc):
                                raise
                # This timer belongs to the rendered page only; the actual
                # terminal boot task is backend-owned/global. After a browser
                # reload the new page can therefore notice completion and attach
                # to the same PTY instead of spinning forever.
                ui.timer(0.4, watch_terminal_start)
            return

        if session is None and isinstance(ws, WorkspaceStore):
            # Old/non-VM workspaces are intentionally not given their historical
            # host PTY. Backward compatibility is less important than preserving
            # the VM-first host isolation invariant.
            with ui.column().classes('hy-tool-panel hy-terminal-panel w-full no-wrap gap-0'):
                with ui.row().classes('hy-tool-toolbar w-full items-center py-2 flex-wrap gap-2').style('border-bottom:1px solid var(--hy-border); min-width:0'):
                    ui.label(tab.title).classes('font-semibold').style('min-width:0;max-width:100%;overflow-wrap:anywhere')
                    ui.label('Workspace environment unavailable').classes('text-xs text-negative')
                with ui.column().classes('w-full h-full items-center justify-center gap-3'):
                    ui.icon('shield', size='34px').classes('text-negative')
                    ui.label('This workspace has no sandboxed VM').classes('font-semibold')
                    ui.label('HarnessyXO will not open a host shell for a workspace. Create a VM in Environments, then open its terminal.').classes('text-sm hy-muted').style('max-width:760px;text-align:center')
            return

        if session is None:
            try:
                # The Home terminal is an explicit user-operated host utility.
                session = TerminalSession(ws.root)
                self.terminal_sessions[tab.key] = session
            except Exception as exc:
                ui.label(f'Cannot start terminal: {exc}').classes('text-negative p-4')
                return

        started_label = ('guest home (guest console)' if guest_console else f'{project_label} (project files)') if is_workspace_vm else str(ws.root)
        with ui.column().classes('hy-tool-panel hy-terminal-panel w-full no-wrap gap-0'):
            with ui.row().classes('hy-tool-toolbar w-full items-center py-2 flex-wrap gap-2').style('border-bottom:1px solid var(--hy-border); min-width:0'):
                ui.label(tab.title).classes('font-semibold').style('min-width:0;max-width:100%;overflow-wrap:anywhere')
                started_location = ui.label(f'Started in {started_label}').classes('text-xs hy-muted hy-file-name').style('max-width:680px')
                if guest_console:
                    started_location.tooltip(_guest_console_files_text(guest_file_capabilities))
                if is_workspace_vm:
                    ui.label(f'🛡 {config.name} · {config.architecture} · CPU only').classes('text-xs hy-muted')
                    ui.button('New terminal…', icon='add', on_click=lambda: self._choose_vm_terminal(self._find_reg(ws.id), config.id)).props('flat dense no-caps')
                ui.space()
                with ui.row().classes('items-center no-wrap gap-1'):
                    ui.button('Ctrl+C', on_click=session.interrupt).props('flat dense no-caps')
                    safe_dom_id = re.sub(r'[^A-Za-z0-9_-]+', '-', tab.key)
                    term_dom_id = f'hy-xterm-{safe_dom_id}'
                    clear_button = ui.button('Clear').props('flat dense no-caps')
            if is_workspace_vm and guest_console:
                verified_references = str(getattr(session, 'guest_references_path', '') or '')
                ui.label(
                    f'References read-only · {verified_references}' if verified_references else
                    'References are not verified for this open console. Reopen it to prepare read-only References.' if guest_file_capabilities.get('guest_references') else
                    'Live References are unavailable in this VM’s Guest console.'
                ).classes('text-xs hy-muted px-4 py-1').style('overflow-wrap:anywhere;min-width:0;max-width:100%')
                if guest_file_capabilities.get('guest_references'):
                    from harnessy.ui.project_file_views import render_file_view_status
                    render_file_view_status(ws, config.id, compact=True, references=True)
            if is_workspace_vm and not guest_console:
                from harnessy.ui.project_file_views import render_file_view_status
                render_file_view_status(ws, config.id, project_id=str(tab.chat_id or ''), compact=True)
            terminal_el = ui.element('div').classes('hy-terminal-shell hy-xterm').props(f'id={term_dom_id}')
            clear_button.on('click', js_handler=f"() => window.harnessyTerminalClear && window.harnessyTerminalClear({json.dumps(tab.key)})")
            client = terminal_el.client
            client.run_javascript(
                f"window.harnessyCreateTerminal && window.harnessyCreateTerminal({json.dumps(term_dom_id)}, {json.dumps(tab.key)}, {json.dumps(ws.id)});",
                timeout=2.0,
            )

            cursor, history = session.history_snapshot()
            cursor_state = {'value': cursor}
            if history:
                client.run_javascript(
                    f"window.harnessyTerminalWrite && window.harnessyTerminalWrite({json.dumps(tab.key)}, {json.dumps(history)});",
                    timeout=2.0,
                )

            async def poll() -> None:
                next_cursor, chunk = session.read_since(cursor_state['value'])
                cursor_state['value'] = next_cursor
                if chunk:
                    try:
                        await client.run_javascript(
                            f"window.harnessyTerminalWrite && window.harnessyTerminalWrite({json.dumps(tab.key)}, {json.dumps(chunk)});",
                            timeout=2.0,
                        )
                    except Exception:
                        pass
            ui.timer(0.08, poll)

    def _render_environment_tab(self, tab: OpenTab, ws: WorkspaceStore) -> None:
        from harnessy.ui.vm_environments import render_vm_environments
        render_vm_environments(self, tab, ws)

    def _render_vm_environment_details(self, tab: OpenTab, ws: WorkspaceStore, environment_id: str, *, embedded: bool = True, dialog_parent: Any = None) -> None:
        manager = EnvironmentManager(ws.root, environment_id=environment_id)
        config = manager.config

        def make_details_dialog():
            # NiceGUI also creates a lifetime canary in the construction slot.
            # Construct under the stable owner; moving only the dialog cannot
            # protect it when the original card and that canary are collected.
            with dialog_parent if dialog_parent is not None else nullcontext():
                return ui.dialog()

        status_label = readiness_detail = None
        operation_banner = None
        open_terminal_button = start_button = stop_button = None
        panel_classes = 'w-full min-w-0 gap-0' if embedded else 'hy-tool-panel w-full no-wrap gap-0'
        with ui.column().classes(panel_classes) as detail_panel:
            if not embedded:
                with ui.row().classes('w-full items-center px-4 py-2 gap-2').style('border-bottom:1px solid var(--hy-border)'):
                    ui.icon('shield', size='20px')
                    ui.label(config.name if config else 'VM Environment').classes('font-semibold')
            with ui.column().classes('w-full min-w-0' if embedded else 'w-full overflow-y-auto').style('' if embedded else 'flex:1'):
                if not config:
                    ui.label('This VM environment is no longer registered.').classes('text-sm hy-muted')
                    return

                preset = get_preset(config.preset)
                from harnessy.ui.vm_environments import network_policy_text
                network_label, network_description = network_policy_text(config.provider)
                network_prefix = 'Public outbound' if config.provider == 'lima' else 'Outbound network'
                guest_project_root = 'C:/harnessy/workspace' if config.provider == 'managed' else '/workspace'
                configured_optional = tuple(config.optional_tools or ())
                selected_optional_tools = tuple(
                    preset.optional_tool_ids if '*' in configured_optional
                    else (tool for tool in preset.optional_tool_ids if tool in configured_optional)
                )
                selected_subtab = getattr(self, 'environment_subtabs', {}).get(f'{ws.id}:{environment_id}', 'Details')
                if selected_subtab not in {'Details', 'Snapshots'}:
                    selected_subtab = 'Details'
                with ui.tabs(value=selected_subtab).classes('hy-env-width px-3').props('dense no-caps align=left indicator-color=primary') as env_tabs:
                    details_tab = ui.tab('Details')
                    snapshots_tab = ui.tab('Snapshots')
                if not hasattr(self, 'environment_subtabs'):
                    self.environment_subtabs = {}

                def remember_subtab(e) -> None:
                    value = str(e.value or 'Details')
                    self.environment_subtabs[f'{ws.id}:{environment_id}'] = value
                    self._save_ui_session()

                env_tabs.on_value_change(remember_subtab)

                with ui.tab_panels(env_tabs, value=selected_subtab, animated=False).classes('w-full bg-transparent') as environment_panels:
                    with ui.tab_panel(details_tab).classes('p-0'):
                        with ui.column().classes('hy-env-width p-4 gap-4'):
                            with ui.row().classes('w-full gap-3 flex-wrap items-stretch'):
                                if not embedded:
                                    with ui.card().classes('hy-env-card p-4 gap-1 min-w-0').style('flex:1 1 280px;max-width:100%'):
                                        ui.label('Environment').classes('text-xs hy-muted')
                                        status_label = ui.label('Checking…').classes('text-lg font-semibold')
                                        ui.label(preset.name).classes('text-sm')
                                        ui.label(f'{config.architecture} · CPU only · {guest_project_root}').classes('text-xs hy-muted')
                                        readiness_detail = ui.label('').classes('text-xs hy-muted').style('white-space:pre-wrap;overflow-wrap:anywhere')
                                with ui.card().classes('hy-env-card p-4 gap-1 min-w-0').style('flex:1 1 280px;max-width:100%'):
                                    from .workspace_resources import WorkspaceResourceEditor
                                    resource_editor = WorkspaceResourceEditor(config, lambda **payload: queue_action('resources', **payload), dialog_parent=dialog_parent)
                                    disk_usage_label = ui.label('VM storage on host: checking…').classes('text-xs hy-muted')
                                    network_status_label = ui.label(f'{network_prefix} enabled' if config.network else f'{network_prefix} disabled').classes('text-xs hy-muted')
                                    if preset.optional_tool_ids:
                                        optional_tools_summary_label = ui.label(
                                            f'Optional tools selected: {len(selected_optional_tools)}/{len(preset.optional_tool_ids)}' +
                                            ('' if config.network or config.provider == 'openwrt' else ' · downloads skipped while outbound is off')
                                        ).classes('text-xs hy-muted')
                                    else:
                                        optional_tools_summary_label = None
                                with ui.card().classes('hy-env-card p-4 gap-1 min-w-0').style('flex:1.5 1 340px;max-width:100%'):
                                    ui.label('Project file view').classes('text-xs hy-muted')
                                    ui.label(guest_project_root).classes('text-sm font-semibold')
                                    ui.label('Workspace source location').classes('text-xs hy-muted')
                                    ui.label(str(ws.files_root)).classes('text-xs hy-muted').style('max-width:100%;min-width:0;white-space:normal;overflow-wrap:anywhere')
                                    from harnessy.ui.vm_environments import FILE_MODES
                                    ui.label(FILE_MODES.get(config.files_mode, config.files_mode)).classes('text-sm font-semibold')
                                    ui.label('Project commands and Project files terminals use the same view: own files plus read-only ancestors, direct Project Access sources and References. Guest console uses a separate home view, with live read-only References where supported.').classes('text-xs hy-muted')
                                    if config.files_mode == 'copy':
                                        ui.label('These are independent copies. Access updates cannot recall files already deployed or read; existing guest files are preserved.').classes('text-xs hy-muted')
                                    ui.label('Workspace source files are preserved when this VM is reset or rebuilt.').classes('text-xs hy-muted')
                                    if config.provider == 'openwrt':
                                        ui.label('System administration is available in Separate project copy mode.' if config.files_mode != 'copy' else 'System administration is available inside this guest. Deploy and collect project files explicitly.').classes('text-xs hy-muted')

                            if not embedded:
                                with ui.row().classes('hy-env-status-banner w-full items-start gap-3 p-3') as operation_banner:
                                    operation_spinner = ui.spinner(size='20px').classes('hy-vm-busy-spinner')
                                    operation_icon = ui.icon('info', size='20px')
                                    with ui.column().classes('gap-1').style('flex:1;min-width:0'):
                                        operation_message = ui.label('Checking environment…').classes('text-sm font-semibold')
                                        operation_detail = ui.label('').classes('text-xs hy-muted').style('white-space:pre-wrap;overflow-wrap:anywhere')
                                        operation_progress = ui.linear_progress(value=0).classes('hy-vm-busy-progress w-full').props('rounded size=6px')
                                        operation_timing = ui.label('').classes('text-xs hy-muted').style('font-variant-numeric:tabular-nums')
                                        operation_error = ui.label('').classes('text-xs hy-muted').style('white-space:pre-wrap;max-height:180px;overflow:auto')

                            if not embedded:
                                with ui.card().classes('hy-env-card w-full p-4 gap-3'):
                                    ui.label('Environment Controls').classes('font-semibold')
                                    ui.label('Terminals and model tools are available only when the environment is Ready.').classes('text-xs hy-muted')
                                    with ui.row().classes('gap-2 flex-wrap'):
                                        open_terminal_button = ui.button(
                                            'Open Terminal', icon='terminal',
                                            on_click=lambda: self.open_tool_tab('terminal', self._find_reg(tab.workspace_id), environment_id=environment_id),
                                        ).props('unelevated no-caps')
                                        start_button = ui.button('Start', icon='play_arrow').props('flat no-caps')
                                        stop_button = ui.button('Stop', icon='stop').props('flat no-caps')

                            if preset.optional_tool_ids:
                                with ui.card().classes('hy-env-card w-full p-4 gap-2'):
                                    with ui.row().classes('w-full items-center gap-2 flex-wrap'):
                                        with ui.column().classes('gap-0').style('flex:1;min-width:240px'):
                                            ui.label('Optional tools').classes('font-semibold')
                                            optional_manage_summary = ui.label(
                                                f'{len(selected_optional_tools)}/{len(preset.optional_tool_ids)} selected for this VM.'
                                            ).classes('text-xs hy-muted')
                                        manage_tools_button = ui.button(
                                            'Manage Optional Tools', icon='construction'
                                        ).props('outline no-caps')
                                    ui.label(
                                        'Change the saved selection after creation. Newly selected missing tools can be installed into a running VM without rebuilding it.'
                                    ).classes('text-xs hy-muted')
                                    if 'rea' in preset.optional_tool_ids:
                                        ui.label(
                                            'Select REA in Manage Optional Tools and apply to install or update its CLI inside this VM. '
                                            'The model uses it through Shell commands or Long-running processes.'
                                        ).classes('text-xs hy-muted')
                            else:
                                optional_manage_summary = None
                                manage_tools_button = None

                            with ui.card().classes('hy-env-card w-full p-4 gap-2'):
                                ui.label('Network policy').classes('font-semibold')
                                network_switch = ui.switch(network_label, value=bool(config.network)).props('dense')
                                ui.label(network_description).classes('text-xs hy-muted')
                                ui.label('Changing this policy preserves VM storage and workspace source.').classes('text-xs hy-muted')
                                network_apply = ui.button('Apply Network Policy', icon='settings_ethernet').props('outline no-caps')
                                network_state = {'saved': bool(config.network), 'dirty': False, 'updating': False}
                                def mark_network_dirty(_event) -> None:
                                    if not network_state['updating']:
                                        network_state['dirty'] = bool(network_switch.value) != network_state['saved']
                                network_switch.on_value_change(mark_network_dirty)

                            with ui.column().classes('hy-env-danger w-full p-4 gap-3'):
                                ui.label('Danger Zone').classes('font-semibold text-negative')
                                ui.label('These actions rebuild VM-owned state. Files/ and private chat worktrees are preserved.').classes('text-xs hy-muted')
                                with ui.row().classes('gap-2 flex-wrap'):
                                    reset_button = ui.button('Factory Reset', icon='restart_alt').props('outline no-caps color=negative')
                                    rebuild_button = ui.button('Rebuild VM', icon='replay').props('outline no-caps color=negative')

                    with ui.tab_panel(snapshots_tab).classes('p-0'):
                        with ui.column().classes('hy-env-width p-4 gap-4'):
                            with ui.row().classes('w-full items-center gap-2'):
                                with ui.column().classes('gap-0'):
                                    ui.label('Snapshots').classes('text-lg font-semibold')
                                    ui.label('Snapshots checkpoint this VM’s storage. Workspace source files are never rolled back.').classes('text-xs hy-muted')
                                    if config.files_mode == 'copy' and config.provider == 'lima':
                                        ui.label('The separate project copy is stored outside the VM disk and is not rolled back by a VM snapshot.').classes('text-xs hy-muted')
                                ui.space()
                                take_snapshot_button = ui.button('Take Snapshot', icon='camera').props('unelevated no-caps')
                            snapshot_operation_label = ui.label('').classes('text-sm hy-muted').style('white-space:pre-wrap')
                            snapshot_list_area = ui.column().classes('w-full gap-2')

                def queue_action(kind: str, **payload: Any) -> bool:
                    try:
                        if not ENVIRONMENT_OPERATIONS.start(ws.root, kind, environment_id=environment_id, **payload):
                            return False
                    except Exception as exc:
                        ui.notify(str(exc), type='warning')
                        return False
                    if not detail_panel.is_deleted:
                        apply_operation_state()
                    self._refresh_sidebar_busy_indicators()
                    return True

                async def manage_optional_tools_dialog() -> None:
                    if manage_tools_button is None:
                        return
                    if ENVIRONMENT_OPERATIONS.is_busy(ws.root, environment_id=environment_id):
                        ui.notify('Wait for the current environment operation to finish.', type='warning')
                        return
                    if active_work(ws.root, environment_id=environment_id):
                        ui.notify('Finish or stop active agents, terminals, and workspace processes before changing optional tools.', type='warning')
                        return
                    latest = manager.config
                    if latest is None:
                        ui.notify('Workspace environment definition is missing.', type='negative')
                        return
                    dialog_preset = get_preset(latest.preset)
                    available = tuple(dialog_preset.optional_tool_ids)
                    configured = tuple(latest.optional_tools or ())
                    existing = tuple(available if '*' in configured else (tool for tool in available if tool in configured))
                    chosen = set(existing)
                    status_labels: dict[str, Any] = {}
                    checkboxes: dict[str, Any] = {}
                    state_label = None
                    supplemental = tuple(dialog_preset.supplemental_tools)
                    installed_bundles: set[str] = set()
                    inspection_ready = False
                    remove_bundles = removal_preview = None

                    def tool_label(tool_id: str) -> str:
                        return {
                            'ghidra': 'Ghidra headless',
                            'rea': 'REA CLI (Reverse Engineer Anything)',
                            'python-re': 'Python RE environments (angr, capa, FLOSS, firmware, Frida)',
                        }.get(tool_id, tool_id)

                    def removal_candidates() -> tuple[str, ...]:
                        return tuple(tool for tool in supplemental if tool in installed_bundles and tool not in chosen)

                    def update_removal_preview() -> None:
                        if remove_bundles is None:
                            return
                        candidates = removal_candidates()
                        eligible = bool(inspection_ready and candidates)
                        remove_bundles.set_enabled(eligible)
                        remove_bundles.set_visibility(not inspection_ready or bool(candidates))
                        if not eligible:
                            remove_bundles.set_value(False)
                        if inspection_ready:
                            removal_preview.set_text(
                                'Would uninstall: ' + ', '.join(tool_label(tool) for tool in candidates) + '.'
                                if candidates else 'No installed managed bundles are deselected.'
                            )

                    def set_choice(tool_id: str, enabled: bool) -> None:
                        if enabled:
                            chosen.add(tool_id)
                        else:
                            chosen.discard(tool_id)
                        if state_label is not None:
                            state_label.set_text(f'{len(chosen)}/{len(available)} selected')
                        update_removal_preview()

                    def set_all(values: tuple[str, ...]) -> None:
                        chosen.clear()
                        chosen.update(values)
                        for tool_id, box in checkboxes.items():
                            box.set_value(tool_id in chosen)
                        if state_label is not None:
                            state_label.set_text(f'{len(chosen)}/{len(available)} selected')
                        update_removal_preview()

                    with make_details_dialog() as dialog, ui.card().classes('w-[760px] max-w-[96vw] gap-3').style('max-height:88vh'):
                        with ui.row().classes('w-full items-center gap-2'):
                            ui.icon('construction', size='22px')
                            ui.label('Manage Optional Tools').classes('text-lg font-semibold')
                            ui.space()
                            ui.button(icon='close', on_click=dialog.close).props('flat round dense aria-label="Close dialog"')
                        ui.label(
                            'This changes optional tools only. Required workspace/runtime packages cannot be deselected here.'
                        ).classes('text-sm')
                        if 'rea' in available:
                            ui.label(
                                'REA runs inside this VM. Apply with REA selected to install or update it; '
                                'Shell commands and Long-running processes permissions control model use.'
                            ).classes('text-xs hy-muted')
                        if latest.provider == 'openwrt':
                            ui.label(
                                'Verified setup packages download through HarnessyXO, including when guest outbound network is off.'
                            ).classes('text-xs hy-muted')
                        elif latest.network:
                            ui.label(
                                'Outbound network is enabled. Missing selected tools can be installed immediately if the VM is running.'
                            ).classes('text-xs hy-muted')
                        else:
                            ui.label(
                                'Outbound network is OFF. HarnessyXO will save your selection but will not attempt optional tool downloads until outbound access is enabled.'
                            ).classes('text-xs text-warning font-semibold')
                        with ui.row().classes('w-full items-center gap-2 flex-wrap'):
                            state_label = ui.label(f'{len(chosen)}/{len(available)} selected').classes('text-xs font-semibold')
                            ui.button('Select all', on_click=lambda: set_all(available)).props('flat dense no-caps')
                            ui.button('Clear optional', on_click=lambda: set_all(())).props('flat dense no-caps')
                            ui.space()
                            inspection_label = ui.label('Checking installed state…').classes('text-xs hy-muted')
                        with ui.scroll_area().classes('w-full').style('height:480px;max-height:55vh'):
                            with ui.column().classes('w-full gap-1 pr-2'):
                                for index, tool_id in enumerate(available):
                                    if index and tool_id in supplemental and available[index - 1] not in supplemental:
                                        ui.separator().classes('my-2')
                                        ui.label('HarnessyXO supplemental bundles').classes('text-xs font-semibold hy-muted')
                                    with ui.row().classes('w-full items-start gap-3 py-1 no-wrap'):
                                        box = ui.checkbox(tool_label(tool_id), value=tool_id in chosen).classes('text-sm').style('flex:1;min-width:0')
                                        checkboxes[tool_id] = box
                                        box.on_value_change(lambda e, tid=tool_id: set_choice(tid, bool(e.value)))
                                        status_labels[tool_id] = ui.label('Checking…').classes('text-xs hy-muted text-right').style('width:210px;white-space:pre-line')
                        if supplemental:
                            remove_bundles = ui.checkbox('Uninstall deselected managed bundles', value=False).classes('text-xs')
                            remove_bundles.disable()
                            removal_preview = ui.label('Checking installed managed bundles…').classes('text-xs hy-muted').style('overflow-wrap:anywhere')
                        ui.label(
                            'For safety, deselecting distro package-manager tools does not automatically uninstall them or their dependencies. '
                            'It stops HarnessyXO selecting/reinstalling them.' +
                            (' The uninstall option applies only to HarnessyXO-owned /opt bundles.' if supplemental else '')
                        ).classes('text-xs hy-muted')
                        with ui.row().classes('w-full justify-end gap-2'):
                            ui.button('Cancel', on_click=dialog.close).props('flat no-caps')
                            def apply_tools() -> None:
                                selected = tuple(tool for tool in available if tool in chosen)
                                removed_owned = removal_candidates()
                                remove_owned = bool(remove_bundles is not None and remove_bundles.value and inspection_ready and removed_owned)

                                def commit() -> None:
                                    current_config = manager.config
                                    if current_config is None or current_config.preset != dialog_preset.id:
                                        ui.notify('This VM’s tool preset changed. Reopen Manage Optional Tools to review its current choices.', type='warning')
                                        return
                                    dialog.close()
                                    removal_options = {'expected_removed_bundles': removed_owned} if remove_owned else {}
                                    queue_action(
                                        'tools', optional_tools=selected, expected=existing,
                                        expected_preset=dialog_preset.id,
                                        remove_deselected_bundles=remove_owned,
                                        **removal_options,
                                    )

                                if remove_owned and removed_owned:
                                    with make_details_dialog() as confirm_dialog, ui.card().classes('w-[560px] max-w-[94vw] gap-3'):
                                        ui.label('Remove supplemental bundles?').classes('text-lg font-semibold text-negative')
                                        ui.label(
                                            'HarnessyXO will delete the managed installation for: ' +
                                            ', '.join(tool_label(tool) for tool in removed_owned) + '.'
                                        ).classes('text-sm')
                                        ui.label('This removes only HarnessyXO-owned supplemental /opt bundles. Workspace Files/ and distro package-manager tools are not deleted.').classes('text-xs hy-muted')
                                        with ui.row().classes('w-full justify-end gap-2'):
                                            ui.button('Cancel', on_click=confirm_dialog.close).props('flat no-caps')
                                            def confirm_remove() -> None:
                                                confirm_dialog.close()
                                                commit()
                                            ui.button('Remove Bundles and Apply', icon='delete_outline', on_click=confirm_remove).props('unelevated no-caps color=negative')
                                    confirm_dialog.open()
                                    return
                                commit()
                            ui.button('Apply / Retry Selected', icon='construction', on_click=apply_tools).props('unelevated no-caps')
                    dialog.open()

                    try:
                        inspection = await manager.provider().optional_tool_status()
                        current_status = await manager.provider().status()
                        if not current_status.running:
                            inspection_label.set_text('VM stopped · install status not probed')
                            if removal_preview is not None:
                                removal_preview.set_text('Uninstalling managed bundles requires a running VM and verified installed state.')
                        else:
                            inspection_label.set_text('Installed state read from running VM')
                            installed_bundles.update(
                                tool for tool in supplemental
                                if str(inspection.get(tool, {}).get('state') or 'unknown') in {'installed', 'partial'}
                            )
                            inspection_ready = all(
                                str(inspection.get(tool, {}).get('state') or 'unknown') in {'installed', 'partial', 'missing'}
                                for tool in supplemental
                            )
                            update_removal_preview()
                            if not inspection_ready and removal_preview is not None:
                                removal_preview.set_text('Installed state unavailable for some managed bundles. Uninstalling is disabled.')
                        for tool_id in available:
                            row = inspection.get(tool_id, {})
                            state = str(row.get('state') or 'unknown')
                            detail = str(row.get('detail') or '')
                            prefix = {
                                'installed': 'Installed', 'missing': 'Not installed',
                                'partial': 'Partial', 'unknown': 'Unknown',
                            }.get(state, state.title())
                            if not latest.network and latest.provider != 'openwrt' and state != 'installed' and tool_id in chosen:
                                prefix += ' · pending network'
                            status_labels[tool_id].set_text(prefix + (f'\n{detail}' if detail else ''))
                    except Exception as exc:
                        inspection_label.set_text('Could not inspect installed tools')
                        if remove_bundles is not None:
                            inspection_ready = False
                            installed_bundles.clear()
                            update_removal_preview()
                            removal_preview.set_text('Installed state unavailable. Uninstalling managed bundles is disabled.')
                        for label in status_labels.values():
                            label.set_text('Status unavailable')
                        log_event('runtime', 'optional_tool_inspection_failed', workspace=str(ws.root), error=str(exc))

                if manage_tools_button is not None:
                    manage_tools_button.on('click', manage_optional_tools_dialog)

                def network_dialog() -> None:
                    target = bool(network_switch.value)
                    expected = bool(network_state['saved'])
                    if target == expected:
                        return
                    if active_work(ws.root, environment_id=environment_id):
                        ui.notify('Finish or stop active agents, tools, and workspace processes before changing network policy.', type='warning')
                        return
                    with make_details_dialog() as dialog, ui.card().classes('w-[540px] max-w-[94vw] gap-3'):
                        ui.label('Apply network policy?').classes('text-lg font-semibold')
                        ui.label(f'Enable {network_label.lower()}.' if target else f'Disable {network_label.lower()}.').classes('text-sm font-semibold')
                        ui.label(network_description).classes('text-sm')
                        ui.label('An idle running VM may restart to apply the policy. A stopped VM stays stopped. Finish active work first. VM storage and workspace source are preserved.').classes('text-sm')
                        with ui.row().classes('w-full justify-end gap-2'):
                            ui.button('Cancel', on_click=dialog.close).props('flat no-caps')
                            def confirm() -> None:
                                dialog.close()
                                queue_action('network', enabled=target, expected=expected)
                            ui.button('Apply', on_click=confirm).props('unelevated no-caps')
                    dialog.open()
                network_apply.on('click', network_dialog)

                def destructive_dialog(kind: str, title: str, body: str, confirm_text: str) -> None:
                    with make_details_dialog() as dialog, ui.card().classes('w-[520px] max-w-[94vw] gap-3'):
                        ui.label(title).classes('text-lg font-semibold text-negative')
                        ui.label(body).classes('text-sm')
                        ui.label('Files/ and private chat worktrees will be preserved.').classes('text-xs hy-muted')
                        with ui.row().classes('w-full justify-end gap-2'):
                            ui.button('Cancel', on_click=dialog.close).props('flat no-caps')
                            def confirm() -> None:
                                dialog.close()
                                queue_action(kind)
                            ui.button(confirm_text, on_click=confirm).props('unelevated no-caps color=negative')
                    dialog.open()

                def snapshot_dialog() -> None:
                    with make_details_dialog() as dialog, ui.card().classes('w-[520px] max-w-[94vw] gap-3'):
                        ui.label('Take Snapshot').classes('text-lg font-semibold')
                        ui.label('Create a restorable checkpoint of the VM environment. Files/ and private chat worktrees stay live and are not included.').classes('text-sm hy-muted')
                        name_input = ui.input('Snapshot name (optional)').classes('w-full').props('autofocus')
                        ui.label('Leave the name blank to let HarnessyXO generate one automatically.').classes('text-xs hy-muted')
                        with ui.row().classes('w-full justify-end gap-2'):
                            ui.button('Cancel', on_click=dialog.close).props('flat no-caps')
                            def confirm() -> None:
                                name = str(name_input.value or '').strip()
                                dialog.close()
                                queue_action('snapshot', name=name)
                            ui.button('Take Snapshot', icon='camera', on_click=confirm).props('unelevated no-caps')
                    dialog.open()

                def restore_dialog(tag_name: str) -> None:
                    with make_details_dialog() as dialog, ui.card().classes('w-[520px] max-w-[94vw] gap-3'):
                        ui.label('Restore Snapshot').classes('text-lg font-semibold')
                        ui.label(f'Restore VM state from “{tag_name}”?').classes('text-sm')
                        ui.label('Files/ and private chat worktrees are live and will not be rolled back.').classes('text-xs hy-muted')
                        with ui.row().classes('w-full justify-end gap-2'):
                            ui.button('Cancel', on_click=dialog.close).props('flat no-caps')
                            def confirm() -> None:
                                dialog.close()
                                queue_action('restore', tag=tag_name)
                            ui.button('Restore', icon='restore', on_click=confirm).props('unelevated no-caps')
                    dialog.open()

                if not embedded:
                    start_button.on('click', lambda: queue_action('start'))
                    stop_button.on('click', lambda: queue_action('stop'))
                reset_button.on('click', lambda: destructive_dialog(
                    'reset', 'Factory Reset Environment',
                    'Reset the VM environment to its backend factory state, then start and verify it again?',
                    'Factory Reset',
                ))
                rebuild_button.on('click', lambda: destructive_dialog(
                    'rebuild', 'Rebuild VM',
                    'Delete and recreate the VM from its HarnessyXO environment definition?',
                    'Rebuild VM',
                ))
                take_snapshot_button.on('click', snapshot_dialog)

                last_snapshot_signature = {'value': None}
                latest_status: dict[str, Any] = {'known': False}
                restore_buttons: list[Any] = []

                def _format_operation_seconds(seconds: float | int | None) -> str:
                    try:
                        value = max(0, int(float(seconds or 0)))
                    except (TypeError, ValueError):
                        value = 0
                    minutes, secs = divmod(value, 60)
                    hours, minutes = divmod(minutes, 60)
                    if hours:
                        return f'{hours}h {minutes:02d}m'
                    if minutes:
                        return f'{minutes}m {secs:02d}s'
                    return f'{secs}s'

                def apply_operation_state() -> None:
                    op = ENVIRONMENT_OPERATIONS.state(ws.root, environment_id=environment_id)
                    busy = bool(op.busy)
                    if not embedded:
                        show_operation = busy or bool(op.error or op.success)
                        operation_banner.set_visibility(show_operation)
                        operation_spinner.set_visibility(busy)
                        operation_icon.set_visibility(show_operation and not busy)
                        operation_detail.set_visibility(busy and bool(op.detail))
                        operation_progress.set_visibility(busy)
                        operation_timing.set_visibility(busy)
                        if busy:
                            operation_icon.props('name=hourglass_top')
                            operation_message.set_text(op.message or 'Working…')
                            operation_detail.set_text(op.detail or '')
                            operation_error.set_text('')
                            status_label.set_text(op.message or {
                                'start': 'Starting…',
                                'stop': 'Stopping…',
                                'snapshot': 'Snapshotting…',
                                'restore': 'Restoring…',
                                'reset': 'Resetting…',
                                'rebuild': 'Rebuilding…',
                                'tools': 'Updating optional tools…',
                                'resources': 'Applying VM resources…',
                            }.get(op.action, 'Working…'))

                            if op.progress_percent is None:
                                operation_progress.props(add='indeterminate')
                            else:
                                operation_progress.props(remove='indeterminate')
                                operation_progress.set_value(max(0.0, min(1.0, float(op.progress_percent) / 100.0)))

                            now = time.time()
                            elapsed = max(0.0, now - float(op.started_at or now))
                            stage_elapsed = max(0.0, now - float(op.stage_started_at or op.started_at or now))
                            timing_parts = [f'Elapsed {_format_operation_seconds(elapsed)}']
                            if op.step_total and op.step_index:
                                timing_parts.append(f'Stage {op.step_index}/{op.step_total}')
                            if op.progress_percent is not None:
                                timing_parts.append(f'Workflow {float(op.progress_percent):.0f}%')
                            if op.stage_progress_percent is not None:
                                timing_parts.append(f'Lima {float(op.stage_progress_percent):.0f}%')
                            timing_parts.append(f'This stage {_format_operation_seconds(stage_elapsed)}')
                            expected = float(op.expected_total_seconds or 0)
                            if expected > 0:
                                if elapsed < expected:
                                    timing_parts.append(f'ETA ~{_format_operation_seconds(expected - elapsed)}')
                                else:
                                    timing_parts.append(f'Recent median {_format_operation_seconds(expected)}')
                            else:
                                timing_parts.append('ETA learning from completed runs')
                            remaining_stage_deadline = max(0.0, float(op.stage_deadline or 0) - now) if op.stage_deadline else 0.0
                            if remaining_stage_deadline:
                                timing_parts.append(f'Stage timeout {_format_operation_seconds(remaining_stage_deadline)}')
                            remaining_deadline = max(0.0, float(op.deadline or 0) - now) if op.deadline else 0.0
                            if remaining_deadline:
                                timing_parts.append(f'Operation timeout {_format_operation_seconds(remaining_deadline)}')
                            operation_timing.set_text(' · '.join(timing_parts))
                        elif op.error:
                            operation_icon.props('name=error_outline color=negative')
                            operation_message.set_text('Environment operation failed')
                            operation_detail.set_text('')
                            operation_error.set_text(op.error)
                        elif op.success:
                            operation_icon.props('name=check_circle color=primary')
                            operation_message.set_text(op.success)
                            operation_detail.set_text('')
                            operation_error.set_text('')
                        else:
                            operation_icon.props('name=info color=primary')
                            operation_message.set_text('Environment status')
                            operation_detail.set_text('')
                            operation_error.set_text('')

                    saved_config = manager.config
                    resource_editor.sync(saved_config, {**latest_status, 'resource_operation': op.action == 'resources' and not embedded},
                                         busy=busy, active=bool(active_work(ws.root, environment_id=environment_id)))
                    if saved_config is not None:
                        saved_network = bool(saved_config.network)
                        if preset.optional_tool_ids:
                            saved_optional = tuple(
                                preset.optional_tool_ids if '*' in tuple(saved_config.optional_tools or ())
                                else (tool for tool in preset.optional_tool_ids if tool in set(saved_config.optional_tools or ()))
                            )
                            suffix = '' if saved_network or saved_config.provider == 'openwrt' else ' · downloads skipped while outbound is off'
                            if optional_tools_summary_label is not None:
                                optional_tools_summary_label.set_text(
                                    f'Optional tools selected: {len(saved_optional)}/{len(preset.optional_tool_ids)}{suffix}'
                                )
                            if optional_manage_summary is not None:
                                optional_manage_summary.set_text(
                                    f'{len(saved_optional)}/{len(preset.optional_tool_ids)} selected for this VM.'
                                )
                        if saved_network != network_state['saved']:
                            network_state['saved'] = saved_network
                            if not network_state['dirty'] or (op.action == 'network' and op.status == 'succeeded'):
                                network_state['updating'] = True
                                network_switch.value = saved_network
                                network_state['updating'] = False
                                network_state['dirty'] = False
                        network_status_label.set_text(f'{network_prefix} enabled' if saved_network else f'{network_prefix} disabled')
                    network_switch.disable() if busy else network_switch.enable()
                    if manage_tools_button is not None:
                        manage_tools_button.disable() if busy or bool(active_work(ws.root, environment_id=environment_id)) else manage_tools_button.enable()
                        manage_tools_button.props(add='loading') if busy and op.action == 'tools' and not embedded else manage_tools_button.props(remove='loading')
                    can_apply_network = not busy and not active_work(ws.root, environment_id=environment_id) and bool(network_switch.value) != network_state['saved']
                    network_apply.enable() if can_apply_network else network_apply.disable()
                    network_apply.props(add='loading') if busy and op.action == 'network' and not embedded else network_apply.props(remove='loading')

                    known = bool(latest_status.get('known'))
                    running = bool(latest_status.get('running'))
                    ready = bool(latest_status.get('ready'))
                    active = bool(active_work(ws.root, environment_id=environment_id))
                    action_buttons = {
                        'reset': reset_button, 'rebuild': rebuild_button,
                        'snapshot': take_snapshot_button,
                    }
                    if not embedded:
                        action_buttons.update(start=start_button, stop=stop_button)
                    for button in (*action_buttons.values(), *restore_buttons):
                        button.classes(add='hy-vm-busy-action')
                        button.props(remove='loading')
                        button.set_enabled(known and not busy and not active)
                    active_button = action_buttons.get(op.action) if busy else None
                    if active_button is not None and not embedded:
                        active_button.props(add='loading')
                    reset_button.set_text('Resetting…' if busy and op.action == 'reset' else 'Factory Reset')
                    rebuild_button.set_text('Rebuilding…' if busy and op.action == 'rebuild' else 'Rebuild VM')
                    take_snapshot_button.set_text('Creating…' if busy and op.action == 'snapshot' else 'Take Snapshot')
                    if not embedded:
                        open_terminal_button.set_enabled(known and ready and not busy)
                        start_button.set_enabled(known and not busy and not active and not (running and ready))
                        stop_button.set_enabled(known and running and not busy and not active)
                        start_button.set_text('Starting…' if busy and op.action == 'start' else 'Checking…' if not known else 'Retry Setup' if running and not ready else 'Start')
                        stop_button.set_text('Stopping…' if busy and op.action == 'stop' else 'Stop')
                    if busy and op.action == 'snapshot':
                        snapshot_bits = [op.message or 'Creating snapshot…']
                        if op.detail:
                            snapshot_bits.append(op.detail)
                        snapshot_operation_label.set_text(' · '.join(snapshot_bits))
                    else:
                        snapshot_operation_label.set_text((op.error or op.success or '') if not embedded or op.action in {'snapshot', 'restore'} else '')

                def render_snapshots(snapshots: list[str] | None, error: str = '') -> None:
                    signature = (tuple(snapshots or []), snapshots is None, error)
                    if signature == last_snapshot_signature['value']:
                        return
                    last_snapshot_signature['value'] = signature
                    restore_buttons.clear()
                    snapshot_list_area.clear()
                    with snapshot_list_area:
                        if error:
                            ui.label('Snapshot list could not be refreshed. ' + error).classes('text-sm text-negative').style('overflow-wrap:anywhere')
                        if snapshots is None:
                            ui.label('Snapshots unavailable — refresh/reconcile before creating another checkpoint.').classes('text-sm hy-muted')
                            return
                        if not snapshots:
                            with ui.column().classes('w-full items-center py-10 gap-2'):
                                ui.icon('camera_alt', size='34px').classes('hy-muted')
                                ui.label('No snapshots yet').classes('font-semibold')
                                ui.label('Use Take Snapshot before risky VM changes.').classes('text-xs hy-muted')
                            return
                        for snapshot_tag in snapshots:
                            with ui.row().classes('hy-env-snapshot-row w-full items-center p-3 gap-3'):
                                ui.icon('camera_alt', size='20px')
                                ui.label(snapshot_tag).classes('font-medium').style('flex:1;min-width:0;overflow-wrap:anywhere')
                                restore_button = ui.button('Restore', icon='restore', on_click=lambda tag=snapshot_tag: restore_dialog(tag)).props('flat no-caps')
                                restore_buttons.append(restore_button)
                                if ENVIRONMENT_OPERATIONS.is_busy(ws.root, environment_id=environment_id):
                                    restore_button.disable()

                async def refresh_environment() -> None:
                    # Every page observes the same process-owned status cache. A
                    # restored tab/client therefore cannot create another Lima
                    # poller, and lifecycle operations suppress controller polls.
                    if detail_panel.is_deleted:
                        environment_poll.cancel()
                        return
                    try:
                        info = await ENVIRONMENT_STATUS.get(ws.root, environment_id=environment_id)
                        if detail_panel.is_deleted:
                            environment_poll.cancel()
                            return
                        if info is not None:
                            status = dict(info.get('status') or {})
                            latest_status.clear()
                            latest_status.update(status)
                            latest_status['known'] = not bool(info.get('_status_poll_error'))
                            running = bool(status.get('running'))
                            ready = bool(status.get('ready'))
                            if status_label is not None:
                                if ready:
                                    status_label.set_text('Ready')
                                elif running:
                                    phase = str(status.get('phase') or 'running_not_ready').replace('_', ' ').title()
                                    status_label.set_text(f'Running · {phase}')
                                else:
                                    status_label.set_text(str(status.get('state') or 'stopped').replace('_', ' ').title())
                            detail = str(status.get('error') or status.get('detail') or '')
                            poll_error = str(info.get('_status_poll_error') or '')
                            if poll_error:
                                detail = (detail + f'\nStatus refresh: {poll_error}').strip()
                            if readiness_detail is not None:
                                readiness_detail.set_text(detail if detail not in {'Running', 'Stopped'} else '')
                            disk_usage_label.set_text(f"VM storage on host: {_human_size(int(info.get('vm_storage_bytes') or 0))}")
                            raw_snapshots = info.get('snapshots')
                            render_snapshots(list(raw_snapshots) if isinstance(raw_snapshots, list) else None, str(info.get('_snapshot_list_error') or ''))
                    except RuntimeError as exc:
                        if _is_stale_ui_error(exc):
                            return
                        latest_status.clear()
                        latest_status['known'] = False
                        try:
                            if status_label is not None:
                                status_label.set_text('Unavailable')
                            if readiness_detail is not None:
                                readiness_detail.set_text(str(exc))
                        except RuntimeError as update_exc:
                            if _is_stale_ui_error(update_exc):
                                return
                            raise
                    except Exception as exc:
                        latest_status.clear()
                        latest_status['known'] = False
                        try:
                            if status_label is not None:
                                status_label.set_text('Unavailable')
                            if readiness_detail is not None:
                                readiness_detail.set_text(str(exc))
                        except RuntimeError as update_exc:
                            if _is_stale_ui_error(update_exc):
                                return
                            raise
                    try:
                        apply_operation_state()
                        self._refresh_sidebar_busy_indicators()
                    except RuntimeError as exc:
                        if not _is_stale_ui_error(exc):
                            raise

                apply_operation_state()
                environment_poll = ui.timer(0.75, refresh_environment, immediate=True)

    # --------------------------------------------------------- zip/downloads
    def _render_artifacts_tab(self, tab: OpenTab, ws: WorkspaceStore) -> None:
        with ui.column().classes('hy-tool-panel w-full no-wrap gap-0'):
            with ui.row().classes('w-full items-center px-4 py-2').style('border-bottom:1px solid var(--hy-border)'):
                ui.label(f'{ws.name} · ZIP / Downloads').classes('font-semibold')
            with ui.column().classes('w-full p-4 gap-3 overflow-y-auto').style('flex:1'):
                ui.label('Package a Project / Chat directory').classes('font-semibold')
                chats = ws.list_chats()
                if chats:
                    chat_select = ui.select(options=make_choice_options(chats, lambda c: c.id, lambda c: f'{c.title} ({c.id[:6]})'), value=chats[0].id, label='Project / Chat').classes('w-full max-w-xl')
                    async def package() -> None:
                        try:
                            out = await asyncio.to_thread(ws.package_active_root, str(chat_select.value), None)
                            ui.notify(f'Created {out.name}', type='positive')
                            self.refresh_tabs()
                        except Exception as exc:
                            ui.notify(str(exc), type='negative')
                    ui.button('Create ZIP', icon='archive', on_click=package).props('unelevated no-caps')
                else:
                    ui.label('Create a Project / Chat first.').classes('hy-muted')
                ui.separator()
                ui.label('Artifacts').classes('font-semibold')
                artifacts: list[dict[str, Any]] = []
                for c in chats:
                    artifacts.extend(ws.list_artifacts(c.id))
                artifacts.sort(key=lambda x: x['created_at'], reverse=True)
                if not artifacts:
                    ui.label('No generated ZIPs yet.').classes('hy-muted')
                for item in artifacts:
                    with ui.row().classes('hy-artifact items-center gap-2'):
                        ui.icon('archive', size='18px')
                        ui.label(item['name'])
                        ui.label(item['created_at']).classes('text-xs hy-muted')
                        ui.button(icon='download', on_click=lambda p=item['path']: ui.download.file(p)).props('flat round dense')

    # --------------------------------------------------------------- settings
    def open_settings(self, initial_tab: str = 'General') -> None:
        self.settings = self.machine.load_settings()
        original_settings = deepcopy(self.settings)
        draft = deepcopy(original_settings)
        collectors: list[Any] = []
        instruction_writers: list[Any] = []
        dirty = {'value': False}
        dirty_label_ref: dict[str, Any] = {}

        def mark_dirty() -> None:
            dirty['value'] = True
            label = dirty_label_ref.get('label')
            if label is not None:
                label.set_text('Unsaved changes')

        def watch(*controls) -> None:
            for control in controls:
                control.on_value_change(lambda _e: mark_dirty())

        with ui.dialog().props('persistent') as dialog, ui.card().classes('hy-settings-card max-w-full'):
            with ui.row().classes('hy-settings-header w-full items-center'):
                ui.label('Settings').classes('text-xl font-semibold')
                ui.label(f'v{__version__}').classes('text-xs hy-muted')
                ui.space()
                dirty_label_ref['label'] = ui.label('').classes('text-xs hy-muted')

                async def close_dialog() -> None:
                    dialog.close()

                async def request_close() -> None:
                    if not dirty['value']:
                        await close_dialog()
                        return
                    with ui.dialog() as warn, ui.card().classes('w-[480px] max-w-[92vw]'):
                        ui.label('Discard unsaved changes?').classes('text-lg font-semibold')
                        ui.label('Unsaved preferences will be discarded. Confirmed installations and account actions have been applied and will not be undone.').classes('text-sm hy-muted')
                        with ui.row().classes('w-full justify-end'):
                            ui.button('Keep editing', on_click=warn.close).props('flat no-caps')
                            async def discard() -> None:
                                warn.close()
                                await close_dialog()
                            ui.button('Discard', on_click=discard).props('unelevated no-caps color=negative')
                    warn.open()

                ui.button(icon='close', on_click=request_close).props('flat round dense aria-label="Close settings"')

            section_names = ['General', 'Models', 'Project / Chat', 'Agent / Tools', 'Notifications', 'Server / Network', 'Users / Password']
            with ui.row().classes('hy-settings-body w-full no-wrap gap-0'):
                with ui.tabs().props('vertical dense').classes('hy-settings-nav') as sections:
                    section_tabs = {name: ui.tab(name) for name in section_names}
                ui.select(section_names, label='Settings section').props('outlined dense').classes('hy-settings-compact-nav').bind_value(sections)
                # Use names consistently across NiceGUI versions: older builds
                # retain an initial Tab object in .value until the first click.
                target = initial_tab if initial_tab in section_tabs else 'General'
                with ui.tab_panels(sections, value=target).props('vertical').classes('hy-settings-content'):
                    with ui.tab_panel(section_tabs['General']):
                        self._settings_section_header('General', 'Application appearance and login management.')
                        ui.label(f'Settings folder: {self.machine.root}').classes('text-xs hy-muted mb-3 hy-wrap-anywhere')
                        general = draft['general']
                        dark = ui.switch('Dark mode', value=bool(general.get('dark', False)))
                        ui.label('Theme changes apply immediately after Save.').classes('text-xs hy-muted')
                        with ui.column().classes('hy-settings-section w-full gap-1 mt-4').props(
                            'data-hy-prompt-nav-settings=1'
                        ):
                            ui.label('Prompt navigator').classes('font-semibold')
                            navigator_visible = ui.switch(
                                'Show prompt navigator', value=bool(general.get('prompt_navigator', True)),
                            ).props('data-hy-prompt-nav-visible=1')
                            navigator_options = normalize_prompt_navigator_options(
                                general.get('prompt_navigator_options'),
                            )
                            ui.label(
                                'Grey squares are user prompts. Purple squares open the selected events between '
                                'prompts; their size grows slightly with the number of entries. Scroll the '
                                'navigator for long chats. Icons and counts appear inside the menu.'
                            ).classes('text-xs hy-muted')
                            navigator_labels = {
                                'bookmarks': 'Show bookmarks',
                                'completion_check': 'Completion Check',
                                'error': 'Past errors / denied tools',
                                'context': 'Context tuning indicators',
                                'attention': 'Needs attention indicators',
                                'stopped': 'Stopped run indicators',
                                'recovery': 'Recovery indicators',
                                'approval': 'Waiting for tool approval',
                            }
                            navigator_controls = {
                                key: ui.checkbox(label, value=bool(navigator_options[key])).props(
                                    f'data-hy-prompt-nav-option={key}'
                                ) for key, label in navigator_labels.items()
                            }
                            ui.label(
                                'These choices affect only the navigator. Hiding markers or indicators does not '
                                'remove saved history or hide approval requests in the chat. Historical indicators '
                                'summarize saved events. Completion Check adds checks to the purple event menu; selecting one '
                                'jumps directly to that check’s bubble.'
                            ).classes('text-xs hy-muted')

                            def update_navigator_controls(_event=None) -> None:
                                for control in navigator_controls.values():
                                    control.set_enabled(bool(navigator_visible.value))

                            navigator_visible.on_value_change(update_navigator_controls)
                            update_navigator_controls()
                            watch(navigator_visible, *navigator_controls.values())
                            collectors.append(lambda: general.update({
                                'prompt_navigator': bool(navigator_visible.value),
                                'prompt_navigator_options': {
                                    'layout': 'grouped',
                                    **{key: bool(control.value) for key, control in navigator_controls.items()},
                                },
                            }))
                        timeout_options = {
                            0: 'Never', 15: '15 minutes', 30: '30 minutes', 60: '1 hour',
                            360: '6 hours', 720: '12 hours', 1440: '24 hours',
                            10080: '7 days', 43200: '30 days',
                        }
                        timeout_minutes = int(general.get('login_session_timeout_minutes', 0))
                        if timeout_minutes not in timeout_options:
                            timeout_options[timeout_minutes] = f'{timeout_minutes:,} minutes'
                        login_timeout = ui.select(
                            timeout_options, value=timeout_minutes, label='Login session timeout',
                        ).props('outlined dense data-hy-login-timeout=1').classes('w-full mt-3')
                        ui.label(
                            'Never disables automatic sign-out. A timed session starts at sign-in; '
                            'changing this setting restarts the timer for currently valid sessions when you Save. '
                            'This applies to all users, and is not an inactivity timer.'
                        ).classes('text-xs hy-muted')
                        ui.label(
                            'Logout, account changes and restarting HarnessyXO still end sessions.'
                        ).classes('text-xs hy-muted')
                        ui.label('Manage accounts in the Users / Password section of Settings.').classes('text-xs hy-muted')
                        watch(dark, login_timeout)
                        collectors.append(lambda: general.update({
                            'dark': bool(dark.value),
                            'login_session_timeout_minutes': int(login_timeout.value),
                        }))

                    with ui.tab_panel(section_tabs['Models']):
                        self._settings_section_header('Models', 'Configure model connections, generation settings, and capabilities.')
                        self._build_models_settings_panel(draft, collectors, mark_dirty)

                    with ui.tab_panel(section_tabs['Project / Chat']):
                        self._settings_section_header('Project / Chat', 'Composer behaviour and live-output preferences.')
                        chat_general = draft['general']
                        with ui.column().classes('hy-settings-section w-full gap-1'):
                            ui.label('Composer').classes('font-semibold')
                            enter = ui.switch('Enter sends message', value=bool(chat_general.get('enter_to_send', True)))
                            ui.label('When disabled, Cmd+Enter / Ctrl+Enter sends. Shift+Enter always inserts a newline.').classes('text-xs hy-muted')
                            watch(enter)
                            collectors.append(lambda: chat_general.update({'enter_to_send': bool(enter.value)}))

                        with ui.column().classes('hy-settings-section w-full gap-1 mt-4'):
                            ui.label('Live output').classes('font-semibold')
                            ui.label('Thinking and tool activity use collapsible live previews. Scroll up to read earlier output; return to the latest output to follow the active response.').classes('text-xs hy-muted')

                    with ui.tab_panel(section_tabs['Agent / Tools']):
                        self._settings_section_header('Agent / Tools', 'Configure agent behaviour, global instructions, and tool permissions.')
                        agent = draft['agent']
                        permission_labels = {
                            'filesystem_read': 'Filesystem read',
                            'filesystem_write': 'Filesystem write',
                            'attachments': 'Attachments / retrieval',
                            'memory': 'Workspace memory',
                            'shell': 'Shell commands',
                            'processes': 'Long-running processes',
                            'git_read': 'Git read',
                            'git_write': 'Git write / history changes',
                            'browser': 'Browser automation',
                            'web': 'Web access',
                            'code_intelligence': 'Code intelligence / LSP',
                            'diagnostics': 'HarnessyXO diagnostics',
                            'external_targets': 'External Targets',
                        }
                        current_permissions = agent.setdefault('tool_permissions', dict(DEFAULT_TOOL_PERMISSIONS))
